(function(root){const data={"meta":{"title":"机械工程材料","subject":"机械工程材料","total":374,"counts":{"term":50,"tf":116,"single":71,"blank":79,"essay":42,"analysis":16},"source":"《机械工程材料》试题库及答案（含详细解析·勘误版）"},"chapters":[{"id":"perf","shortTitle":"力学性能","title":"强度、塑性、硬度、韧性与疲劳","file":"机械工程材料","order":0},{"id":"crystal","shortTitle":"晶体结构与结晶","title":"晶格、缺陷、结晶与塑性变形","file":"机械工程材料","order":1},{"id":"phase","shortTitle":"铁碳相图与组织","title":"相、组织、Fe-Fe₃C 相图与转变","file":"机械工程材料","order":2},{"id":"heat","shortTitle":"钢的热处理","title":"退火、正火、淬火、回火与表面处理","file":"机械工程材料","order":3},{"id":"steel","shortTitle":"工业用钢","title":"结构钢、工具钢、不锈钢与牌号","file":"机械工程材料","order":4},{"id":"iron","shortTitle":"铸铁与有色金属","title":"石墨化、球铁、铝合金与轴承合金","file":"机械工程材料","order":5},{"id":"nonmetal","shortTitle":"非金属与选材","title":"高分子、陶瓷、复合材料与失效选材","file":"机械工程材料","order":6}],"summary":{"perf":{"single":22,"multiple":0,"tf":23,"blank":17,"term":5,"essay":10,"analysis":7},"crystal":{"single":4,"multiple":0,"tf":29,"blank":16,"term":15,"essay":3,"analysis":0},"phase":{"single":16,"multiple":0,"tf":27,"blank":23,"term":11,"essay":16,"analysis":4},"heat":{"single":16,"multiple":0,"tf":24,"blank":7,"term":13,"essay":10,"analysis":4},"steel":{"single":4,"multiple":0,"tf":2,"blank":9,"term":4,"essay":3,"analysis":1},"iron":{"single":8,"multiple":0,"tf":10,"blank":7,"term":2,"essay":0,"analysis":0},"nonmetal":{"single":1,"multiple":0,"tf":1,"blank":0,"term":0,"essay":0,"analysis":0}},"questions":[{"kind":"term","type":"term","section":"名词解释","question":"强度","answer":"材料在外力作用下抵抗变形和破坏的能力。","explanation":"定义正确。强度按受力方式分为屈服强度σs、抗拉强度σb、抗压与抗弯强度等，其共同点是材料抵抗塑性变形和断裂的能力。注意“抵抗变形”只指塑性变形，抵抗弹性变形的能力是刚度（用弹性模量E衡量），二者不能混为一谈。","erratum":"","sourceNumber":1,"id":"j0001","order":0,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"塑性变形","answer":"外力去处后不能恢复的变形称为塑性变形","explanation":"定义思路正确，但有两处表述问题：一是“外力去处”应为“去除”（笔误）；二是塑性变形是外力去除后不能恢复的残余变形，需强调“残余”。补充：塑性变形以滑移和孪生两种方式进行，这是金属能压力加工的根本原因。","erratum":"","sourceNumber":2,"id":"j0002","order":1,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"韧性","answer":"是指材料抵抗冲击载荷作用而不破坏的能力。","explanation":"定义基本正确。更严格的表述是：韧性指材料在塑性变形和断裂全过程中吸收变形功和冲击功的能力，工程上用冲击吸收功Ak或冲击韧度αk衡量。韧性同时取决于强度和塑性——强度高而塑性差的材料韧性并不好。","erratum":"","sourceNumber":3,"id":"j0003","order":2,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"疲劳强度","answer":"材料在规定次数应力循环后仍不发生断裂时的最大应力称为疲劳极限。用σ-1表示。","explanation":"方向正确，但表述不严密。σ-1是疲劳极限，指对称循环应力下经规定次数（如10^7次）循环而不发生断裂的最大应力。题干“最大应力称为疲劳极限”应补上“对称循环、规定循环基数”这一前提；否则应称“条件疲劳极限”。","erratum":"","sourceNumber":4,"id":"j0004","order":3,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"硬度","answer":"是指材料抵抗表面局部塑性变形的能力。","explanation":"定义正确。硬度是材料抵抗局部塑性变形（压入、刻划、磨损）的能力，常用布氏HBW、洛氏HRC、维氏HV表示。工程上硬度与抗拉强度近似成正比（碳钢σb≈3.5HBW），且硬度检测不破坏零件，故应用最广。","erratum":"","sourceNumber":5,"id":"j0005","order":4,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"珠光体（P）","answer":"由铁素体和渗碳体组成的机械混合物。铁素体和渗碳体呈层片状。珠光体有较高的强度和硬度，但塑性较差。","explanation":"定义正确。需强调P是“两相组织”而非“相”：其组成相为F和 Fe3C，形态为层片状。片层间距越小，相界面越多、位错运动阻力越大，强度硬度越高，同时塑性韧性也越好（S、T即更细的P）。","erratum":"","sourceNumber":6,"id":"j0006","order":5,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"奥氏体","answer":"碳在γ-Fe中的固溶体称奥氏体。用A或γ表示。","explanation":"定义正确。奥氏体是碳在γ-Fe中的间隙固溶体，面心立方晶格，晶格间隙大，溶碳能力最高可达2.11%（1148℃）。它是钢加热时的高温相、绝大多数热处理的“母相”，塑性好、强度低。","erratum":"","sourceNumber":7,"id":"j0007","order":6,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"相","answer":"是指金属或合金中凡成分相同、结构相同，并与其它部分有界面分开的均匀组成部分。","explanation":"定义正确，抓住了“成分相同、结构相同、有界面分开”三个要件。易错点：珠光体、莱氏体、贝氏体、回火索氏体属于“组织”（相的混合物），不能称“相”；相是组织的基本组成单元。","erratum":"","sourceNumber":8,"id":"j0008","order":7,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"共析反应","answer":"由特定成分的单相固态合金，在恒定的温度下，分解成两个新的，具有一定晶体结构的固相的反应。","explanation":"定义正确。共析反应即A(0.77%C)→F(0.0218%C)+Fe3C，在727℃恒温进行，属三相平衡。与共晶反应的唯一区别是反应物为固相（A）而非液相（L），两者都是“一分为二”的恒温分解反应。","erratum":"","sourceNumber":9,"id":"j0009","order":8,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"过冷度","answer":"实际结晶温度与理论结晶温度之差称为过冷度。","explanation":"定义正确，用ΔT表示。过冷度是结晶的驱动力：ΔT越大，形核率N的增长快于长大速度G，N/G 增大，晶粒细化。注意“理论结晶温度”即平衡熔点，实际结晶温度总低于它。","erratum":"","sourceNumber":10,"id":"j0010","order":9,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"渗碳体（Fe3C）","answer":"铁和碳相互作用形成的具有复杂晶格的间隙化合物。渗碳体具有很高的硬度，但塑性很差，延伸率接近于零。在钢中以片状存在或网络状存在于晶界。在莱氏体中为连续的基体，有时呈鱼骨状。","explanation":"定义正确。Fe3C是复杂斜方晶格的间隙化合物，w C=6.69%，硬度约800HBW、脆性极大、塑性近于零。其形态决定钢的性能：片状（P中）、网状（沿晶界，使钢变脆）、球状（球化退火，利于切削）最为常见。","erratum":"","sourceNumber":11,"id":"j0011","order":10,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"同素异构性","answer":"同一金属在不同温度下具有不同晶格类型的现象。","explanation":"定义正确。纯铁的同素异构转变：<912℃为α-Fe（体心立方）→912~1394℃为γ-Fe（面心立方）→1394~1538℃为δ-Fe（体心立方）。正因为存在同素异构转变，钢才能通过加热、冷却改变组织，这是热处理的根本依据。","erratum":"","sourceNumber":12,"id":"j0012","order":11,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"间隙固溶体","answer":"溶质原子分布于溶剂的晶格间隙中所形成的固溶体。","explanation":"定义正确。形成条件：溶质与溶剂原子半径比小于0.59（如C、N、B、H溶于Fe）。因晶格间隙有限，溶解度总是有限的；但间隙原子造成的晶格畸变呈强不对称性，故间隙固溶的强化效果明显强于置换固溶。","erratum":"","sourceNumber":13,"id":"j0013","order":12,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"共晶转变","answer":"指具有一定成分的液态合金,在一定温度下,同时结晶出两种不同的固相的转变。","explanation":"定义正确。共晶转变是液相在恒温下同时结晶出两种固相，如Fe-C中L(4.3%C)→A(2.11%C)+Fe3C，产物即莱氏体Ld。它与共析反应的区别仅在反应物状态（液相vs固相）。","erratum":"","sourceNumber":14,"id":"j0014","order":13,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"置换固溶体","answer":"溶质原子溶入溶质晶格并占据溶质晶格位置所形成的固溶体。","explanation":"定义正确，但有一处笔误：“溶质原子溶入溶质晶格”应为“溶入溶剂晶格”。形成条件为原子半径比0.85~1.15、晶格类型相同、电化学性质相近；满足时可能无限互溶（Cu-Ni），否则有限（Cu-Zn）。","erratum":"","sourceNumber":15,"id":"j0015","order":14,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"变质处理","answer":"在金属浇注前添加变质剂来改变晶粒的形状或大小的处理方法。","explanation":"定义正确。铸造时细化晶粒的三种方法：增大过冷度、变质处理（加变质剂/孕育剂）、附加振动（机械、超声、电磁）。变质处理的机理是增加非自发形核核心、提高形核率，而不改变成分。","erratum":"","sourceNumber":16,"id":"j0016","order":15,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"晶体的各向异性","answer":"晶体在不同方向具有不同性能的现象。","explanation":"定义正确，但需补全两方面：①晶体各向异性的根源是不同晶向上原子排列密度不同；②单晶体必然各向异性，多晶体一般呈“伪各向同性”，但存在织构（冷变形纤维组织、铸造柱状晶）时同样会表现出各向异性。","erratum":"","sourceNumber":17,"id":"j0017","order":16,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"弥散强化","answer":"当在晶内呈颗粒状弥散分布时，第二相颗粒越细，分布越均匀，合金的强度、硬度越高，塑性、韧性略有下降，这种强化方法称弥散强化","explanation":"定义正确。机理：细小弥散的第二相颗粒阻碍位错运动（Orowan绕过机制）。颗粒越细、越弥散、体积分数越大、与基体共格畸变越强，强化效果越好。它与固溶强化的区别在于第二相是独立的新相。","erratum":"","sourceNumber":18,"id":"j0018","order":17,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"固溶强化","answer":"因溶质原子溶入而使固溶体的强度和硬度升高的现象。","explanation":"定义正确。机理是溶质原子造成晶格畸变，畸变应力场与位错应力场相互作用，阻碍位错运动。强化效果取决于溶质与溶剂的尺寸差、溶质浓度；间隙固溶的畸变大，故强化效果大于置换固溶。","erratum":"","sourceNumber":19,"id":"j0019","order":18,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"细晶强化","answer":"通过细化晶粒来同时提高金属的强度、硬度、塑性和韧性的方法称细晶强化。","explanation":"定义正确，且这是唯一能同时提高强度、硬度、塑性和韧性的强化方式（Hall-Petch关系σs=σ0+kd^(-1/2)）。原因：晶界阻碍位错运动使强度升高，晶粒细小使变形均匀、裂纹不易扩展使塑韧性改善。","erratum":"","sourceNumber":20,"id":"j0020","order":19,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"形变强化","answer":"随着塑性变形程度的增加，金属的强度、硬度提高，而塑性、韧性下降的现象。","explanation":"定义正确。机理：随变形量增大，位错密度急剧升高并相互缠结，位错运动阻力增大，表现为强度、硬度升高，塑性、韧性下降。它与加工硬化、冷作强化是同一现象的不同名称（见第22、23题）。","erratum":"","sourceNumber":21,"id":"j0021","order":20,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"加工硬化","answer":"随着塑性变形的增加，金属的强度、硬度迅速增加；塑性、韧性迅速下降的现象","explanation":"定义正确。工程意义有两面：有利的一面是冷拉钢丝、冷轧薄板、冷挤压件借加工硬化提高强度；不利的一面是继续冷变形会开裂，须在工序间安排再结晶退火来消除加工硬化。","erratum":"","sourceNumber":22,"id":"j0022","order":21,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"冷作强化","answer":"随冷塑性变形量增加，金属的强度、硬度提高，塑性、韧性下降的现象称加工硬化。","explanation":"定义正确。需注意本条与第21、22题实为同一概念（形变强化＝加工硬化＝冷作强化），定义文字几乎重复，区别只在“称加工硬化”一句放在了冷作强化名下，答题时可互换使用。","erratum":"","sourceNumber":23,"id":"j0023","order":22,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"再结晶","answer":"金属发生重新形核和长大而不改变其晶格类型的结晶过程。经过塑性变形的金属材料加热到较高的温度时，原子具有较大的活动能力，使晶粒的外形开始变化。从破碎拉长的晶粒变成新的等轴晶粒。和变形前的晶粒形状相似，晶格类型相同，把这一阶段称为“再结晶”。","explanation":"定义正确，但需点明两个关键：①再结晶过程有形核和长大，但不改变晶格类型，故它不是相变；②再结晶温度T再≈0.4Tm（热力学温度），变形度越大、纯度越高，T再越低。再结晶后晶粒细小、加工硬化完全消除。","erratum":"","sourceNumber":24,"id":"j0024","order":23,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"纤维组织","answer":"经过一定塑性变形后，金属组织（特别是晶界上存在的杂质）沿变形方向的流线分布叫纤维组织。","explanation":"定义正确。冷、热加工都能形成纤维（流线）组织，其本质是夹杂物、偏析沿变形方向呈流线分布，使性能呈方向性：纵向强度、塑性高，横向低。设计锻件时应使流线沿零件最大受力方向并与轮廓相符，不得切断。","erratum":"","sourceNumber":25,"id":"j0025","order":24,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"淬火","answer":"将钢加热到相变温度以上（亚共析钢为Ac3以上30 ℃～50 ℃；共析钢和过共析钢为Ac1以上30 ℃～50 ℃），保温一定时间后快速冷却以获得马氏体组织的热处理工艺称为淬火。","explanation":"定义正确，温度选择是重点：亚共析钢Ac3+30~50℃（完全淬火），共析钢与过共析钢Ac1+30~50℃（不完全淬火，保留粒状渗碳体）。高于上限会过热、晶粒粗大；低于下限则奥氏体化不充分，硬度不足。","erratum":"","sourceNumber":26,"id":"j0026","order":25,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"淬透性","answer":"钢淬火时获得马氏体的能力。","explanation":"定义不完整。淬透性指钢在淬火时获得马氏体（淬硬层）的能力，用规定条件下的淬硬层深度表示，取决于过冷奥氏体的稳定性（即C曲线位置），是钢的固有属性，与冷却介质、零件尺寸无关——冷速和尺寸只影响实际淬硬层深度。","erratum":"","sourceNumber":27,"id":"j0027","order":26,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"淬硬性","answer":"钢在淬火后获得马氏体的最高硬度。","explanation":"定义正确。淬硬性指淬火后马氏体所能达到的最高硬度，主要取决于马氏体含碳量（0.2%~0.6%近似线性上升，超过0.6%趋缓）。它与淬透性无必然联系：GCr15淬硬性高但淬透性中等，40Cr淬透性好而淬硬性一般。","erratum":"","sourceNumber":28,"id":"j0028","order":27,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"调质处理","answer":"淬火后加高温回火","explanation":"定义过简。调质＝淬火＋高温回火（500~650℃），得到回火索氏体，目的是获得强度与塑性、韧性良好配合的综合力学性能，广泛用于轴类、连杆、齿轮、螺栓等重要受力件。它是“最终热处理”，不是预备热处理。","erratum":"","sourceNumber":29,"id":"j0029","order":28,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"马氏体","answer":"碳在α-Fe中的过饱和固溶体。","explanation":"定义基本正确，宜补“过饱和”与晶格：马氏体是碳在α-Fe中的过饱和固溶体，晶格为体心正方（c/a略大于1，是体心立方的畸变），故第18、49题的判断可判为正确。含碳越高，正方度越大、畸变越强、硬度越高但越脆。","erratum":"","sourceNumber":30,"id":"j0030","order":29,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"时效强化","answer":"固溶处理后铝合金的强度和硬度随时间变化而发生显著提高的现象。","explanation":"定义正确。机理：过饱和固溶体脱溶析出弥散的GP区或过渡相，造成晶格畸变并阻碍位错运动，使强度硬度显著升高。时效分自然时效（室温）和人工时效（加热），硬铝合金、铝铜合金是典型代表。","erratum":"","sourceNumber":31,"id":"j0031","order":30,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"临界冷却速度","answer":"钢淬火时获得完全马氏体的最低冷却速度。","explanation":"定义正确。Vk是过冷奥氏体在连续冷却时全部转变为马氏体（不发生P、B转变）所需的最小冷却速度，即CCT曲线上与“珠光体转变开始线”相切的冷速。Vk越小，C曲线越靠右，淬透性越好。","erratum":"","sourceNumber":32,"id":"j0032","order":31,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"热硬性","answer":"指金属材料在高温下保持高硬度的能力。","explanation":"定义正确（又称红硬性）。它是刃具钢、高速钢、硬质合金的核心指标：W18Cr4V可在600℃仍保持HRC60左右，故可取30~50m/min的高速切削；碳素工具钢T10 超过200℃即软化。","erratum":"","sourceNumber":33,"id":"j0033","order":32,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"二次硬化","answer":"淬火钢在回火时硬度提高的现象。","explanation":"定义不完整。二次硬化需具备两个条件：①钢中含W、Mo、V等强碳化物形成元素，回火时析出细小弥散的特殊碳化物；②回火冷却时残余奥氏体转变为马氏体。二者叠加使500~600℃回火后硬度不降反升，高速钢的三次回火即利用此效应。","erratum":"","sourceNumber":34,"id":"j0034","order":33,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"残余奥氏体","answer":"指淬火后尚未转变，被迫保留下来的奥氏体。","explanation":"定义正确。马氏体转变在Ms~Mf之间进行，冷至室温时Ms低于室温的部分未能转变完，即为残余奥氏体。它降低硬度、耐磨性和尺寸稳定性，可用冷处理（-60~-80℃）或多次回火使其转变或稳定化。","erratum":"","sourceNumber":35,"id":"j0035","order":34,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"调质处理","answer":"指淬火及高温回火的热处理工艺。","explanation":"定义正确，与第29题重复。答题时注意：调质必须包含“高温回火”这一环节，仅淬火＋中温回火（如弹簧钢）不能称调质，其组织是回火屈氏体而非回火索氏体。","erratum":"","sourceNumber":36,"id":"j0036","order":35,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"淬硬性","answer":"钢淬火时的硬化能力。","explanation":"本条第28题重复，且“硬化能力”表述过于笼统，容易被误解为淬透性。应改为：淬硬性指钢淬火后马氏体所能达到的最高硬度，取决于马氏体含碳量；而淬透性指获得马氏体层的深浅，取决于过冷奥氏体稳定性。","erratum":"","sourceNumber":37,"id":"j0037","order":36,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"过冷奥氏体","answer":"将钢奥氏体化后冷却至A1温度之下尚未分解的奥氏体。","explanation":"定义正确。过冷奥氏体在A1以下是不稳定相，按 C曲线分别发生珠光体转变（A1~550℃）、贝氏体转变（550℃~Ms）和马氏体转变（Ms以下）。C曲线的“鼻尖”（约550℃）孕育期最短，是淬火冷却必须快越过的危险区。","erratum":"","sourceNumber":38,"id":"j0038","order":37,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"本质晶粒度","answer":"指奥氏体晶粒的长大倾向。","explanation":"表述不准确。本质晶粒度是按规定条件（930℃保温8h）测定的奥氏体晶粒长大倾向，用于评价冶炼（脱氧）质量，分本质细晶粒钢（1~4级）和本质粗晶粒钢（5~8级）；它不等于实际晶粒度，实际晶粒度取决于具体加热规范。","erratum":"","sourceNumber":39,"id":"j0039","order":38,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"C曲线","answer":"过冷奥氏体的等温冷却转变曲线。","explanation":"定义正确（又称TTT曲线、等温转变曲线）。曲线呈“C”形，因为高温区过冷度小、低温区扩散慢，二者都不利于转变，故在550℃附近孕育期最短。三个转变区分别得到P（S、T）、B、M。","erratum":"","sourceNumber":40,"id":"j0040","order":39,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"CCT曲线","answer":"过冷奥氏体的连续冷却转变曲线。","explanation":"定义正确（又称CCT曲线）。它与C曲线的关系是考点：CCT曲线整体位于 TTT曲线的右下方，临界冷速更大；共析钢连续冷却时因贝氏体孕育期长而来不及转变，故CCT曲线上没有贝氏体转变区。","erratum":"","sourceNumber":41,"id":"j0041","order":40,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"马氏体","answer":"含碳过饱和的α固溶体。","explanation":"定义正确，与第30题重复。“含碳过饱和的α固溶体”是简明说法；完整表述应加上“碳在α-Fe中的过饱和间隙固溶体，晶格为体心正方”。","erratum":"","sourceNumber":42,"id":"j0042","order":41,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"回火稳定性","answer":"钢在回火时抵抗硬度下降的能力。","explanation":"定义正确（又称回火抗力、耐回火性）。Cr、Mo、W、V、Si等元素能延缓马氏体分解和碳化物聚集长大，提高回火稳定性，使钢在较高温度回火仍保持高硬度——这正是合金刃具钢优于碳素工具钢的关键。","erratum":"","sourceNumber":43,"id":"j0043","order":42,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"可逆回火脆性","answer":"又称第二类回火脆性，发生的温度在400～650℃，当重新加热脆性消失后，应迅速冷却，不能在400～650℃区间长时间停留或缓冷，否则会再次发生催化现象。","explanation":"表述较乱，应理清：第二类（可逆）回火脆性发生在400~650℃回火（或该区间缓慢冷却）之后，冲击韧性显著下降；将钢重新加热到600℃以上快冷，脆性可以消除，故称“可逆”。加Mo、W或降低P、Sb、Sn等杂质可抑制。","erratum":"","sourceNumber":44,"id":"j0044","order":43,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"Q235","answer":"屈服强度值大于等于235MPa的碳素结构钢。","explanation":"定义正确。Q＝屈服强度，235＝最小屈服强度235MPa。后缀含义要会读：A、B、C、D 为质量等级（S、P含量依次降低），F为沸腾钢、b为半镇静钢、Z为镇静钢。Q235是最常用的普通碳素结构钢。","erratum":"","sourceNumber":45,"id":"j0045","order":44,"chapterId":"steel","chapterIds":["steel"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"T8A钢","answer":"其平均含碳量为千分之八的高级优质碳素工具钢。","explanation":"定义正确。T＝碳素工具钢，8＝平均含碳量0.8%（千分之八），A＝高级优质（S≤0.020%、P≤0.030%）。T8A淬火＋低温回火后HRC60~62，用于冲头、凿子、木工工具等。同类还有T7A~T13A。","erratum":"","sourceNumber":46,"id":"j0046","order":45,"chapterId":"steel","chapterIds":["steel"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"40CrNiMo钢","answer":"含碳量为0.4%，Cr、Ni、Mo的含量都小于1.5%的结构合金钢。","explanation":"定义正确。40＝平均含碳量0.40%；Cr、Ni、Mo均小于1.5%，属中碳合金结构钢（调质钢）。40CrNiMo淬透性很高、综合力学性能好，用于大截面重载零件如汽轮机主轴、航空发动机曲轴。","erratum":"","sourceNumber":47,"id":"j0047","order":46,"chapterId":"steel","chapterIds":["steel"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"Ni18Cr9Ti","answer":"含碳量小于0.08%，Ni的含量为18%，Cr的含量为9%，Ti的含量小于1.5% 的不锈钢。","explanation":"牌号书写不规范。标准写法应为1Cr18Ni9Ti：1＝w C约0.1%（≤0.12%），18＝w Cr约18%，9＝w Ni约9%，Ti为稳定化元素（防晶间腐蚀）。题中“Ni18Cr9Ti”不是国标牌号，答题时应写1Cr18Ni9Ti或0Cr18Ni9Ti。","erratum":"","sourceNumber":48,"id":"j0048","order":47,"chapterId":"steel","chapterIds":["steel"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"石墨化","answer":"铸铁中碳原子析出并形成石墨的过程称为石墨化。","explanation":"定义正确。石墨化包括石墨的形核与长大两个阶段。促进元素：C、Si、Al、Cu、Ni；阻碍元素：S、Mn、Cr、Mo、V。此外冷却速度越慢越利于石墨化，故厚壁铸件易得灰口、薄壁件易得白口。","erratum":"","sourceNumber":49,"id":"j0049","order":48,"chapterId":"iron","chapterIds":["iron"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"term","type":"term","section":"名词解释","question":"HT150","answer":"最低抗拉强度为150MPa的灰铸铁。","explanation":"定义正确。HT＝灰铸铁，150＝最低抗拉强度150MPa（旧牌号HT150→新牌号HT150仍沿用）。灰铸铁的抗拉强度低、抗压强度高（约为抗拉的3~4倍）、减振性和切削性好，适合做机床床身、箱体、底座。","erratum":"","sourceNumber":50,"id":"j0050","order":49,"chapterId":"iron","chapterIds":["iron"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"主要的强度指标有弹性极限，屈服点（屈服强度），抗拉强度，刚度。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"","explanation":"判定正确。弹性极限σe、屈服强度σs、抗拉强度σb都是强度指标；刚度是抵抗弹性变形的能力，用弹性模量E衡量，属“弹性指标”而非强度指标，故原命题多列了刚度。","erratum":"","sourceNumber":1,"id":"j0051","order":50,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"常用塑性指标有断后伸长率和断面收缩率。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。塑性指标只有两个：断后伸长率δ和断面收缩率ψ。注意δ的数值与试样标距有关（δ5、δ10），ψ则与尺寸无关，故ψ更能反映材料真实塑性。","erratum":"","sourceNumber":2,"id":"j0052","order":51,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"洛氏硬度一般不用于在线检测","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"","explanation":"判定正确。洛氏硬度压痕小、读数快、不损伤零件，广泛用于成批半成品和成品的在线检测；不宜检测成品的是布氏硬度（压痕大）和维氏（速度慢）。","erratum":"","sourceNumber":3,"id":"j0053","order":52,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"维氏硬度不能用于检测薄壁件。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"","explanation":"判定正确。维氏硬度可用小负荷（乃至显微硬度）检测薄壁件、渗层、镀层和微小区域，能测薄壁件恰是它的优点，故原命题说“不能”是错误的。","erratum":"","sourceNumber":4,"id":"j0054","order":53,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"铁素体是钢中常见的金属化合物相。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"","explanation":"判定正确。铁素体是碳在α-Fe中的间隙固溶体（单相固溶体），不是化合物；钢中常见的金属化合物是渗碳体Fe3C。","erratum":"","sourceNumber":5,"id":"j0055","order":54,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"珠光体是钢中常见的金属化合物相。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"","explanation":"判定正确。珠光体是铁素体与渗碳体的层片状机械混合物，属两相组织，既不是化合物也不是单相固溶体。","erratum":"","sourceNumber":6,"id":"j0056","order":55,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"奥氏体是钢室温常见的金属化合物相。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"","explanation":"判定正确。奥氏体是碳在γ-Fe中的间隙固溶体，只在727℃以上稳定，室温下不稳定，且它也不是化合物。原命题错在“化合物相”和“室温常见”两处。","erratum":"","sourceNumber":7,"id":"j0057","order":56,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"韧性表示了金属材料抗冲击的能力。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。韧性是材料在塑性变形和断裂全过程中吸收变形功和冲击功的能力，用冲击吸收功Ak或冲击韧度αk表示，本质是“抗冲击”而非“抗拉”。","erratum":"","sourceNumber":8,"id":"j0058","order":57,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"大部分零件的损坏是由疲劳造成的。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。统计表明疲劳断裂约占零件失效的80%，多起源于表面或内部缺陷处的应力集中，断口呈“贝壳状”且无明显塑性变形，危害最大。","erratum":"","sourceNumber":9,"id":"j0059","order":58,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"细化晶粒虽能提高金属的强度，但增大了金属的脆性。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"细化晶粒不但能提高金属的强度，也降低了金属的脆性","explanation":"判定正确。细化晶粒是唯一能同时提高强度、硬度、塑性和韧性的强化方式（细晶强化），故“增大脆性”的说法完全相反。","erratum":"","sourceNumber":10,"id":"j0060","order":59,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"结构钢的淬透性，随钢中碳含量的增大而增大。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"结构钢的淬硬性，随钢中碳含量的增大而增大","explanation":"判定正确。随含碳量增加而提高的是淬硬性（马氏体硬度）；淬透性只在亚共析范围内随碳量增加而提高，过共析反而下降，且主要由合金元素决定。","erratum":"","sourceNumber":11,"id":"j0061","order":60,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"普通低合金结构钢不能通过热化处理进行强化。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定基本正确。普通低合金结构钢（Q345、Q390等）含碳量低（≤0.20%），淬火强化效果不显著，通常以热轧或正火状态使用，靠合金元素、细晶和析出强化保证性能。题中“热化处理”应为“热处理”。","erratum":"","sourceNumber":12,"id":"j0062","order":61,"chapterId":"steel","chapterIds":["steel"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"置换固溶体必是无限固溶体。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"置换固溶体有可能是无限固溶体","explanation":"判定正确。置换固溶体既可以无限互溶（Cu-Ni、Au-Ag），也可以有限互溶（Cu-Zn）；只有间隙固溶体才必定是有限固溶体。","erratum":"","sourceNumber":13,"id":"j0063","order":62,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"单晶体必有各向异性。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。各向异性由晶格结构决定，是晶体的固有属性。单晶体必然各向异性；多晶体因各晶粒取向杂乱才呈“伪各向同性”，这与第58题互为对照。","erratum":"","sourceNumber":14,"id":"j0064","order":63,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"普通钢和优质钢是按其强度等级来区分的。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"普通钢和优质钢是按钢中有害杂质硫、磷的含量来划分的","explanation":"判定正确。普通钢与优质钢按有害杂质S、P的含量划分：普通钢S≤0.050%、P≤0.045%；优质钢S、P均≤0.035%；高级优质钢更严。与强度等级无关。","erratum":"","sourceNumber":15,"id":"j0065","order":64,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"过热钢经再结晶退火后能显著细化晶粒。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"过热钢经正火后能显著细化晶粒","explanation":"判定正确。再结晶退火只能消除加工硬化、恢复晶粒形状，不能改变晶粒度；过热钢的粗大晶粒必须通过重结晶（完全退火或正火）来细化。","erratum":"","sourceNumber":16,"id":"j0066","order":65,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"奥氏体耐热钢也就是奥氏体不锈钢。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"奥氏体耐热钢不是奥氏体不锈钢","explanation":"判定正确。奥氏体耐热钢以高温强度、抗氧化性为主要目标（如4Cr14Ni14W2Mo），奥氏体不锈钢以耐蚀性为目标（如1Cr18Ni9Ti），两者的成分设计和合金化思路不同。","erratum":"","sourceNumber":17,"id":"j0067","order":66,"chapterId":"steel","chapterIds":["steel"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"马氏体的晶体结构和铁素体的相同。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定可接受，但需说明：马氏体是碳在α-Fe中的过饱和固溶体，其晶格为体心正方（c/a略大于1），本质上是体心立方的畸变，故教材通行判为相同；严格讲点阵常数已改变。","erratum":"","sourceNumber":18,"id":"j0068","order":67,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"面心立方金属的塑性比体心立方金属的好。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。面心立方有12个滑移系且滑移方向均为密排方向，塑性优于体心立方（体心立方滑移系虽多，但派纳力高、低温易脆断）。","erratum":"","sourceNumber":19,"id":"j0069","order":68,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"铁素体是置换固溶体。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"铁素体是碳溶于α-Fe中形成的间隙固溶体体","explanation":"判定正确，但原“改正”有笔误（“固溶体体”）。铁素体是碳在α-Fe中形成的间隙固溶体，727℃时溶解度最大也只有0.0218%，室温仅0.0008%。","erratum":"","sourceNumber":20,"id":"j0070","order":69,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"晶界是金属晶体的常见缺陷。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。晶界属面缺陷（二维缺陷），同类还有亚晶界、相界、孪晶界；点缺陷是空位、间隙原子，线缺陷是位错。","erratum":"","sourceNumber":21,"id":"j0071","order":70,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"渗碳体是钢中常见的固溶体相。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"渗碳体是钢中常见的金属化合物相","explanation":"判定正确。渗碳体是铁与碳形成的间隙化合物（金属化合物），有固定成分6.69%C和固定熔点，不具备固溶体的可变成分特征。","erratum":"","sourceNumber":22,"id":"j0072","order":71,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"金属的塑性变形主要通过位错的滑移进行。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。常温塑性变形以位错滑移为主；高温下还有晶界滑动和扩散蠕变；低温、高应变速率时为孪生。故滑移是主要方式而非唯一方式。","erratum":"","sourceNumber":23,"id":"j0073","order":72,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"金属在进行热加工时，不会产生加工硬化现象。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定可接受（教材通行口径）。热加工中虽瞬时产生加工硬化，但同时发生动态再结晶把它消除，宏观上不显示加工硬化。严格说“产生过但看不出来”，与第28题的表述是同一意思。","erratum":"","sourceNumber":24,"id":"j0074","order":73,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"金属由液态凝结为固态的过程都是结晶过程。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。纯金属和共晶成分合金在恒温下结晶；一般合金在一定的温度范围内结晶。例外是非晶合金（金属玻璃）。","erratum":"","sourceNumber":25,"id":"j0075","order":74,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"钢铁含碳量越高,越容易焊得优质接头;相同的含碳量,合金钢的焊接性更佳.","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"钢铁含碳量越低,越容易焊得优质接头;相同的含碳量,合金钢的焊接性更佳.","explanation":"判定正确。焊接性随含碳量升高而变差（淬硬倾向、冷裂纹敏感性增大）；相同含碳量时，合金元素越多，焊接性越差。","erratum":"原“改正”后半句仍错。应为：钢铁含碳量越低越容易焊得优质接头；相同含碳量时，碳钢的焊接性优于合金钢（合金元素增加淬硬和裂纹倾向）。","sourceNumber":26,"id":"j0076","order":75,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"凡是金属都有一定塑性,因此都可进行压力加工.","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"凡是金属都有一定塑性,但不一定可进行压力加工，如铸铁.","explanation":"判定正确。铸铁塑性、韧性极低，不能压力加工；此外高碳钢、某些脆性合金也受限。能否压力加工取决于塑性储备，而不是“凡金属都有塑性”这一前提。","erratum":"","sourceNumber":27,"id":"j0077","order":76,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"冷塑性变形要出现加工硬化,热塑性变形实际也出现过加工硬化,但因温度较高,很快发生了再结晶,最终使加工硬化不明显了.","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。热变形是“加工硬化＋动态再结晶”同时进行的过程，稳态时硬化被完全抵消，故最终不显示明显加工硬化。注意本条与第24、90题的说法需要统一口径。","erratum":"","sourceNumber":28,"id":"j0078","order":77,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"金属的再结晶温度也就是金属的凝固温度.","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"金属的再结晶温度也就是能进行再结晶的最低温度","explanation":"判定正确。再结晶温度是开始再结晶的最低温度（T再≈0.4Tm，热力学温度），与凝固温度相差很远：铁凝固1538℃，再结晶温度仅约450℃。","erratum":"","sourceNumber":29,"id":"j0079","order":78,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"区分冷、热加工的标志是金属在加工变形时是否产生加工硬化。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"区分冷、热加工的标志是以再结晶温度来划分的","explanation":"判定正确。冷、热加工以再结晶温度划分：变形温度高于T再为热加工，低于T再为冷加工。是否产生加工硬化只是结果，不能作判据。","erratum":"","sourceNumber":30,"id":"j0080","order":79,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"上贝氏体的韧性比下贝氏体好。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"上贝氏体的韧性比下贝氏体差","explanation":"判定正确。上贝氏体的铁素体条较宽、碳化物沿条间断续分布，裂纹易沿条间扩展，故韧性明显低于下贝氏体（下贝氏体碳化物在条内弥散分布）。","erratum":"","sourceNumber":31,"id":"j0081","order":80,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"对过共析钢工件进行完全退火可消除渗碳体网。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"对过共析钢工件进行正火可消除渗碳体网","explanation":"判定正确。完全退火加热到Ac3以上，过共析钢全部奥氏体化，缓冷时二次渗碳体沿晶界析出成网，不但不能消除反而加重；消除网状必须用正火（加热到Accm以上后空冷）。","erratum":"","sourceNumber":32,"id":"j0082","order":81,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"对低碳低合金钢进行正火处理可提高其硬度。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。低碳低合金钢正火后珠光体量增多、片间距变细、晶粒细化，硬度提高，切削时不再“粘刀”，故正火是低碳钢常用的改善切削加工性的手段。","erratum":"","sourceNumber":33,"id":"j0083","order":82,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"淬火获得马氏体的必要条件之一是其淬火冷却速度必须小于Vk。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"淬火获得马氏体的必要条件之一是其淬火冷却速度必须大于Vk","explanation":"判定正确。获得全部马氏体的条件是实际冷速大于临界冷速Vk；小于Vk就会先发生珠光体或贝氏体转变，得不到全马氏体。","erratum":"","sourceNumber":34,"id":"j0084","order":83,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"氮化件的变形远比渗碳件的小。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。氮化温度低（500~580℃）、无相变发生，变形仅为渗碳件的1/5~1/10，故常作为精密零件（镗杆、量规、齿轮）的最后一道工序。","erratum":"","sourceNumber":35,"id":"j0085","order":84,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"渗碳、渗氮等化学热处理工艺改变了材料的化学成分，而普通热处理如退火则不改变材料的化学成分。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。化学热处理靠扩散改变表层化学成分（渗碳、渗氮、碳氮共渗）；普通热处理只改变组织，成分不变。","erratum":"","sourceNumber":36,"id":"j0086","order":85,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"高锰钢在各种条件下均能表现出良好的耐磨性。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"高锰钢只有在受到强烈的冲击和压力的条件下才能表现出良好的耐磨性","explanation":"判定正确。高锰钢（ZGMn13）水韧处理后为单相奥氏体，硬度仅HB180~220，只有在强烈冲击、挤压下表层发生加工硬化才耐磨，故不能“在各种条件下”都耐磨。","erratum":"","sourceNumber":37,"id":"j0087","order":86,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"无限固溶体必是置换固溶体。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。无限固溶要求溶质与溶剂晶格相同、原子半径相近、电化学性质相近，只有置换固溶体才可能满足；间隙固溶体的溶解度必定有限。","erratum":"","sourceNumber":38,"id":"j0088","order":87,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"金属的晶粒越细小，其强度越高，但韧性变差。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"一般地说，在室温下，金属的晶粒越细小，其强度和韧性越高","explanation":"判定正确。细晶强化能同时提高强度和韧性，晶粒越细，变形越均匀、裂纹扩展路径越曲折，韧性越好，与“韧性变差”相反。","erratum":"","sourceNumber":39,"id":"j0089","order":88,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"所谓临界冷却速度就是指钢能获得完全马氏体组织的最小冷却速度。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。Vk即全部获得马氏体（不出现珠光体、贝氏体转变）所需的最小冷却速度，是CCT曲线上临界冷速的定义。","erratum":"","sourceNumber":40,"id":"j0090","order":89,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"钢进行分级淬火的目的是为了得到下贝氏体组织。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"钢进行分级淬火的目的是为了减小淬火应力，防止工件变形和开裂","explanation":"判定正确。分级淬火是在Ms点附近（稍高于 Ms）的盐浴或碱浴中短时停留均温后空冷，目的是减小热应力和组织应力、减少变形开裂；获得下贝氏体的是等温淬火。","erratum":"","sourceNumber":41,"id":"j0091","order":90,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"对奥氏体不锈钢进行固溶处理的目的是为了提高其强度。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"对奥氏体不锈钢进行固溶处理的目的是为了提高其耐蚀性","explanation":"判定正确。固溶处理的目的是使晶界碳化物溶解、获得单相奥氏体、提高耐蚀性并降低硬度便于加工，不是提高强度（强度靠冷变形或时效）。","erratum":"","sourceNumber":42,"id":"j0092","order":91,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"弹簧钢的最终热处理应是淬火+低温回火。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"弹簧钢的最终热处理应是淬火+中温回火","explanation":"判定正确。弹簧钢最终热处理为淬火＋中温回火（350~500℃），得到回火屈氏体，具有高的弹性极限、屈强比和足够的韧性；低温回火只适用于要求高硬度的零件。","erratum":"","sourceNumber":43,"id":"j0093","order":92,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"凡单相固溶体均能进行形变强化。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。单相固溶体（奥氏体、铝基固溶体）塑性好，可承受冷变形而产生形变强化；形变强化的前提是能够进行塑性变形。","erratum":"","sourceNumber":44,"id":"j0094","order":93,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"陶瓷组织中的气相能起到一定的强化作用。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"陶瓷组织中的气相降低了陶瓷的强度，是造成裂纹的根源","explanation":"判定正确。陶瓷组织中的气孔减少承载面积、形成应力集中，是裂纹源，使强度、韧性、抗热震性全面下降，绝无强化作用。","erratum":"","sourceNumber":45,"id":"j0095","order":94,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"热塑性塑料一般具有链状或支链状分子结构。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。热塑性塑料为线型或支链型大分子，受热软化、冷却硬化，可反复加工；热固性塑料固化后形成体型网状交联结构，不可逆。","erratum":"","sourceNumber":46,"id":"j0096","order":95,"chapterId":"nonmetal","chapterIds":["nonmetal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"凡间隙固溶体必是有限固溶体。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。间隙固溶体的溶解度受晶格间隙数量和尺寸限制，必定有限；无限固溶只可能是置换固溶体。","erratum":"","sourceNumber":47,"id":"j0097","order":96,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"热变形加工可打碎杂质和晶体晶粒，使晶粒细化，提高力学性能。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定基本正确。热加工可使铸态枝晶和粗大晶粒破碎、使夹杂物细化并沿流线分布，从而细化晶粒、提高力学性能。但“打碎杂质”表述不严谨，夹杂物多为塑性伸长或变形，并非被打碎。","erratum":"","sourceNumber":48,"id":"j0098","order":97,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"马氏体的晶体结构和铁素体相同。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"同第18题。马氏体为碳在α-Fe中的过饱和固溶体，晶格为体心正方（可视为体心立方的畸变），故通行判为相同。","erratum":"","sourceNumber":49,"id":"j0099","order":98,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"感应加热表面淬火的淬硬深度与该钢的淬透性没有关系。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。感应加热时电流频率越高，电流透入深度越小，淬硬层越浅，与钢的淬透性无关；但淬硬层内能达到的硬度与含碳量、淬透性有关。","erratum":"","sourceNumber":50,"id":"j0100","order":99,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"共析钢经奥氏体化后，冷却所形成的组织主要取决于钢的加热温度。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"","explanation":"判定正确。奥氏体化后冷却所得组织主要取决于冷却速度（过冷度），加热温度只影响奥氏体的成分均匀性和晶粒大小，从而间接影响转变产物的粗细。","erratum":"","sourceNumber":51,"id":"j0101","order":100,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"采用等温淬火可获得晶粒大小均匀的马氏体。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"","explanation":"判定正确。等温淬火（Ms以上等温）得到下贝氏体（或B下＋A′），得不到马氏体；要得到均匀细小的马氏体应控制加热温度获得细晶奥氏体。","erratum":"","sourceNumber":52,"id":"j0102","order":101,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"珠光体的片层间距越小，其强度越高，其塑性越差。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"珠光体的片层间距越小，其强度越高，其塑性越好","explanation":"判定正确。片层间距减小使相界面增多，位错运动阻力增大、强度硬度升高；同时细片层有利于界面协调变形，塑性韧性也变好，故原命题“塑性越差”说反了。","erratum":"","sourceNumber":53,"id":"j0103","order":102,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"钢的临界冷却速度Vk越大，则其淬透性越好。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"钢的临界冷却速度Vk越低，则其淬透性越好","explanation":"判定正确。Vk越小，说明过冷奥氏体越稳定，淬透性越好；Vk越大则淬透性越差。注意与第68题的说法一致。","erratum":"","sourceNumber":54,"id":"j0104","order":103,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"对过共析钢工件进行完全退火可消除渗碳体网。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"","explanation":"同第32题，判定正确。消除过共析钢网状渗碳体的正确工艺是正火，而不是完全退火。","erratum":"","sourceNumber":55,"id":"j0105","order":104,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"过共析钢的正常淬火一般均为不完全淬火。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。过共析钢正常淬火加热到Ac1+30~50℃，属不完全淬火，保留部分未溶粒状渗碳体，既提高耐磨性又降低开裂倾向。","erratum":"","sourceNumber":56,"id":"j0106","order":105,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"工件经渗碳处理后，随后应进行淬火及低温回火。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。渗碳只改变表层成分，必须通过淬火＋低温回火使表层获得高碳马氏体＋粒状碳化物才能硬化；不淬火则渗层无强化效果。","erratum":"","sourceNumber":57,"id":"j0107","order":106,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"金属是多晶体，因而绝对不可以产生各向异性。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"","explanation":"多晶体在晶粒取向完全随机时表现为“伪各向同性”，但当存在织构（冷变形纤维组织、形变织构、铸造柱状晶）时同样会表现出各向异性——第85题正是这个结论，两题不可矛盾。","erratum":"本题答案应改为╳。正确表述：多晶体一般呈伪各向同性，但存在织构（择优取向）时仍可表现出各向异性。","sourceNumber":58,"id":"j0108","order":107,"chapterId":"crystal","chapterIds":["crystal"],"answerCorrected":true,"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"凡能使钢的C曲线右移的合金元素均能增加钢的淬透性。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。C曲线右移→Vk减小→淬透性提高，唯一例外是Co（使C曲线左移、淬透性下降）。这也是“除Co外合金元素都提高淬透性”的由来。","erratum":"","sourceNumber":59,"id":"j0109","order":108,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"感应加热表面淬火的淬硬深度与该钢的淬透性没有关系。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"同第50题。感应淬火的淬硬层深度由电流频率决定，与淬透性无关；频率越高（如高频100~500kHz）淬硬层越浅（0.5~2mm）。","erratum":"","sourceNumber":60,"id":"j0110","order":109,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"金属凝固时，过冷度越大，晶体长大速度越大，因而其晶粒粗大。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"金属凝固时，过冷度越大，晶体长大速度越大，因而其晶粒细化","explanation":"判定正确。过冷度增大时形核率N的增长快于长大速度G，N/G 增大，晶粒反而细化，故“晶粒粗大”的结论与事实相反。","erratum":"","sourceNumber":61,"id":"j0111","order":110,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"钢的淬透性与其实际冷却速度无关。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"钢的淬透性与其实际冷却速度有关","explanation":"淬透性是钢的固有属性，由过冷奥氏体的稳定性（成分、奥氏体化条件）决定，只与实际冷却速度无关；冷却速度影响的是实际淬硬层深度，不是淬透性本身。原“改正”把两个概念混为一谈，与第101、102题的判定也自相矛盾。","erratum":"本题答案应改为√。正确表述：钢的淬透性与其实际冷却速度无关；实际淬硬层深度才同时取决于淬透性、冷却速度和零件尺寸。","sourceNumber":62,"id":"j0112","order":111,"chapterId":"heat","chapterIds":["heat"],"answerCorrected":true,"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"亚共析钢的正常淬火一般为不完全淬火。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"","explanation":"亚共析钢必须加热到Ac3+30~50℃实现完全奥氏体化，属完全淬火；只有过共析钢才在Ac1+30~50℃做不完全淬火。本条与第56题、简答题29直接对立，按第56 题的结论，本条应为╳。","erratum":"本题答案应改为╳。正确表述：亚共析钢的正常淬火为完全淬火（Ac3+30~50℃）；过共析钢的正常淬火才是不完全淬火（Ac1+30~50℃）。","sourceNumber":63,"id":"j0113","order":112,"chapterId":"phase","chapterIds":["phase"],"answerCorrected":true,"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"碳钢淬火后回火时一般不会出现高温回火脆性。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。高温回火脆性（第二类回火脆性）主要出现在含Cr、Mn、Ni的合金钢中，碳钢一般不明显，故碳钢回火后快冷或缓冷差别不大。","erratum":"","sourceNumber":64,"id":"j0114","order":113,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"工件经氮化处理后不能再进行淬火。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。氮化层硬度高且表面处于残余压应力状态，氮化后不能再淬火（会引起变形、破坏渗层），只能研磨或抛光。","erratum":"","sourceNumber":65,"id":"j0115","order":114,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"对灰铸铁不能进行强化热处理。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"对灰铸铁能进行强化热处理","explanation":"判定正确。灰铸铁可进行去应力退火、正火、表面淬火等，但因片状石墨割裂基体，强化效果有限，故“不能进行”说法太绝对。","erratum":"","sourceNumber":66,"id":"j0116","order":115,"chapterId":"iron","chapterIds":["iron"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"过共析钢经正常淬火后，马氏体的含碳量小于钢的含碳量。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。过共析钢不完全淬火时，加热温度在Ac1~Accm之间，部分二次渗碳体未溶，奥氏体含碳量低于钢的平均含碳量，故淬火后马氏体含碳量偏低。","erratum":"","sourceNumber":67,"id":"j0117","order":116,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"凡能使钢的临界冷却速度增大的合金元素均能减小钢的淬透性。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。Vk增大意味着C曲线左移、过冷奥氏体稳定性下降，淬透性减小；与第59题正好互为逆命题。","erratum":"","sourceNumber":68,"id":"j0118","order":117,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"高速钢淬火后经回火可进一步提高其硬度。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。高速钢回火时析出W、Mo、V的特殊碳化物（二次硬化），同时残余奥氏体在回火冷却中转变为马氏体，硬度不降反升，可达HRC63~66。","erratum":"","sourceNumber":69,"id":"j0119","order":118,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"提高铸铁中碳元素和硅元素的含量,有利于其石墨化，因而碳和硅的含量越高越好。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"过高是，易生成过多且粗大的石墨，降低铸件的性能","explanation":"判定正确。C、Si是促进石墨化的元素，但过高会使石墨粗大、数量过多、基体减少，强度硬度显著下降，一般控制w C2.5%~4.0%、w Si1.0%~3.0%。原“改正”有笔误“过高是”。","erratum":"","sourceNumber":70,"id":"j0120","order":119,"chapterId":"iron","chapterIds":["iron"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"马氏体的强度和硬度总是大于珠光体的。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"马氏体的硬度是大于珠光体的，而强度比珠光体的差","explanation":"判定正确。马氏体硬度虽高但脆性大；高碳片状（孪晶）马氏体因显微裂纹多，强度反而不如珠光体，故“总是大于”不成立。","erratum":"","sourceNumber":71,"id":"j0121","order":120,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"纯铁在室温下的晶体结构为面心立方晶格。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"纯铁在室温下的晶体结构为体心立方晶格","explanation":"判定正确。纯铁室温为α-Fe（体心立方）；912~1394℃才是面心立方γ-Fe；1394℃以上为δ-Fe（体心立方）。","erratum":"","sourceNumber":72,"id":"j0122","order":121,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"马氏体的硬度主要取决于淬火时的冷却速度。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"马氏体的硬度主要取决于其含碳量","explanation":"判定正确。马氏体硬度主要取决于含碳量（0.2%~0.6%范围内近似直线上升，>0.6%后趋缓），冷却速度只决定能否获得马氏体及获得多少。","erratum":"","sourceNumber":73,"id":"j0123","order":122,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"等温淬火的目的是为了获得下贝氏体组织。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。等温淬火是在Ms以上、C曲线鼻尖以下的温度等温，获得下贝氏体，具有良好强韧性配合、变形小、无需回火。","erratum":"","sourceNumber":74,"id":"j0124","order":123,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"对普通低合金钢件进行淬火强化效果不显著。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。普通低合金钢含碳量低（≤0.20%），淬火后为低碳马氏体，硬度提高有限，且大截面淬不透，故淬火强化不显著。","erratum":"","sourceNumber":75,"id":"j0125","order":124,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"高锰钢的性能特点是硬度高，脆性大。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"高锰钢的性能特点是良好的韧性和耐磨性","explanation":"判定正确。高锰钢水韧处理后硬度低（HB180~220）、韧性极高（αk可达200J/cm²以上），是典型的“耐磨不硬”材料。","erratum":"","sourceNumber":76,"id":"j0126","order":125,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"马氏体是碳溶入γ-Fe中形成的过饱和固溶体。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"马氏体是碳溶入α-Fe中形成的过饱和固溶体","explanation":"判定正确。碳溶入γ-Fe形成的是奥氏体；马氏体是碳在α-Fe中的过饱和固溶体。","erratum":"","sourceNumber":77,"id":"j0127","order":126,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"间隙固溶体的溶质原子直径小，其强化效果远比置换固溶体差。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"","explanation":"间隙固溶时溶质原子挤入间隙，造成强烈的不对称晶格畸变，对位错运动的阻碍远大于置换固溶，故间隙固溶强化效果比置换固溶更强，原命题说“远比…差”颠倒了关系。","erratum":"本题答案应改为╳。正确表述：间隙固溶体的溶质原子直径小，但造成的晶格畸变大，其强化效果比置换固溶体强。","sourceNumber":78,"id":"j0128","order":127,"chapterId":"crystal","chapterIds":["crystal"],"answerCorrected":true,"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"硬铝合金经固溶处理后，强度明显提高。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"","explanation":"硬铝合金必须“固溶＋时效”才能显著强化。仅固溶（淬火）后强度提高不多，主要提高塑性和韧性；只有随后自然时效或人工时效析出弥散第二相，强度才大幅上升——这与第105题的结论一致，两题不能都判√。","erratum":"本题答案应改为╳。正确表述：硬铝合金经固溶处理后再经时效，强度才明显提高；仅固溶处理强化效果不显著。","sourceNumber":79,"id":"j0129","order":128,"chapterId":"iron","chapterIds":["iron"],"answerCorrected":true,"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"钢经热处理后，其组织和性能必然会改变。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"钢经热处理后，其组织和性能不一定会改变","explanation":"判定正确。去应力退火、再结晶退火都不发生相变重结晶，组织不变；只有发生相变的热处理（退火、正火、淬火、回火中的重结晶过程）才改变组织和性能。","erratum":"","sourceNumber":80,"id":"j0130","order":129,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"纯金属都是在恒温下结晶的。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。纯金属和共晶成分合金在恒温下结晶；一般合金（如60钢、40Cr）在液相线与固相线之间的温度范围内结晶。","erratum":"","sourceNumber":81,"id":"j0131","order":130,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"所谓白口铸铁是指碳全部以石墨形式存在的铸铁。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"所谓白口铸铁是指碳主要以渗碳体形式存在的铸铁","explanation":"判定正确。白口铸铁中碳主要以渗碳体形式存在，断口呈银白色、硬而脆；碳以石墨形式存在、断口灰暗的是灰口铸铁。","erratum":"","sourceNumber":82,"id":"j0132","order":131,"chapterId":"iron","chapterIds":["iron"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"白口铸铁铁水凝固时不会发生共析转变。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"白口铸铁铁水凝固时会发生共析转变","explanation":"判定正确。白口铸铁凝固后仍要发生共析转变A→P（727℃），室温组织为P＋Fe3CⅡ＋Ld′，故“不会发生共析转变”错误。","erratum":"","sourceNumber":83,"id":"j0133","order":132,"chapterId":"iron","chapterIds":["iron"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"铸件可用再结晶退火细化晶粒。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"","explanation":"再结晶退火只适用于经过冷塑性变形、产生加工硬化的金属，其作用是恢复晶粒形状、消除加工硬化，并不能细化晶粒；铸件是铸造组织，细化晶粒须用完全退火或正火——参见第16题。","erratum":"本题答案应改为╳。正确表述：铸件不能用再结晶退火细化晶粒，应进行完全退火或正火（重结晶退火）细化晶粒。","sourceNumber":84,"id":"j0134","order":133,"chapterId":"crystal","chapterIds":["crystal"],"answerCorrected":true,"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"冷热加工所形成的纤维组织都能使金属出现各向异性。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。冷、热加工形成的纤维（流线）组织都会使性能呈方向性：纵向强度、塑性、韧性高于横向，故锻造零件要求流线沿受力方向分布。","erratum":"","sourceNumber":85,"id":"j0135","order":134,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"奥氏体的塑性比铁素体的高。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。奥氏体为面心立方，滑移系多（12个），塑性优于体心立方的铁素体，δ可达40%~50%，这正是钢在高温奥氏体状态下适合锻造的原因。","erratum":"","sourceNumber":86,"id":"j0136","order":135,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"马氏体转变是通过切变完成的，而不是通过形核和长大来完成的。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"马氏体转变也是通过形核和长大来完成的，转变机制非常复杂","explanation":"判定正确。马氏体转变虽属无扩散的共格切变型转变，但同样经历形核与（切变）长大，只是长大速度极快（接近声速）、长大方式特殊，故“不是通过形核长大”说法错误。","erratum":"","sourceNumber":87,"id":"j0137","order":136,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"金属中的固态相变过程，都是晶粒的重新形核和长大过程。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定可接受，但命题不够严密。多数固态相变（重结晶、脱落、共析）确按形核—长大进行；但调幅分解靠成分起伏连续长大、无明确形核，马氏体转变为切变型，均属例外。","erratum":"","sourceNumber":88,"id":"j0138","order":137,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"位错的滑移可沿晶体中的任意面和任意方向进行。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"位错的滑移可沿晶体中一定的晶面和方向进行","explanation":"判定正确。位错只能沿特定的滑移面（密排面）和滑移方向（密排方向）滑移，不能沿任意面、任意方向进行，这正是晶体滑移具有确定性和方向性的原因。","erratum":"","sourceNumber":89,"id":"j0139","order":138,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"对金属进行冷、热加工都会产生加工硬化。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"对金属进行冷加工会产生加工硬化","explanation":"本条与第24、28题口径冲突，需统一。严格讲冷、热加工过程都会产生加工硬化，只是热加工中随即被动态再结晶消除。按教材“热加工不显示加工硬化”的通行口径，判╳可接受，但“改正”应补充“随即被再结晶消除”这一层意思，不宜简单说“只有冷加工才产生”。","erratum":"","sourceNumber":90,"id":"j0140","order":139,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"在共析温度下，奥氏体的最低含碳量是0.77%。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"在共析温度下，奥氏体的最低含碳量是0","explanation":"判定正确，但“改正”不严密。共析温度（727℃）下奥氏体的含碳量范围是0.0218%~0.77%，说“最低是0.77%”错在把共析成分当成了下限；下限应为0.0218%（P点），而不是0。","erratum":"“改正”应写作：在共析温度下，奥氏体的含碳量范围为0.0218%~0.77%，最低为0.0218%；0.77% 是共析成分，也是该温度下奥氏体的最高含碳量。","sourceNumber":91,"id":"j0141","order":140,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"亚共析钢经正火后，组织中的珠光体含量高于其退火组织中的。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。正火冷速快、过冷度大，先共析铁素体析出量少且珠光体片间距更细，故珠光体含量和强度硬度都高于退火组织。","erratum":"","sourceNumber":92,"id":"j0142","order":141,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"合金的强度和硬度一般都比纯金属高。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。合金化产生固溶强化、第二相强化和细晶强化，故合金的强度、硬度一般高于纯金属（导电、导热性则相反）。","erratum":"","sourceNumber":93,"id":"j0143","order":142,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"白口铸铁在室温下的相组成都为铁素体和渗碳体。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。白口铸铁室温组织为P＋Fe3CⅡ＋Ld′，都是铁素体与渗碳体两相的不同形态组合，故相组成仍为F＋Fe3C。","erratum":"","sourceNumber":94,"id":"j0144","order":143,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"过共析钢的平衡组织中没有铁素体相。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"过共析钢的平衡组织中有铁素体相","explanation":"判定正确。这里考的是“相”与“组织”的区别：过共析钢平衡组织为P＋Fe3CⅡ，没有游离铁素体“组织”，但其相组成仍是F＋Fe3C，铁素体作为组成相存在。","erratum":"","sourceNumber":95,"id":"j0145","order":144,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"过共析钢用球化处理的方法可消除其网状渗碳体。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"","explanation":"球化退火只能把片状、细粒状碳化物变成球状，不能溶解晶界上的网状渗碳体；存在网状渗碳体时必须先正火（加热到Accm以上使网溶解、空冷抑制重新析出），再进行球化退火——参见简答题20、26与选择题41。","erratum":"本题答案应改为╳。正确表述：球化处理不能消除网状渗碳体，须先用正火消除渗碳体网，再进行球化退火。","sourceNumber":96,"id":"j0146","order":145,"chapterId":"phase","chapterIds":["phase"],"answerCorrected":true,"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"采用等温淬火可获得晶粒大小均匀的马氏体。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"采用等温淬火可获得晶粒大小均匀的贝氏体","explanation":"判定正确。等温淬火获得的是下贝氏体，不存在“晶粒大小均匀的马氏体”这种组织，与第52题同义。","erratum":"","sourceNumber":97,"id":"j0147","order":146,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"形状复杂，机械性能要求不高的零件最好选用球铁制造。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"","explanation":"本条宜判╳。形状复杂、力学性能要求不高的零件应选灰铸铁——其流动性好、收缩小、铸造性能优良且价格低；球墨铸铁强度高但收缩大、易产生缩孔缩松，适合受力较大的复杂件（如曲轴、齿轮）。题干“最好选用球铁”不妥。","erratum":"建议改为╳。正确表述：形状复杂、力学性能要求不高的零件宜用灰铸铁制造；球墨铸铁适用于强度、韧性要求较高的零件。","sourceNumber":98,"id":"j0148","order":147,"chapterId":"perf","chapterIds":["perf"],"answerCorrected":true,"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"可锻铸铁的碳当量一定比灰口铸铁低。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定可接受。可锻铸铁由低碳（2.2%~2.8%）、低硅的白口坯经石墨化退火得到，其碳当量一般低于普通灰铸铁（3.6%~4.0%），故铸造时容易得到白口组织，这是可锻铸铁生产的前提。","erratum":"","sourceNumber":99,"id":"j0149","order":148,"chapterId":"iron","chapterIds":["iron"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"铝合金淬火后其晶格类型不会改变。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。铝合金淬火（固溶处理）只是使第二相溶入α-Al形成过饱和固溶体，晶格仍为面心立方，不改变晶格类型（这与钢的淬火有本质区别）。","erratum":"","sourceNumber":100,"id":"j0150","order":149,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"同一钢材在相同加热条件下，水淬比油淬的淬透性好。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"","explanation":"淬透性是钢的固有属性，同一钢材加热条件相同时，无论水淬还是油淬，其淬透性完全相同；水淬只是冷却能力强、使实际淬硬层更深。原判与第62题自相矛盾。","erratum":"本题答案应改为╳。正确表述：同一钢材在相同加热条件下，水淬与油淬的淬透性相同，只是水淬获得的实际淬硬层更深。","sourceNumber":101,"id":"j0151","order":150,"chapterId":"phase","chapterIds":["phase"],"answerCorrected":true,"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"同一钢材在相同加热条件下，小件比大件的淬透性好。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"","explanation":"同理，淬透性与零件尺寸无关。小件淬硬层深、大件中心淬不透，这是“尺寸效应”（质量效应）造成的实际淬硬层差异，并不代表淬透性改变。","erratum":"本题答案应改为╳。正确表述：同一钢材的淬透性与零件尺寸无关；尺寸小者实际淬硬层更深，属尺寸效应。","sourceNumber":102,"id":"j0152","order":151,"chapterId":"phase","chapterIds":["phase"],"answerCorrected":true,"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"工具钢淬火时，冷却速度越快，则所得组织中的残余奥氏体越多。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"工具钢淬火时，冷却速度越快，则所得组织中的马氏体越多","explanation":"判定正确。冷速越快，过冷奥氏体在高温区停留越短、稳定性越低，Ms以下转变越充分，残余奥氏体越少、马氏体越多。反之缓冷（如油淬、分级淬火）残余奥氏体较多。","erratum":"","sourceNumber":103,"id":"j0153","order":152,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"表面淬火后一般不进行回火。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"","explanation":"判定正确。表面淬火后必须及时低温回火（150~200℃），以消除淬火应力、降低脆性、防止磨削裂纹并稳定组织，故“一般不进行回火”错误。","erratum":"","sourceNumber":104,"id":"j0154","order":153,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"对常见铝合金仅进行淬火，强化效果不显著。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。铝合金仅淬火（固溶）后强度提高有限，必须经时效析出弥散第二相才显著强化，与第79题呼应。","erratum":"","sourceNumber":105,"id":"j0155","order":154,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"贝氏体转变是非扩散性转变。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"贝氏体转变是一半扩散性转变","explanation":"判定正确，但“改正”用词应为“半扩散型转变”。贝氏体转变中铁原子不扩散（以切变方式重组），碳原子可以扩散，故称半扩散型（中间型）转变。","erratum":"","sourceNumber":106,"id":"j0156","order":155,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"马氏体转变是非扩散性转变。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。马氏体转变是无扩散的共格切变型转变，原子只做有组织的短距离位移，不进行扩散。","erratum":"","sourceNumber":107,"id":"j0157","order":156,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"金属的晶粒越细小，其强度越高，其塑性越好。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。细晶强化能同时提高强度、硬度和塑性、韧性，是唯一“全面”的强化方式，与第39、10题一致。","erratum":"","sourceNumber":108,"id":"j0158","order":157,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"位错的滑移是金属进行塑性变形的唯一方式。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"位错的滑移是金属进行塑性变形的主要方式","explanation":"判定正确。塑性变形的主要方式是滑移，此外还有孪生、晶界滑动与扩散蠕变，故“唯一方式”错误。","erratum":"","sourceNumber":109,"id":"j0159","order":158,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"表面淬火主要用于高碳钢。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"表面淬火主要用于中碳钢、中碳合金钢","explanation":"判定正确。表面淬火主要用于中碳钢和中碳合金钢（0.35%~0.50%C，如45、40Cr）；高碳钢表层淬火易开裂，低碳钢表层硬度提不高。","erratum":"","sourceNumber":110,"id":"j0160","order":159,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"工件经氮化处理后不必再进行淬火","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。与第65题同义：氮化后表面硬度已很高且存在残余压应力，不必也不能再淬火。","erratum":"","sourceNumber":111,"id":"j0161","order":160,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"可锻铸铁只能通过可锻化退火而得到。","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"可锻铸铁只能通过石墨化退火而得到","explanation":"判定正确，但“改正”意义不大：“可锻化退火”与“石墨化退火”是同一工艺的两种叫法。关键结论是可锻铸铁只能由白口坯经石墨化退火获得，不能锻造。","erratum":"","sourceNumber":112,"id":"j0162","order":161,"chapterId":"iron","chapterIds":["iron"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"提高铸铁中碳、硅、硫和锰元素的含量,有利于其石墨化","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"提高铸铁中碳、硅元素的含量,有利于其石墨化。硫是强烈阻碍石墨化的元素和锰是阻碍石墨化的元素","explanation":"判定正确。C、Si是强促进石墨化元素；S强烈阻碍石墨化（生成 FeS并稳定渗碳体），Mn也阻碍石墨化（生成MnS、稳定碳化物），故不能笼统说提高这四种元素都有利。","erratum":"","sourceNumber":113,"id":"j0163","order":162,"chapterId":"iron","chapterIds":["iron"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"影响石墨化的主要因素是化学成分和加热速度","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"影响石墨化的主要因素是化学成分和冷却速度（╳）","explanation":"判定正确。影响石墨化的两大因素是化学成分（C、Si、S、Mn）和冷却速度（冷速越慢越利于石墨化）。原“改正”末尾仍带“（╳）”，属录入笔误，应删去。","erratum":"","sourceNumber":114,"id":"j0164","order":163,"chapterId":"iron","chapterIds":["iron"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"可锻铸铁通过锻造来得到需要的零件","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["B"],"correction":"可锻铸铁不可锻造","explanation":"判定正确。“可锻铸铁”是因可经可锻化（石墨化）退火而“可锻”得名，实际并不能锻造，塑性、韧性仍远低于钢。","erratum":"","sourceNumber":115,"id":"j0165","order":164,"chapterId":"iron","chapterIds":["iron"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"judge","type":"tf","section":"判断正误","question":"将20钢及60钢同时加热至860 ℃，并保温相同时间，60钢奥氏体晶粒粗大些","options":[{"label":"A","text":"说法正确"},{"label":"B","text":"说法错误"}],"answer":["A"],"correction":"","explanation":"判定正确。860℃时60钢（Ac3约780℃）已完全奥氏体化，奥氏体晶粒可自由长大；20钢（Ac3约870℃）仍处于A＋F两相区，未溶铁素体钉扎晶界、阻碍晶粒长大，故60钢奥氏体晶粒更粗大。","erratum":"","sourceNumber":116,"id":"j0166","order":165,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"钢中的二次渗碳体是指从（）中析出的渗碳体","options":[{"label":"A","text":"从钢液中析出的"},{"label":"B","text":"从奥氏体中析出的"},{"label":"C","text":"从铁素中析出的"},{"label":"D","text":"从马氏体中析出的"}],"answer":["B"],"explanation":"二次渗碳体是奥氏体冷却时沿晶界析出的（A→Fe3CⅡ），故选B。一次渗碳体从液相中析出，三次渗碳体从铁素体中析出——按“从哪个相中析出”来记最清楚。","erratum":"","sourceNumber":1,"id":"j0167","order":166,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"碳钢的下列各组织中，哪个是复相组织（）","options":[{"label":"A","text":"珠光体"},{"label":"B","text":"铁素体"},{"label":"C","text":"渗碳体"},{"label":"D","text":"马氏体"}],"answer":["A"],"explanation":"珠光体是铁素体与渗碳体的层片状机械混合物，属复相组织，故选A。铁素体、渗碳体是单相，马氏体是单相过饱和固溶体，都不算复相。","erratum":"","sourceNumber":2,"id":"j0168","order":167,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"在Fe-Fe3C合金中，其平衡组织中含有二次渗碳量最多的合金的含碳量为（）","options":[{"label":"A","text":"0.0008%"},{"label":"B","text":"0.021%"},{"label":"C","text":"0.77%"},{"label":"D","text":"2.11%"}],"answer":["D"],"explanation":"奥氏体的溶碳量在E点（1148℃、2.11%C）最大，此时可析出的二次渗碳体也最多，约22.64%〔(2.11-0.77)/(6.69-0.77)〕，故选D。","erratum":"","sourceNumber":3,"id":"j0169","order":168,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"下列二元合金的恒温转变中，哪个是共析转变（）","options":[{"label":"A","text":"L+α→β"},{"label":"B","text":"L→α+β"},{"label":"C","text":"γ→α+β"},{"label":"D","text":"α+β→γ"}],"answer":["C"],"explanation":"共析转变是一种固相在恒温下分解为两种新固相，即γ→α+β，故选C。A、B都含液相，属共晶转变； D为加热方向的逆转变。","erratum":"","sourceNumber":4,"id":"j0170","order":169,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"金属的塑性变形主要是通过下列哪种方式进行的（）","options":[{"label":"A","text":"晶粒的相对滑动"},{"label":"B","text":"晶格的扭折"},{"label":"C","text":"位错的滑移"},{"label":"D","text":"位错类型的改变"}],"answer":["C"],"explanation":"常温下塑性变形以位错滑移为主，故选C。晶粒相对滑动只发生在高温（>0.5Tm）；晶格扭折只出现在局部；位错类型改变不构成变形机制。","erratum":"","sourceNumber":5,"id":"j0171","order":170,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"金属的冷变形产生加工硬化现象，使强度、硬度增加，而（）","options":[{"label":"A","text":"塑性、脆性下降"},{"label":"B","text":"韧性、脆性下降"},{"label":"C","text":"塑性、韧性下降"},{"label":"D","text":"弹性、韧性下降"}],"answer":["C"],"explanation":"加工硬化使强度、硬度升高，塑性、韧性下降，故选C。注意“脆性”是升高而非下降，故A、B、D 都错。","erratum":"","sourceNumber":6,"id":"j0172","order":171,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"为改善低碳钢的切削加工性应进行哪种热处理（）","options":[{"label":"A","text":"等温退火"},{"label":"B","text":"完全退火"},{"label":"C","text":"球化退火"},{"label":"D","text":"正火"}],"answer":["D"],"explanation":"低碳钢退火后硬度低、切屑粘刀、表面粗糙，正火可提高硬度、细化晶粒、改善切削加工性，故选D。注意本题选项字母有误（C出现两次），“正火”应标为D。","erratum":"","sourceNumber":7,"id":"j0173","order":172,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"钢中加入除Co之外的其它合金元素一般均能使其C曲线右移，从而（）","options":[{"label":"A","text":"增大 Vk"},{"label":"B","text":"增加淬透性"},{"label":"C","text":"减小淬透性"},{"label":"D","text":"增大淬硬性"}],"answer":["B"],"explanation":"C曲线右移使临界冷速Vk减小，淬透性增大，故选B。淬硬性只取决于含碳量，与C曲线位置无关，故D错。","erratum":"","sourceNumber":8,"id":"j0174","order":173,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"高碳钢淬火后回火时，随回火温度升高其（）","options":[{"label":"A","text":"强度硬度下降，塑性韧性提高"},{"label":"B","text":"强度硬度提高，塑性韧性下降"},{"label":"C","text":"强度韧性提高，塑性韧性下降"},{"label":"D","text":"强度韧性下降，塑性硬度提高"}],"answer":["A"],"explanation":"回火温度升高，马氏体逐步分解、碳化物聚集长大，强度硬度下降，塑性韧性提高，故选A。这是回火的基本规律：低温回火保硬度、高温回火求韧性。","erratum":"","sourceNumber":9,"id":"j0175","order":174,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"过共析钢的正常淬火加热温度应该选择在（）","options":[{"label":"A","text":"Acl+30—50C"},{"label":"B","text":"Ac3+30—50C"},{"label":"C","text":"Accm+30—50C"},{"label":"D","text":"T再+30—50C"}],"answer":["A"],"explanation":"过共析钢正常淬火加热到Ac1+30~50℃（不完全淬火），保留粒状渗碳体以提高耐磨性并减少开裂，故选A。Accm以上加热会使奥氏体晶粒粗大、残余奥氏体增多、易开裂。","erratum":"","sourceNumber":10,"id":"j0176","order":175,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"常见的齿轮材料20CrMnTi的最终热处理工艺应该是（）","options":[{"label":"A","text":"调质"},{"label":"B","text":"淬火+低温回火"},{"label":"C","text":"渗碳"},{"label":"D","text":"渗碳后淬火+低温回火"}],"answer":["D"],"explanation":"20CrMnTi是渗碳钢，必须渗碳后淬火＋低温回火，才能获得表硬心韧的性能，故选D。仅淬火＋低温回火达不到表面高硬度（含碳量太低）。","erratum":"","sourceNumber":11,"id":"j0177","order":176,"chapterId":"steel","chapterIds":["steel"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"常见的调质钢大都属于（）","options":[{"label":"A","text":"低碳低合金钢"},{"label":"B","text":"中碳低合金钢"},{"label":"C","text":"高碳低合金钢"},{"label":"D","text":"低碳中合金钢"}],"answer":["B"],"explanation":"调质钢含碳0.30%~0.50%，属中碳（低）合金钢，故选 B。低碳钢强度不足，高碳钢韧性差，都不适合作调质钢。","erratum":"","sourceNumber":12,"id":"j0178","order":177,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"某一中载齿轮决定用45钢制造，其最终热处理采用下列哪种方案为宜（）","options":[{"label":"A","text":"淬火+低温回火"},{"label":"B","text":"渗碳后淬火+低温回火"},{"label":"C","text":"调质后表面淬火"},{"label":"D","text":"正火"}],"answer":["C"],"explanation":"45钢中载齿轮应调质保证心部综合力学性能，再表面淬火提高齿面硬度与耐磨性，故选C。氮化、渗碳不适用于45钢；单纯正火硬度不够。","erratum":"","sourceNumber":13,"id":"j0179","order":178,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"在Fe-Fe3C合金的退火组织中，含珠光体量最多的合金的碳含量为（）","options":[{"label":"A","text":"0.02%"},{"label":"B","text":"0.77%"},{"label":"C","text":"2.11%"},{"label":"D","text":"4.3%"}],"answer":["B"],"explanation":"珠光体量在共析成分0.77%C时达到最多（100%），超过后出现二次渗碳体、珠光体量反而减少，故选B。","erratum":"","sourceNumber":14,"id":"j0180","order":179,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"下列钢经完全退火后，哪种钢可能会析出网状渗碳体（）","options":[{"label":"A","text":"Q235"},{"label":"B","text":"45"},{"label":"C","text":"60Si2Mn"},{"label":"D","text":"T12"}],"answer":["D"],"explanation":"T12为过共析钢（1.2%C），完全退火加热到Accm以上后缓冷，二次渗碳体沿晶界析出成网，故选D。Q235、45、60Si2Mn均为亚共析钢，不会出现网状渗碳体。","erratum":"","sourceNumber":15,"id":"j0181","order":180,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"下列材料中不宜淬火的是（）","options":[{"label":"A","text":"GCr15"},{"label":"B","text":"W18Cr4V"},{"label":"C","text":"40Cr"},{"label":"D","text":"YT15"}],"answer":["D"],"explanation":"YT15是硬质合金（WC＋TiC＋Co），硬度极高、脆性大，只能磨削加工，不能淬火，故选D。其余三种都是钢，可以淬火。","erratum":"","sourceNumber":16,"id":"j0182","order":181,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"下列合金钢中，耐蚀性最好的是（）","options":[{"label":"A","text":"20CrMnTi"},{"label":"B","text":"40Cr"},{"label":"C","text":"W18Cr4V"},{"label":"D","text":"1Cr18Ni9Ti"}],"answer":["D"],"explanation":"1Cr18Ni9Ti是奥氏体不锈钢，含Cr18%、Ni9%，表面形成致密钝化膜，耐蚀性最好，故选D。注意本题选项字母有误（B重复），D项为1Cr18Ni9Ti。","erratum":"","sourceNumber":17,"id":"j0183","order":182,"chapterId":"steel","chapterIds":["steel"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"下列合金中，哪种合金被称为巴氏合金（）","options":[{"label":"A","text":"铝基轴承合金"},{"label":"B","text":"铅基轴承合金"},{"label":"C","text":"铜基轴承合金"},{"label":"D","text":"锌基轴承合金"}],"answer":["B"],"explanation":"巴氏合金是轴承合金的俗称，分锡基（ZChSnSb11-6）和铅基（ZChPbSb）两类，选项中铅基属之，故选B。","erratum":"","sourceNumber":18,"id":"j0184","order":183,"chapterId":"iron","chapterIds":["iron"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"对球墨铸铁进行高温正火的目的是为了得到下列哪种组织（）","options":[{"label":"A","text":"F+G"},{"label":"B","text":"F+P+G"},{"label":"C","text":"P+G"},{"label":"D","text":"Ld+G"}],"answer":["C"],"explanation":"球墨铸铁高温正火（950~1000℃保温后空冷）使基体全部转变为珠光体，得到P＋G，故选C。低温正火（820~860℃）才得到F＋P＋G。","erratum":"","sourceNumber":19,"id":"j0185","order":184,"chapterId":"iron","chapterIds":["iron"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"为降低低碳冷轧钢板的硬度，宜采用下列哪种工艺（）","options":[{"label":"A","text":"完全退火"},{"label":"B","text":"球化退火"},{"label":"C","text":"再结晶退火"},{"label":"D","text":"等温退火"}],"answer":["C"],"explanation":"低碳冷轧钢板是冷变形产生加工硬化的板材，降低硬度应进行再结晶退火（600~650℃）使变形晶粒重新形核长大；完全退火温度过高会粗化晶粒、增加氧化。","erratum":"原答案D（等温退火）有误，正确答案为C（再结晶退火）。等温退火解决的是缩短退火周期、均匀组织，不是消除冷变形加工硬化。","sourceNumber":20,"id":"j0186","order":185,"chapterId":"perf","chapterIds":["perf"],"answerCorrected":true,"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"感应加热表面淬火的淬硬深度，主要决定于因素（）","options":[{"label":"A","text":"淬透性"},{"label":"B","text":"冷却速度"},{"label":"C","text":"感应电流的大小"},{"label":"D","text":"感应电流的频率"}],"answer":["D"],"explanation":"感应加热时电流频率越高、透入深度越小，淬硬层越浅（δ≈500~700/√f），故选D。这是感应淬火最重要的工艺参数，与钢的淬透性无关。","erratum":"","sourceNumber":21,"id":"j0187","order":186,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"下列材料中耐热性最好的是（）","options":[{"label":"A","text":"GCr15"},{"label":"B","text":"W18Cr4V"},{"label":"C","text":"1Cr18Ni9Ti"},{"label":"D","text":"9SiCr"}],"answer":["C"],"explanation":"1Cr18Ni9Ti为奥氏体不锈钢，高温下组织稳定、抗氧化性和热强性好，耐热性最好，故选C。W18Cr4V热硬性虽好，但抗氧化性和高温组织稳定性不如奥氏体钢。","erratum":"","sourceNumber":22,"id":"j0188","order":187,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"过共析钢的退火组织是（）","options":[{"label":"A","text":"F+Fe3CIII"},{"label":"B","text":"F+P"},{"label":"C","text":"P+Fe3CII"},{"label":"D","text":"P+Fe3CIII"}],"answer":["C"],"explanation":"过共析钢退火（球化退火）组织为P＋Fe3CⅡ（球状），故选C。F＋Fe3CⅢ是工业纯铁，F＋P是亚共析钢，P＋Fe3CⅢ不存在这种组合。","erratum":"","sourceNumber":23,"id":"j0189","order":188,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"下列钢淬硬性从高到低排列正确的是：（）","options":[{"label":"A","text":"40Cr＞60＞T8＞T12"},{"label":"B","text":"40Cr＞T12＞T8＞60"},{"label":"C","text":"60＞40Cr＞T12＞T8"},{"label":"D","text":"T12＞T8＞60＞40Cr"}],"answer":["D"],"explanation":"淬硬性取决于马氏体含碳量，含碳越高淬硬性越好：T12(1.2%)＞T8(0.8%)＞60(0.6%)＞40Cr(0.4%)，故正确排序应为D。原答案A恰好把顺序完全颠倒，是把“淬透性”与“淬硬性”混淆了。","erratum":"原答案A有误，正确答案为D（T12＞T8＞60＞40Cr）。若问的是淬透性，则40Cr最高，但题干问的是淬硬性。","sourceNumber":24,"id":"j0190","order":189,"chapterId":"heat","chapterIds":["heat"],"answerCorrected":true,"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"下列钢经淬火后硬度最低的是（）","options":[{"label":"A","text":"Q235"},{"label":"B","text":"40Cr"},{"label":"C","text":"GCr15"},{"label":"D","text":"45钢"}],"answer":["A"],"explanation":"Q235含碳量仅0.14%~0.22%，淬火后为低碳马氏体，硬度最低（HRC25左右），故选A。GCr15、45钢、40Cr含碳量高得多，淬火硬度都在HRC50以上。","erratum":"","sourceNumber":25,"id":"j0191","order":190,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"对奥氏体不锈钢进行固溶处理的目的是（）","options":[{"label":"A","text":"强化基体"},{"label":"B","text":"提高其韧性"},{"label":"C","text":"消除应力"},{"label":"D","text":"消除碳化物"}],"answer":["D"],"explanation":"固溶处理（1050~1100℃水淬）使晶界Cr23C6溶解、获得单相奥氏体，消除晶间腐蚀倾向，故选D。其目的不是强化基体，反而使强度略降、塑性提高。","erratum":"","sourceNumber":26,"id":"j0192","order":191,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"滚动轴承钢GCr15的最终热处理应该是（）","options":[{"label":"A","text":"淬火+低温回火"},{"label":"B","text":"渗碳+淬火+低温回火"},{"label":"C","text":"淬火+中温回火"},{"label":"D","text":"氮化+淬火+低温回火"}],"answer":["A"],"explanation":"GCr15为高碳铬轴承钢，最终热处理为淬火＋低温回火（150~160℃），获得高硬度、高耐磨性和尺寸稳定性，故选A。渗碳、氮化都不是轴承钢的常规工艺。","erratum":"","sourceNumber":27,"id":"j0193","order":192,"chapterId":"steel","chapterIds":["steel"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"对工件进行分级淬火的目的是（）","options":[{"label":"A","text":"得到下贝氏体"},{"label":"B","text":"减少残余奥氏体量"},{"label":"C","text":"减少工件变形"},{"label":"D","text":"缩短生产周期"}],"answer":["C"],"explanation":"分级淬火是在Ms附近的盐浴中短时停留均温后空冷，减小热应力和组织应力，从而减少工件变形开裂，故选C。获得下贝氏体是等温淬火的目的。","erratum":"","sourceNumber":28,"id":"j0194","order":193,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"钢获得下列哪种组织时有最佳的综合机械性能（）","options":[{"label":"A","text":"M+K"},{"label":"B","text":"P+F"},{"label":"C","text":"B 下"},{"label":"D","text":"M+P"}],"answer":["C"],"explanation":"题目所给选项中，下贝氏体（B下）的碳化物在铁素体条内弥散分布，强度、硬度、塑性和韧性配合最好，综合力学性能最优，应选C。D项“M＋P”不是一种稳定的回火组织，无法代表最佳综合性能。","erratum":"建议核对：原答案D（M＋P）不妥，正确答案宜为C（B下）。若选项中有“回火索氏体”，则回火索氏体才是最佳综合力学性能的典型组织。","sourceNumber":29,"id":"j0195","order":194,"chapterId":"perf","chapterIds":["perf"],"answerCorrected":true,"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"某中等载荷齿轮拟选用45钢制造，其可能的最终热处理工艺应该是（）","options":[{"label":"A","text":"淬火+低温回火"},{"label":"B","text":"调质+表面淬火"},{"label":"C","text":"渗碳+淬火+低温回火"},{"label":"D","text":"淬火+中温回火"}],"answer":["B"],"explanation":"45钢中等载荷齿轮：调质保证心部强韧性，表面淬火提高齿面硬度，故选B。与第13题同一考点，只是表述不同。","erratum":"","sourceNumber":30,"id":"j0196","order":195,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"为了提高45钢的综合机械性能，应进行（）","options":[{"label":"A","text":"正火"},{"label":"B","text":"调质"},{"label":"C","text":"退火"},{"label":"D","text":"淬火+中温回火"}],"answer":["B"],"explanation":"提高45钢综合力学性能的标准工艺是调质（淬火＋高温回火，得回火索氏体），故选B。正火只用于预备热处理，淬火＋中温回火用于弹簧。","erratum":"","sourceNumber":31,"id":"j0197","order":196,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"等温退火相对于一般退火工艺而言，更能（）","options":[{"label":"A","text":"减少工件变形"},{"label":"B","text":"消除应力"},{"label":"C","text":"细化晶粒"},{"label":"D","text":"缩短退火周期"}],"answer":["D"],"explanation":"等温退火把工件快冷到珠光体转变区等温，待转变完成后空冷，可显著缩短退火周期（尤其对合金钢，可缩短一半以上）并使组织均匀，故选D。减少变形是分级淬火的特点。","erratum":"原答案A（减少工件变形）有误，正确答案为D（缩短退火周期）。等温退火最主要的优点是缩短生产周期、组织均匀。","sourceNumber":32,"id":"j0198","order":197,"chapterId":"phase","chapterIds":["phase"],"answerCorrected":true,"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"高速钢淬火后进行多次回火的主要目的是（）","options":[{"label":"A","text":"消除残余奥氏体，使碳化物入基体"},{"label":"B","text":"消除残余奥氏体，使碳化物先分析出"},{"label":"C","text":"使马氏体分解，提高其韧性"},{"label":"D","text":"消除应力，减少工件变形"}],"answer":["B"],"explanation":"高速钢淬火后有20%~25%残余奥氏体，需在560℃三次回火：使残余奥氏体转变为马氏体，同时析出细小特殊碳化物（二次硬化），故选B。","erratum":"","sourceNumber":30,"id":"j0199","order":198,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"金属产生时效强化的主要原因是（）","options":[{"label":"A","text":"形成了高密度位错"},{"label":"B","text":"晶格发生畸变"},{"label":"C","text":"晶格类型发生改变"},{"label":"D","text":"析出亚稳定第二相粒子"}],"answer":["D"],"explanation":"时效强化的本质是过饱和固溶体脱溶析出弥散的亚稳第二相（GP区、过渡相），阻碍位错运动，故选D。晶格畸变只是析出相带来的结果，不是根本原因。","erratum":"","sourceNumber":31,"id":"j0200","order":199,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"钢件出现下述哪种缺陷时，难以用热处理来消除（）","options":[{"label":"A","text":"晶内偏析"},{"label":"B","text":"纤维组织"},{"label":"C","text":"晶粒粗大"},{"label":"D","text":"网状渗碳体"}],"answer":["B"],"explanation":"纤维（流线）组织是夹杂物沿变形方向分布形成的，属定向的组织特征，热处理无法消除，只能通过锻造改善流线分布，故选B。晶内偏析可扩散退火，晶粒粗大可再生退火，网状渗碳体可正火消除。","erratum":"","sourceNumber":32,"id":"j0201","order":200,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"钢的下列组织中热稳定性最差的是（）","options":[{"label":"A","text":"珠光体"},{"label":"B","text":"马氏体"},{"label":"C","text":"回火屈氏体"},{"label":"D","text":"回火索氏体"}],"answer":["C"],"explanation":"回火屈氏体中的碳化物高度弥散，在高温下极易聚集粗化，故热稳定性最差，故选C。回火索氏体碳化物较粗、较稳定；珠光体是平衡组织，高温下虽会球化但转变缓慢。","erratum":"","sourceNumber":33,"id":"j0202","order":201,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"对片状马氏体而言，下列说法哪个是错误的（）","options":[{"label":"A","text":"是位错马氏体"},{"label":"B","text":"是孪晶马氏体"},{"label":"C","text":"是过饱和的a固溶体"},{"label":"D","text":"具有高的强度"}],"answer":["A"],"explanation":"片状马氏体是孪晶马氏体（高碳、硬度高、脆性大），板条马氏体才是位错马氏体，故“是位错马氏体”说法错误，选A。","erratum":"","sourceNumber":34,"id":"j0203","order":202,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"下列各材料中淬火时最容易产生淬火裂纹的材料是（）","options":[{"label":"A","text":"45钢"},{"label":"B","text":"20CrMnTi"},{"label":"C","text":"16Mn"},{"label":"D","text":"W18Cr14V"}],"answer":["A"],"explanation":"45钢含碳0.45%、必须水淬，且Ms点较高、组织应力大，淬火裂纹倾向最大；16Mn含碳仅0.16%，淬火硬度低、几乎不裂；20CrMnTi渗碳后淬油；高合金钢淬透性高、可油淬或分级淬火，开裂倾向小。故宜选A。","erratum":"原卷标注 C（16Mn），但本题解析的结论是「45 钢含碳 0.45%、必须水淬，且 Ms 点较高、组织应力大，淬火裂纹倾向最大……故宜选 A」，故正确答案应为 A（45 钢）。","sourceNumber":35,"id":"j0204","order":203,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"下列诸因素中，哪个是造成45钢淬火硬度偏低的主要原因（）","options":[{"label":"A","text":"加强温度低于Ac3"},{"label":"B","text":"加热温度高于AC3"},{"label":"C","text":"保温时间过长"},{"label":"D","text":"冷却速度大于VK"}],"answer":["A"],"explanation":"加热温度低于Ac3时，亚共析钢未完全奥氏体化，保留先共析铁素体，淬火后硬度偏低（出现“软点”），故选A。冷速大于Vk、保温充分都有利于提高硬度。","erratum":"","sourceNumber":36,"id":"j0205","order":204,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"亚共晶白口铸铁的退火组织中，不可能有下列中的哪种组织（）","options":[{"label":"A","text":"二次渗碳体"},{"label":"B","text":"共析渗碳体"},{"label":"C","text":"一次渗碳体"},{"label":"D","text":"共晶渗碳体"}],"answer":["C"],"explanation":"亚共晶白口铸铁（2.11%~4.3%C）的组织为P＋Fe3CⅡ＋Ld′，其中只有共晶渗碳体、二次渗碳体和共析渗碳体，没有从液相直接析出的一次渗碳体，故选C。","erratum":"","sourceNumber":37,"id":"j0206","order":205,"chapterId":"iron","chapterIds":["iron"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"过共析钢进行下列哪种热处理可能会造成网状渗碳体析出（）","options":[{"label":"A","text":"完全退火"},{"label":"B","text":"再结晶退火"},{"label":"C","text":"正火"},{"label":"D","text":"去应力退火"}],"answer":["A"],"explanation":"完全退火加热到Accm以上使网状渗碳体溶解，但随炉缓冷时二次渗碳体又沿晶界析出成网，故选A。要消除网状必须用正火（空冷抑制析出）。","erratum":"","sourceNumber":38,"id":"j0207","order":206,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"下列指标中，哪个是只决定了钢的成份的性能（）","options":[{"label":"A","text":"淬透性"},{"label":"B","text":"淬硬性"},{"label":"C","text":"淬透层深度"},{"label":"D","text":"VK"}],"answer":["B"],"explanation":"淬硬性只取决于马氏体含碳量，即只由钢的成分决定，故选B。淬透性还受奥氏体化温度、保温时间影响；Vk同样受奥氏体化条件影响；淬透层深度还要看冷却介质和零件尺寸。","erratum":"原答案D（VK）欠妥，正确答案宜为B（淬硬性）。VK虽主要由成分决定，但也随加热温度、保温时间变化，不是“只决定于成分”。","sourceNumber":39,"id":"j0208","order":207,"chapterId":"perf","chapterIds":["perf"],"answerCorrected":true,"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"分级淬火的目的是为了（）","options":[{"label":"A","text":"得到B下"},{"label":"B","text":"增加马氏体的量"},{"label":"C","text":"减少残余奥氏体"},{"label":"D","text":"减少工件变形开裂"}],"answer":["D"],"explanation":"分级淬火的核心目的是减小淬火应力、防止变形开裂，故选D。它与第28题同一考点，只是选项设置不同。","erratum":"","sourceNumber":40,"id":"j0209","order":208,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"过共析钢因过热而析出网状渗碳体组织时，可用下列哪种工艺消除（）","options":[{"label":"A","text":"完全退火"},{"label":"B","text":"等温退火"},{"label":"C","text":"球化退火"},{"label":"D","text":"正火"}],"answer":["D"],"explanation":"过热析出的网状渗碳体必须用正火消除：加热到Accm以上使网溶入奥氏体，空冷时冷速快、二次渗碳体来不及沿晶界析出，从而得到细片珠光体。球化退火不能溶解网状碳化物。","erratum":"原答案C（球化退火）有误，正确答案为D（正火）。参见判断题32、55、96及简答题20。","sourceNumber":41,"id":"j0210","order":209,"chapterId":"phase","chapterIds":["phase"],"answerCorrected":true,"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"下列诸材料中淬透性最好的是（）","options":[{"label":"A","text":"20CrMnTi"},{"label":"B","text":"40Cr"},{"label":"C","text":"GCr15"},{"label":"D","text":"Q235"}],"answer":["A"],"explanation":"20CrMnTi含Mn、Cr，过冷奥氏体稳定，C曲线最靠右，淬透性最好，故选A。40Cr次之；GCr15 含碳高、淬透性中等；Q235最差。","erratum":"","sourceNumber":42,"id":"j0211","order":210,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"下列诸材料中热硬性最好的是（）","options":[{"label":"A","text":"T12"},{"label":"B","text":"9SiCr"},{"label":"C","text":"W18Cr4V"},{"label":"D","text":"YG3"}],"answer":["C"],"explanation":"W18Cr4V是高速钢，含W18%、Cr4%、V1%，600℃仍保持HRC60左右，热硬性最好，故选C。 T12、9SiCr超过200~300℃即软化；YG3是硬质合金，热硬性虽好但属另一类材料。","erratum":"","sourceNumber":43,"id":"j0212","order":211,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"为降低低碳冷轧钢板的硬度,宜采用下列哪种工艺（）","options":[{"label":"A","text":"完全退火"},{"label":"B","text":"球化退火"},{"label":"C","text":"再结晶退火"},{"label":"D","text":"等温退火"}],"answer":["C"],"explanation":"降低冷轧低碳钢板硬度须用再结晶退火，故选C。本题与第20题内容相同但答案正确，第20题的答案D应据此更正。","erratum":"","sourceNumber":44,"id":"j0213","order":212,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"下列诸材料被称为低变形钢适合作冷作模具的是（）","options":[{"label":"A","text":"9SiCr"},{"label":"B","text":"CrWMn"},{"label":"C","text":"Cr12MoV"},{"label":"D","text":"5CrMnMo"}],"answer":["B"],"explanation":"CrWMn含Cr、W、Mn，淬透性好、淬火变形小（微变形钢），适合作冷作模具，故选B。9SiCr用于刃具，Cr12MoV用于重载冷模，5CrMnMo用于热锻模。","erratum":"","sourceNumber":45,"id":"j0214","order":213,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"高速钢经最终热处理后的组织应该是（）","options":[{"label":"A","text":"M+K"},{"label":"B","text":"M+A+K"},{"label":"C","text":"M回+A+K"},{"label":"D","text":"S回+A+K"}],"answer":["C"],"explanation":"高速钢最终热处理为淬火＋三次560℃回火，组织为回火马氏体＋较多粒状碳化物＋少量残余奥氏体，故选C。M＋A＋K是淬火态（未回火）组织。","erratum":"","sourceNumber":46,"id":"j0215","order":214,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"白口铸铁件不具有下列哪个性能（）","options":[{"label":"A","text":"高强度"},{"label":"B","text":"高硬度"},{"label":"C","text":"高耐磨性"},{"label":"D","text":"高脆性"}],"answer":["A"],"explanation":"白口铸铁硬而脆，具有高硬度、高耐磨性和高脆性，唯独抗拉强度低，故选A（不具有高强度）。","erratum":"","sourceNumber":47,"id":"j0216","order":215,"chapterId":"iron","chapterIds":["iron"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"对球墨铸铁件进行下列哪种热处理可得到铁素体基球铁（）","options":[{"label":"A","text":"低温正火"},{"label":"B","text":"高温正火"},{"label":"C","text":"高温退火"},{"label":"D","text":"等温退火"}],"answer":["C"],"explanation":"要获得铁素体基球铁，须进行高温退火（900~950℃保温后随炉冷），使珠光体中的渗碳体分解为铁素体和石墨，故选C。正火得到珠光体基，等温淬火得到贝氏体基。","erratum":"","sourceNumber":48,"id":"j0217","order":216,"chapterId":"iron","chapterIds":["iron"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"下列诸铝合金中,不能进行时效强化的是（）","options":[{"label":"A","text":"LF21"},{"label":"B","text":"LY11"},{"label":"C","text":"LC6"},{"label":"D","text":"LD10"}],"answer":["A"],"explanation":"LF21是铝锰系防锈铝，属不能热处理强化的铝合金，只能冷变形强化，故选A。LY11（铝铜）、LC6（铝镁硅）、LD10都是可时效强化的铝合金。","erratum":"","sourceNumber":49,"id":"j0218","order":217,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"下列各工程塑料中,进行注射成型比较困难的是（）","options":[{"label":"A","text":"聚氯乙烯"},{"label":"B","text":"ABS塑料"},{"label":"C","text":"聚四氟乙烯"},{"label":"D","text":"氨基塑料"}],"answer":["C"],"explanation":"聚四氟乙烯（PTFE）熔点高达327℃、熔体黏度极大且不流动，不能注射成型，只能用冷压烧结成型，故选C。氨基塑料虽为热固性、注射较麻烦，但可用专用注射机成型，并非“比较困难”之首。","erratum":"建议核对：原答案D（氨基塑料）不妥，正确答案宜为C（聚四氟乙烯）。PTFE因熔体黏度极大而根本不能注射成型。","sourceNumber":50,"id":"j0219","order":218,"chapterId":"nonmetal","chapterIds":["nonmetal"],"answerCorrected":true,"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"40Cr钢的碳含量范围是（）","options":[{"label":"A","text":"约40%"},{"label":"B","text":"约4%"},{"label":"C","text":"约0.4%"},{"label":"D","text":"约0.04%"}],"answer":["C"],"explanation":"40Cr中“40”表示平均含碳量0.40%（万分之四十），故选C。这是合金钢牌号的基本读法：两位数字为含碳量万分数。","erratum":"","sourceNumber":51,"id":"j0220","order":219,"chapterId":"steel","chapterIds":["steel"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"冷加工金属经再结晶退火后,下列说法哪个是错误的?（）","options":[{"label":"A","text":"其晶粒形状会改变"},{"label":"B","text":"其机械性能会发生改变"},{"label":"C","text":"其晶格类型会发生改变"},{"label":"D","text":"其晶粒大小会发生改变"}],"answer":["C"],"explanation":"再结晶退火只改变晶粒形状和大小、消除加工硬化，晶格类型始终不变（仍是原来的晶体结构），故“晶格类型会改变”错误，选C。","erratum":"","sourceNumber":52,"id":"j0221","order":220,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"对过共析钢不能进行下列哪种退火处理（）","options":[{"label":"A","text":"完全退火"},{"label":"B","text":"再结晶退火"},{"label":"C","text":"等温退火"},{"label":"D","text":"去应力退火"}],"answer":["A"],"explanation":"过共析钢不能进行完全退火：加热到Accm以上会全部奥氏体化，缓冷析出网状渗碳体，使性能恶化。再结晶退火、去应力退火、等温退火都可进行，故选 A。","erratum":"","sourceNumber":53,"id":"j0222","order":221,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"普通灰口铸铁组织中,不应有下列哪种渗碳体出现?（）","options":[{"label":"A","text":"一次渗碳体"},{"label":"B","text":"二次渗碳体"},{"label":"C","text":"三次渗碳体"},{"label":"D","text":"一次渗碳体和二次渗碳体"}],"answer":["C"],"explanation":"普通灰口铸铁（亚共晶成分）中，碳以片状石墨和珠光体中的共析渗碳体形式存在，不会出现三次渗碳体（三次渗碳体只在碳量极低的工业纯铁中出现），故选C。","erratum":"","sourceNumber":54,"id":"j0223","order":222,"chapterId":"iron","chapterIds":["iron"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"对亚共析钢进行完全退火,其退火温度应为（）","options":[{"label":"A","text":"低于Ac1温度"},{"label":"B","text":"高于 Ac1温度而低于Ac3温度"},{"label":"C","text":"等于Ac3温度"},{"label":"D","text":"Ac3+30至50度"}],"answer":["D"],"explanation":"亚共析钢完全退火须加热到Ac3+30~50℃（全部奥氏体化后缓冷），故选D。低于Ac1是去应力退火， Ac1~Ac3之间是不完全退火。","erratum":"","sourceNumber":55,"id":"j0224","order":223,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"T8钢奥氏体化后进行油淬,其组织为（）","options":[{"label":"A","text":"M"},{"label":"B","text":"M+A残"},{"label":"C","text":"M+B下+A残"},{"label":"D","text":"M+T+A 残"}],"answer":["C"],"explanation":"T8钢（0.8%C）奥氏体化后油淬，冷速介于Vk与下贝氏体临界冷速之间，得到马氏体＋下贝氏体＋残余奥氏体的混合组织，故选C。","erratum":"","sourceNumber":56,"id":"j0225","order":224,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"马氏体的硬度主要决定于其（）","options":[{"label":"A","text":"碳含量"},{"label":"B","text":"合金元素含量"},{"label":"C","text":"冷却速度"},{"label":"D","text":"过冷度"}],"answer":["A"],"explanation":"马氏体硬度主要取决于含碳量（碳的过饱和固溶造成晶格正方畸变），故选A。合金元素、冷速只间接影响。","erratum":"","sourceNumber":57,"id":"j0226","order":225,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"热锻模的最终热处理工艺应该是（）","options":[{"label":"A","text":"淬火+低温回火"},{"label":"B","text":"淬火+中温回火"},{"label":"C","text":"调质"},{"label":"D","text":"调质后表面淬火"}],"answer":["C"],"explanation":"热锻模（5CrMnMo等）要求高热强性、耐热疲劳性和足够韧性，最终热处理为淬火＋中温回火（或500~600℃高温回火），得到回火屈氏体/回火索氏体，硬度HB320~380。教材多按“淬火＋中温回火”作答。","erratum":"建议核对：原答案C（调质）可商榷。按多数教材，热锻模最终热处理为淬火＋中温回火（B）；若按“淬火＋高温回火”理解则为调质，两者回火温度区间相邻，答题时应写出具体回火温度。","sourceNumber":58,"id":"j0227","order":226,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"下列合金中,铬元素含量最少的是（）","options":[{"label":"A","text":"GCr15"},{"label":"B","text":"CrL12"},{"label":"C","text":"1Cr13"},{"label":"D","text":"1Cr18Ni9Ti"}],"answer":["A"],"explanation":"GCr15含Cr约1.5%，Cr12 含12%，1Cr13含13%，1Cr18Ni9Ti 含18%，故铬含量最少的是GCr15，选A。","erratum":"","sourceNumber":59,"id":"j0228","order":227,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"下列合金中，含碳量最少的钢是（）","options":[{"label":"A","text":"GCr15"},{"label":"B","text":"Cr12MoV"},{"label":"C","text":"1Cr13"},{"label":"D","text":"1Cr18Ni9Ti"}],"answer":["D"],"explanation":"1Cr18Ni9Ti的含碳量≤0.12%（牌号“1”表示w C约0.1%），GCr15约1.0%、Cr12MoV 约1.5%、1Cr13约0.1%~0.15%，四者中含碳量最少的是1Cr18Ni9Ti，选D。","erratum":"","sourceNumber":60,"id":"j0229","order":228,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"钢的淬透性主要决定于其（）","options":[{"label":"A","text":"碳含量"},{"label":"B","text":"合金元素含量"},{"label":"C","text":"冷却速度"},{"label":"D","text":"过冷度"}],"answer":["B"],"explanation":"淬透性主要取决于过冷奥氏体的稳定性，即溶入奥氏体的合金元素种类和数量（除Co外均使C曲线右移），故选B。冷却速度只影响实际淬硬层深度，不改变淬透性。","erratum":"原答案C（冷却速度）有误，正确答案为B（合金元素含量）。这是本题库反复出现的概念混淆点，参见判断题62、101、102。","sourceNumber":61,"id":"j0230","order":229,"chapterId":"heat","chapterIds":["heat"],"answerCorrected":true,"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"阻碍石墨化的元素（）","options":[{"label":"A","text":"碳"},{"label":"B","text":"硅"},{"label":"C","text":"磷"},{"label":"D","text":"硫"}],"answer":["D"],"explanation":"硫是强烈阻碍石墨化的元素（生成FeS并稳定渗碳体），故选 D。碳、硅促进石墨化；磷对石墨化影响不大，但会降低韧性、增加冷脆。","erratum":"","sourceNumber":62,"id":"j0231","order":230,"chapterId":"iron","chapterIds":["iron"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"调质处理后可获得综合力学性能好的组织是（）。","options":[{"label":"A","text":"回火马氏体"},{"label":"B","text":"回火托氏体"},{"label":"C","text":"回火索氏体"},{"label":"D","text":"索氏体"}],"answer":["C"],"explanation":"调质（淬火＋高温回火）得到回火索氏体，综合力学性能最好，故选C。回火马氏体硬度高但韧性差，回火托氏体强度高韧性偏低，索氏体是正火/等温转变产物。","erratum":"","sourceNumber":63,"id":"j0232","order":231,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"具有面心立方晶格的金属有（）。","options":[{"label":"A","text":"α－Ｆｅ"},{"label":"B","text":"γ－Ｆｅ"},{"label":"C","text":"δ－Ｆｅ"},{"label":"D","text":"Ｚｎ"}],"answer":["B"],"explanation":"面心立方（fcc）的金属有γ-Fe、Al、Cu、Ni、Au、Ag等；α-Fe、δ-Fe为体心立方，Zn 为密排六方，故选B。","erratum":"","sourceNumber":64,"id":"j0233","order":232,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"合金铁素体比铁素体的强度高，这是由于造成的（）。","options":[{"label":"A","text":"弥散强化"},{"label":"B","text":"加工硬化"},{"label":"C","text":"细晶强化"},{"label":"D","text":"固溶强化"}],"answer":["D"],"explanation":"合金元素溶入铁素体形成固溶体，造成晶格畸变、阻碍位错运动，使强度升高，属固溶强化，故选 D。","erratum":"","sourceNumber":65,"id":"j0234","order":233,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"具有面心立方晶格的金属有（）。","options":[{"label":"A","text":"α－Ｆｅ"},{"label":"B","text":"γ－Ｆｅ"},{"label":"C","text":"δ－Ｆｅ"},{"label":"D","text":"Ｚｎ"}],"answer":["B"],"explanation":"与第68题完全相同（重复命题），答案仍为B（γ-Fe）。","erratum":"","sourceNumber":66,"id":"j0235","order":234,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"碳钢与白口铸铁的化学成分分界点是（）%C。","options":[{"label":"A","text":"0.0218(0.02)"},{"label":"B","text":"0.77"},{"label":"C","text":"2.11"},{"label":"D","text":"4.3"}],"answer":["C"],"explanation":"碳钢与白口铸铁以2.11%C（E点）为分界：小于2.11%为钢，2.11%~6.69%为铸铁，故选C。0.0218%是钢与工业纯铁的分界，0.77%是共析成分，4.3%是共晶成分。","erratum":"","sourceNumber":67,"id":"j0236","order":235,"chapterId":"iron","chapterIds":["iron"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"choice","type":"single","section":"单项选择","question":"加热是钢进行热处理的第一步，其目的是使钢获得（）。","options":[{"label":"A","text":"均匀的基体组织"},{"label":"B","text":"均匀的A体组织"},{"label":"C","text":"均匀的P 体组织"},{"label":"D","text":"均匀的M 体组织"}],"answer":["B"],"explanation":"加热是热处理的第一步，目的是获得均匀的奥氏体组织，为随后的冷却转变做组织准备，故选B。加热温度决定奥氏体的成分和晶粒大小，直接决定冷却后的组织与性能。","erratum":"","sourceNumber":68,"id":"j0237","order":236,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"在 Fe-Fe₃C 合金中，含有二次渗碳体最多的合金是含碳为＿＿＿＿的钢，其二次渗碳体的最大含量为＿＿＿＿。","blanks":["2.11%","22.64%"],"answer":"2.11%；22.64%","explanation":"二次渗碳体最大量出现在奥氏体溶碳量最大处（E点2.11%C）。由杠杆定律： Fe3CⅡ%=(2.11-0.77)/(6.69-0.77)×100%≈22.64%。这是本课程最常考的一个定量结论。","erratum":"","sourceNumber":1,"id":"j0238","order":237,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"冷变形金属在加热时发生的三个过程依次为＿＿＿＿、＿＿＿＿和＿＿＿＿。","blanks":["回复","再结晶","晶粒长大"],"answer":"回复；再结晶；晶粒长大","explanation":"冷变形金属加热的三个阶段：回复（位错重排、内应力下降，强度硬度略降、塑性略升）→再结晶（新晶粒形核长大，加工硬化完全消除）→晶粒长大（晶界迁移、晶粒粗化，性能下降）。","erratum":"","sourceNumber":2,"id":"j0239","order":238,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"对刃具钢的性能要求主要有三个方面，即＿＿＿＿、＿＿＿＿和＿＿＿＿。","blanks":["高的硬度","高耐磨性","高的红硬性（热硬性）"],"answer":"高的硬度；高耐磨性；高的红硬性（热硬性）","explanation":"刃具钢的三项主要性能要求是高硬度（HRC60以上）、高耐磨性（靠弥散碳化物）和高红硬性（高温保持硬度），此外还需一定的强度和韧性以防崩刃。","erratum":"","sourceNumber":3,"id":"j0240","order":239,"chapterId":"steel","chapterIds":["steel"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"1Cr18Ni9Ti 是＿＿＿＿钢，需采用＿＿＿＿处理以获得单相奥氏体；为了阻止 (CrFe)₂₃C₆ 沿晶界析出，还应进行＿＿＿＿处理。","blanks":["奥氏体型不锈","固溶","稳定化"],"answer":"奥氏体型不锈；固溶；稳定化","explanation":"1Cr18Ni9Ti为奥氏体型不锈钢。固溶处理（1050~1100℃水淬）获得单相奥氏体、溶解晶界碳化物；稳定化处理（850~880℃保温）使TiC优先析出，避免Cr23C6沿晶界析出造成贫铬和晶间腐蚀。","erratum":"","sourceNumber":4,"id":"j0241","order":240,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"高速钢锭经锻造退火后的组织为＿＿＿＿；淬火后的组织为＿＿＿＿、粒状碳化物及 20%~25% 的＿＿＿＿；淬火后再经多次回火后的组织为＿＿＿＿、较多的粒状碳化物及少量残余奥氏体。","blanks":["索氏体及粒状碳化物","隐针马氏体","残余奥氏体","回火马氏体"],"answer":"索氏体及粒状碳化物；隐针马氏体；残余奥氏体；回火马氏体","explanation":"高速钢锻造退火后为索氏体＋粒状碳化物（便于切削）；淬火（1280℃盐浴）后为隐针马氏体＋粒状碳化物＋20%~25%残余奥氏体；经三次560℃回火后为回火马氏体＋较多粒状碳化物＋少量残余奥氏体。","erratum":"","sourceNumber":5,"id":"j0242","order":241,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"灰铸铁能否充分石墨化，主要决定于其碳当量和铸后冷却速度。一般而言，碳当量越＿＿＿＿越有利于石墨化，冷却速度越＿＿＿＿越容易形成白口。","blanks":["高","快"],"answer":"高；快","explanation":"碳当量CE=C+Si/3越高，越接近共晶成分，石墨化越充分；冷却速度越快，碳来不及析出石墨而以渗碳体形式存在，越易形成白口。故薄壁件、表面层常出现白口，需高温退火消除。","erratum":"","sourceNumber":6,"id":"j0243","order":242,"chapterId":"iron","chapterIds":["iron"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"球墨铸铁件可通过热处理调整基体组织：＿＿＿＿处理能得到 F+G 基，＿＿＿＿处理能得到 F+P+G 基，而＿＿＿＿处理能获得 P+G 基。","blanks":["退火","低温正火（不完全正火）","正火"],"answer":"退火；低温正火（不完全正火）；正火","explanation":"球墨铸铁的热处理基体：退火→F＋G（高韧性）；正火→P＋G（高强度、耐磨）；等温淬火→B下＋G（综合性能最好）。","erratum":"原答案“调质→F＋P＋G”错误。调质（淬火＋高温回火）得到的是回火索氏体基体，即S回＋G；F＋P＋G是“不完全正火/低温正火”的组织。","sourceNumber":7,"id":"j0244","order":243,"chapterId":"iron","chapterIds":["iron"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"金属结晶时晶粒的大小主要决定于其＿＿＿＿与＿＿＿＿，一般可通过增加过冷度或＿＿＿＿来细化晶粒。","blanks":["形核率","晶核长大速度","变质处理"],"answer":"形核率；晶核长大速度；变质处理","explanation":"晶粒大小取决于形核率N与长大速度G的比值（N/G越大晶粒越细）。细化晶粒的铸造方法：增大过冷度、变质处理、附加振动。注意过冷度增大时N增长快于G，故晶粒细化。","erratum":"","sourceNumber":8,"id":"j0245","order":244,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"热加工纤维组织的形成原因是单向变形造成＿＿＿＿沿变形方向呈流线分布，从而使其产生＿＿＿＿。","blanks":["夹杂物（及偏析）","各向异性"],"answer":"夹杂物（及偏析）；各向异性","explanation":"纤维组织的成因是单向变形使夹杂物、偏析沿变形方向拉长呈流线分布，从而使性能呈方向性（纵向高、横向低），即各向异性。锻造时应使流线沿零件受力方向分布。","erratum":"","sourceNumber":9,"id":"j0246","order":245,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"普通钢与优质钢的区分是以其中＿＿＿＿元素的含量来区分的：＿＿＿＿含量高易使钢产生热脆性，＿＿＿＿含量高易使钢产生冷脆性。","blanks":["S 和 P","S（硫）","P（磷）"],"answer":"S 和 P；S（硫）；P（磷）","explanation":"普通钢与优质钢按S、P含量划分。硫不溶于铁，形成低熔点 FeS共晶（985℃）分布于晶界，热加工时熔化开裂，故S引起热脆；磷溶入铁素体造成强烈畸变、使低温韧性骤降，故P引起冷脆。","erratum":"原答案把“热脆/冷脆”写反了。正确：磷（P）含量高易产生冷脆，硫（S）含量高易产生热脆。","sourceNumber":10,"id":"j0247","order":246,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"所谓本质细晶粒钢，是指该钢正常淬火加热时＿＿＿＿的钢。","blanks":["奥氏体晶粒长大倾向小"],"answer":"奥氏体晶粒长大倾向小","explanation":"本质细晶粒钢指按规定条件（930℃保温8h）测定时奥氏体晶粒长大倾向小的钢，通常用Al脱氧（生成AlN、Al2O3质点钉扎晶界）获得；它与实际晶粒度不同。","erratum":"","sourceNumber":11,"id":"j0248","order":247,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"钢淬火时马氏体转变的转变量主要决定于其＿＿＿＿，与其保温时间无关。","blanks":["冷却终止温度（冷却到达的最低温度）"],"answer":"冷却终止温度（冷却到达的最低温度）","explanation":"马氏体转变量取决于冷却所达到的最低温度——冷到Ms以下越深，转变量越多；冷到Mf以下才转变完全。它与保温时间无关（马氏体转变是无扩散的，等温不能增加转变量，只能发生陈化）。","erratum":"原答案“临界冷却速度”不准确。临界冷速只决定“能否”获得马氏体，而“转变量多少”取决于冷却终止温度（Ms~Mf之间的位置）。","sourceNumber":12,"id":"j0249","order":248,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"钢的淬透性决定于其成分。一般随碳含量的增加，亚共析钢的淬透性＿＿＿＿；当加入除 Co 之外的合金元素时，均能使钢的淬透性＿＿＿＿。","blanks":["增大","提高"],"answer":"增大；提高","explanation":"亚共析钢在0.0218%~0.77%C范围内，随含碳量增加，C 曲线右移，淬透性增大；超过共析成分后淬透性反而下降。除Co以外的合金元素溶入奥氏体后均使C曲线右移、淬透性提高。","erratum":"","sourceNumber":13,"id":"j0250","order":249,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"马氏体有两种典型形态，即强度高而韧性差的＿＿＿＿马氏体和强度低而韧性高的＿＿＿＿马氏体。","blanks":["片状（针状、孪晶）","板条（位错）"],"answer":"片状（针状、孪晶）；板条（位错）","explanation":"马氏体有两种典型形态：片状（针状、孪晶）马氏体，碳含量高、硬度高、韧性差；板条（位错）马氏体，碳含量低、强度高、韧性好。形态主要取决于含碳量。","erratum":"","sourceNumber":14,"id":"j0251","order":250,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"对奥氏体不锈钢进行＿＿＿＿处理可获得单相奥氏体组织，进行＿＿＿＿处理可防止产生晶间腐蚀。","blanks":["固溶","稳定化"],"answer":"固溶；稳定化","explanation":"奥氏体不锈钢的固溶处理获得单相奥氏体组织；稳定化处理（加Ti、Nb的钢在850~880℃保温）使碳化钛优先析出，防止晶间腐蚀。两者常配合使用。","erratum":"","sourceNumber":15,"id":"j0252","order":251,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"对普通灰铸铁工件进行低温退火的目的是为了＿＿＿＿，进行高温退火的目的是为了＿＿＿＿。","blanks":["消除内应力","消除铸件白口、降低硬度"],"answer":"消除内应力；消除铸件白口、降低硬度","explanation":"灰铸铁低温退火（500~600℃）用于消除铸造内应力、稳定尺寸，不改变组织；高温退火（900~950℃）使共晶渗碳体分解、消除表层白口、降低硬度便于切削。","erratum":"","sourceNumber":16,"id":"j0253","order":252,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"材料牌号 QT600-3 中，QT 表示＿＿＿＿，600 表示＿＿＿＿，3 表示＿＿＿＿。","blanks":["球墨铸铁","最低抗拉强度 600MPa","最低断后伸长率 3%"],"answer":"球墨铸铁；最低抗拉强度 600MPa；最低断后伸长率 3%","explanation":"QT600-3：QT＝球墨铸铁，600＝最低抗拉强度600MPa，3＝最低断后伸长率3%。这是球铁牌号的标准读法（与灰铸铁HT150只有抗拉强度一项不同）。","erratum":"","sourceNumber":17,"id":"j0254","order":253,"chapterId":"steel","chapterIds":["steel"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"在 Fe-Fe₃C 相图中，共晶反应式为＿＿＿＿，共析反应式为＿＿＿＿。","blanks":["L(4.3%C)→A(2.11%C)+Fe₃C","A(0.77%C)→F(0.0218%C)+Fe₃C"],"answer":"L(4.3%C)→A(2.11%C)+Fe₃C；A(0.77%C)→F(0.0218%C)+Fe₃C","explanation":"共晶反应L(4.3%C)→A(2.11%C)＋Fe3C，产物为莱氏体；共析反应A(0.77%C)→F(0.0218%C)＋Fe3C，产物为珠光体。","erratum":"","sourceNumber":18,"id":"j0255","order":254,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"常见的合金弹簧钢有＿＿＿＿，其最终热处理工艺为＿＿＿＿，最终组织为＿＿＿＿。","blanks":["60Si2Mn","淬火＋中温回火","回火屈氏体"],"answer":"60Si2Mn；淬火＋中温回火；回火屈氏体","explanation":"60Si2Mn是典型的合金弹簧钢。","erratum":"原答案有两处错误。①最终热处理应为“淬火＋中温回火”（不是去应力退火，去应力退火只用于冷成形弹簧）；②最终组织应为“回火屈氏体”（不是索氏体）。","sourceNumber":19,"id":"j0256","order":255,"chapterId":"steel","chapterIds":["steel"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"钢进行扩散退火的目的是为了＿＿＿＿，进行再结晶退火的目的是为了＿＿＿＿。","blanks":["减少化学成分和组织的不均匀性（消除晶内偏析）","消除加工硬化，便于继续冷加工"],"answer":"减少化学成分和组织的不均匀性（消除晶内偏析）；消除加工硬化，便于继续冷加工","explanation":"扩散（均匀化）退火在Ac3以上100~200℃长时间保温，靠原子扩散消除晶内偏析；再结晶退火在T再以上100~200℃保温，消除冷变形加工硬化，恢复塑性以便继续冷加工。","erratum":"","sourceNumber":20,"id":"j0257","order":256,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"影响铸铁石墨化的主要因素有＿＿＿＿和＿＿＿＿。","blanks":["铸铁的成分（C、Si）","冷却速度"],"answer":"铸铁的成分（C、Si）；冷却速度","explanation":"影响石墨化的两大因素：化学成分（C、Si促进；S、Mn阻碍）和冷却速度（冷速越慢越利于石墨化）。这是铸铁部分的必考点。","erratum":"","sourceNumber":21,"id":"j0258","order":257,"chapterId":"iron","chapterIds":["iron"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"马氏体的硬度主要决定于其＿＿＿＿，钢淬火时获得马氏体量的多少主要决定于其＿＿＿＿。","blanks":["含碳量","冷却终止温度"],"answer":"含碳量；冷却终止温度","explanation":"马氏体硬度由含碳量决定（碳造成晶格正方畸变，固溶强化极强）；获得马氏体量的多少取决于冷却（实际是冷却终止温度，临界冷速只决定“能否”获得）。","erratum":"","sourceNumber":22,"id":"j0259","order":258,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"要降低冷轧钢板的硬度应进行＿＿＿＿退火，要消除合金铸件的枝晶偏析应进行＿＿＿＿退火，要改善高碳钢的切削加工性能应进行＿＿＿＿退火。","blanks":["再结晶","均匀化（扩散）","球化"],"answer":"再结晶；均匀化（扩散）；球化","explanation":"三类退火对应三种目的：消除冷变形加工硬化→再结晶退火；消除枝晶偏析→均匀化（扩散）退火；改善高碳钢切削性、为淬火作组织准备→球化退火。","erratum":"原答案有两处错误。①降低冷轧钢板硬度应为“再结晶退火”（不是完全退火）；②改善高碳钢切削加工性应为“球化退火”（不是等温退火）。","sourceNumber":23,"id":"j0260","order":259,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"常用弹簧的牌号有＿＿＿＿，其热处理工艺为＿＿＿＿，热处理后的组织是＿＿＿＿。","blanks":["65Mn、60Si2Mn","淬火＋中温回火","回火屈氏体"],"answer":"65Mn、60Si2Mn；淬火＋中温回火；回火屈氏体","explanation":"常用弹簧钢牌号65Mn、60Si2Mn；热处理为淬火＋中温回火（350~500℃）；组织为回火屈氏体，具有高的弹性极限和屈强比。注意与第19题的错误答案对照。","erratum":"","sourceNumber":24,"id":"j0261","order":260,"chapterId":"steel","chapterIds":["steel"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"耐磨钢 ZGMn13 进行水韧处理的目的是为了消除＿＿＿＿，得到＿＿＿＿组织，从而保证其具有＿＿＿＿性能。","blanks":["碳化物","单相奥氏体","高的耐磨（加工硬化能力）"],"answer":"碳化物；单相奥氏体；高的耐磨（加工硬化能力）","explanation":"ZGMn13水韧处理（1050~1100℃水淬）的目的是溶解晶界碳化物、获得单相奥氏体，从而保证高的韧性和加工硬化能力，即高的耐磨性。","erratum":"","sourceNumber":25,"id":"j0262","order":261,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"实际晶体中主要存在三类缺陷：点缺陷有＿＿＿＿，线缺陷有＿＿＿＿，面缺陷有＿＿＿＿。","blanks":["空位、间隙原子","位错","晶界、亚晶界"],"answer":"空位、间隙原子；位错；晶界、亚晶界","explanation":"三类晶体缺陷：点缺陷——空位、间隙原子、置换原子；线缺陷——位错（刃型、螺型）；面缺陷 ——晶界、亚晶界、相界、孪晶界。缺陷越多，强度越高（位错强化）。","erratum":"","sourceNumber":26,"id":"j0263","order":262,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"奥氏体不锈钢进行固溶处理的目的是＿＿＿＿，进行稳定化处理的目的是＿＿＿＿。","blanks":["获得单相奥氏体组织、提高耐蚀性","防止晶间腐蚀"],"answer":"获得单相奥氏体组织、提高耐蚀性；防止晶间腐蚀","explanation":"固溶处理的目的：溶解碳化物、获得单相奥氏体、提高耐蚀性（并使材料软化便于加工）；稳定化处理的目的：使TiC/NbC优先析出，防止Cr23C6沿晶界析出引起晶间腐蚀。","erratum":"","sourceNumber":27,"id":"j0264","order":263,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"经＿＿＿＿处理能改善低碳钢的切削加工性能，经＿＿＿＿处理可消除高碳高合金钢中的残余奥氏体。","blanks":["正火","高温回火（多次回火）或冷处理"],"answer":"正火；高温回火（多次回火）或冷处理","explanation":"低碳钢正火可提高硬度、细化晶粒、改善切削加工性。","erratum":"第二空错误。等温退火不能消除残余奥氏体，它的作用是缩短退火周期、均匀组织。消除高碳高合金钢中的残余奥氏体应进行“高温回火（多次回火）”或“冷处理”。","sourceNumber":28,"id":"j0265","order":264,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"轴承合金的组织特点为在＿＿＿＿基体上分布有＿＿＿＿质点，或在硬基体上分布有软质点。","blanks":["软","硬"],"answer":"软；硬","explanation":"轴承合金的组织特点是“软基体上分布硬质点”（如锡基巴氏合金，软基体保证嵌藏性和磨合性，硬质点承担载荷）或“硬基体上分布软质点”（如铅青铜）。两种都能获得良好的减摩性和抗疲劳性。","erratum":"","sourceNumber":29,"id":"j0266","order":265,"chapterId":"iron","chapterIds":["iron"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"合金钢按用途可分为三类，即＿＿＿＿。","blanks":["合金结构钢、合金工具钢和特殊性能钢"],"answer":"合金结构钢、合金工具钢和特殊性能钢","explanation":"合金钢按用途分三类：合金结构钢（渗碳钢、调质钢、弹簧钢、轴承钢）、合金工具钢（刃具钢、模具钢、量具钢）、特殊性能钢（不锈钢、耐热钢、耐磨钢）。","erratum":"","sourceNumber":30,"id":"j0267","order":266,"chapterId":"steel","chapterIds":["steel"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"合金钢中常用的渗碳钢为＿＿＿＿，常用的调质钢为＿＿＿＿，常用的刃具钢为＿＿＿＿，常用的耐磨钢为＿＿＿＿。","blanks":["20CrMnTi","40Cr","9SiCr","ZGMn13"],"answer":"20CrMnTi；40Cr；9SiCr；ZGMn13","explanation":"常用牌号对应：渗碳钢20CrMnTi、调质钢40Cr、刃具钢9SiCr、耐磨钢ZGMn13。记牌号时要能同时说出含碳量、主要合金元素和典型用途。","erratum":"","sourceNumber":31,"id":"j0268","order":267,"chapterId":"steel","chapterIds":["steel"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"金属浇铸时常采用的细化晶粒方法有两种，即＿＿＿＿和＿＿＿＿。","blanks":["变质处理","附加振动"],"answer":"变质处理；附加振动","explanation":"铸造时细化晶粒的方法：变质处理（加变质剂/孕育剂增加非自发形核）和附加振动（机械、超声、电磁振动打碎枝晶），此外还有增大过冷度（提高浇注温度、用金属型等）。","erratum":"","sourceNumber":32,"id":"j0269","order":268,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"铁有三种同素异构体：912℃以下为＿＿＿＿立方结构，912~1394℃为＿＿＿＿立方结构，1394℃以上为＿＿＿＿立方结构。","blanks":["体心","面心","体心"],"answer":"体心；面心；体心","explanation":"铁的同素异构：<912℃为α-Fe（体心立方）→912~1394℃为γ-Fe（面心立方）→1394~1538℃为δ-Fe（体心立方）。这是钢能通过热处理改变组织的根本原因。","erratum":"","sourceNumber":33,"id":"j0270","order":269,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"金属铸锭的组织常分为三层，即外层的＿＿＿＿区、次层的＿＿＿＿区和中心的＿＿＿＿区。","blanks":["细晶","柱状晶","等轴晶"],"answer":"细晶；柱状晶；等轴晶","explanation":"铸锭三区：表层细晶区（模壁激冷、形核多）、次层柱状晶区（定向散热、晶粒择优生长）、中心等轴晶区（心部散热均匀、各向形核）。柱状晶致密但性能有方向性，等轴晶各向同性好。","erratum":"","sourceNumber":34,"id":"j0271","order":270,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"金属晶体通过＿＿＿＿和＿＿＿＿两种方式来发生塑性变形。","blanks":["滑移","孪生"],"answer":"滑移；孪生","explanation":"金属塑性变形的两种基本方式：滑移（沿密排面、密排方向，是主要方式）和孪生（低温、高应变速率时发生）。","erratum":"","sourceNumber":35,"id":"j0272","order":271,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"冷变形金属在加热时随加热温度升高，其组织和性能的变化分为三个阶段，即＿＿＿＿、＿＿＿＿和＿＿＿＿。","blanks":["回复","再结晶","晶粒长大"],"answer":"回复；再结晶；晶粒长大","explanation":"冷变形金属加热三阶段：回复（T=0.3~0.4T熔）、再结晶（0.4T熔以上）、晶粒长大。回复只消除内应力，再结晶才消除加工硬化。","erratum":"","sourceNumber":36,"id":"j0273","order":272,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"在合金钢的组织中，常见的间隙固溶体有＿＿＿＿，常见的间隙化合物有＿＿＿＿。","blanks":["F 和 A","Fe₃C"],"answer":"F 和 A；Fe₃C","explanation":"铁碳合金中的间隙固溶体是F（碳在α-Fe中）和A（碳在γ-Fe中），间隙化合物是Fe3C。","erratum":"原答案“常见的间隙相P和Ld”错误：珠光体和莱氏体是“机械混合物（组织）”，不是相。铁碳合金中的间隙相应为Fe2C（ε相）等简单结构化合物，通常只需答F、A和Fe3C。","sourceNumber":37,"id":"j0274","order":273,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"在 Fe-Fe₃C 合金组织中，一次渗碳体是从＿＿＿＿中析出的，二次渗碳体是从＿＿＿＿中析出的，三次渗碳体是从＿＿＿＿中析出的。","blanks":["液体合金","A（奥氏体）","F（铁素体）"],"answer":"液体合金；A（奥氏体）；F（铁素体）","explanation":"一次渗碳体从液相中析出（L→Fe3CⅠ），粗大、呈板条状；二次渗碳体从奥氏体中析出（A→Fe3CⅡ），沿晶界呈网状；三次渗碳体从铁素体中析出（F→Fe3CⅢ），量极少、呈片状。","erratum":"","sourceNumber":38,"id":"j0275","order":274,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"在铁碳合金的平衡组织中，常见的三个基本相为＿＿＿＿，常见的两个两相组织为＿＿＿＿。","blanks":["F、A 和 Fe₃C","P 和 Ld"],"answer":"F、A 和 Fe₃C；P 和 Ld","explanation":"铁碳合金的三个基本单相是F、A、Fe3C；两个两相组织是P（F＋Fe3C）和Ld（A＋Fe3C，室温为 Ld′）。注意此处“单相组织”实为“基本相”，答题应写“相”。","erratum":"","sourceNumber":39,"id":"j0276","order":275,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"下列各材料的退火组织构成为：工业纯铁＿＿＿＿，亚共析钢＿＿＿＿，过共析钢＿＿＿＿，亚共晶白口铸铁＿＿＿＿，过共晶白口铸铁＿＿＿＿。","blanks":["F","F+P","P+Fe₃CⅡ","P+Ld′+Fe₃CⅡ","Ld′+Fe₃CⅠ"],"answer":"F；F+P；P+Fe₃CⅡ；P+Ld′+Fe₃CⅡ；Ld′+Fe₃CⅠ","explanation":"各材料退火（平衡）组织：工业纯铁F；亚共析钢F＋P；过共析钢P＋Fe3CⅡ；亚共晶白口铸铁P＋Ld′＋Fe3CⅡ；过共晶白口铸铁Ld′＋Fe3CⅠ（一次渗碳体）。","erratum":"","sourceNumber":40,"id":"j0277","order":276,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"钛的熔点为 1680℃，则其再结晶温度约为＿＿＿＿，其再结晶退火温度约为＿＿＿＿。","blanks":["500℃","600~700℃"],"answer":"500℃；600~700℃","explanation":"再结晶温度按T再≈0.4Tm（热力学温度）估算：Ti的Tm=1680+273=1953K，T再≈0.4×1953=781K≈508℃；再结晶退火温度取T再＋100~200℃，即约600~700℃。","erratum":"原答案1054℃、1154℃错误（误把摄氏温度直接乘系数）。正确：再结晶温度约500℃，再结晶退火温度约600~700℃。","sourceNumber":41,"id":"j0278","order":277,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"抗氧化钢中常加入的合金元素有＿＿＿＿等，这主要是因为当这些元素达到一定量时能在钢的表面形成＿＿＿＿。","blanks":["Cr、Si、Al","致密的氧化膜（Cr₂O₃、SiO₂、Al₂O₃）"],"answer":"Cr、Si、Al；致密的氧化膜（Cr₂O₃、SiO₂、Al₂O₃）","explanation":"抗氧化钢常加Cr、Si、Al。它们含量足够时在高温下优先氧化，生成致密、牢固的Cr2O3、SiO2、Al2O3氧化膜，阻止氧继续向内扩散，从而提高抗氧化性。","erratum":"","sourceNumber":42,"id":"j0279","order":278,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"钢加热时奥氏体的形成分为三个阶段，依次为＿＿＿＿、＿＿＿＿和＿＿＿＿。","blanks":["奥氏体晶核的形成及长大","残余渗碳体的溶解","奥氏体成分的均匀化"],"answer":"奥氏体晶核的形成及长大；残余渗碳体的溶解；奥氏体成分的均匀化","explanation":"奥氏体化三阶段：①奥氏体晶核的形成与长大（在F/Fe3C相界形核，向两侧长大）；②残余渗碳体的溶解（碳化物逐渐溶入奥氏体）；③奥氏体成分的均匀化（碳和合金元素扩散均匀）。","erratum":"","sourceNumber":43,"id":"j0280","order":279,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"钢加热奥氏体化后，先淬入水中，再淬入油中，该淬火工艺通常被称为＿＿＿＿。","blanks":["双介质淬火"],"answer":"双介质淬火","explanation":"双介质淬火：先水冷（快冷越过C曲线鼻尖、避免珠光体转变）后油冷（在Ms附近缓冷、减小组织应力），兼得高硬度和低变形开裂倾向，多用于形状复杂的高碳钢件。","erratum":"","sourceNumber":44,"id":"j0281","order":280,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"钢淬火时所得马氏体的形态主要决定于其＿＿＿＿，马氏体的硬度主要决定于其＿＿＿＿，马氏体量的多少主要决定于其＿＿＿＿。","blanks":["成分（含碳量）","含碳量","冷却终止温度"],"answer":"成分（含碳量）；含碳量；冷却终止温度","explanation":"马氏体形态由成分（含碳量）决定；硬度由含碳量决定；马氏体量的多少由冷却终止温度（临界冷速只决定能否获得马氏体）决定。第12、22题与此同理。","erratum":"","sourceNumber":45,"id":"j0282","order":281,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"硬质合金是以＿＿＿＿作为强化相、以＿＿＿＿作粘结基体所形成的复合材料。","blanks":["WC 和 TiC","钴、镍等金属"],"answer":"WC 和 TiC；钴、镍等金属","explanation":"硬质合金以WC、TiC等难熔金属碳化物为强化相（硬质骨架），以Co、Ni等为粘结相，用粉末冶金方法制成。含Co量高则韧性好，含TiC高则耐磨、耐热性好。","erratum":"","sourceNumber":46,"id":"j0283","order":282,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"钢的 Ac3 温度是指＿＿＿＿。","blanks":["加热时先共析铁素体全部溶入奥氏体的终了温度线"],"answer":"加热时先共析铁素体全部溶入奥氏体的终了温度线","explanation":"Ac3是加热时先共析铁素体全部溶入奥氏体的终了温度（即“铁素体消失线”），是亚共析钢完全退火、正火、淬火的下限温度。","erratum":"原答案把Ac3与A3混淆了。A3是冷却时奥氏体开始析出铁素体的温度线；Ac3是加热时铁素体全部溶入奥氏体的温度线，两者相差一个“加热滞后”，Ac3＞A3。","sourceNumber":47,"id":"j0284","order":283,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"渗碳和氮化相比，前者的热处理变形比后者＿＿＿＿，后者的硬化层与基体的结合力比前者＿＿＿＿。","blanks":["大","高"],"answer":"大；高","explanation":"渗碳温度高（900~950℃）、时间长，变形大；氮化温度低（500~580℃）、无相变，变形小（约为渗碳的1/5~1/10）。氮化层与基体是冶金结合、硬度梯度平缓，结合力高于渗碳层。","erratum":"","sourceNumber":48,"id":"j0285","order":284,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"工件渗碳后直接淬火相对于一次淬火的优点是＿＿＿＿，缺点是＿＿＿＿。","blanks":["工艺简单、效率高、成本低、脱碳倾向小","耐磨性较低、变形较大"],"answer":"工艺简单、效率高、成本低、脱碳倾向小；耐磨性较低、变形较大","explanation":"渗碳后直接淬火的优点：工艺简单、生产率高、成本低、脱碳倾向小、可减少一次加热；缺点：表层奥氏体晶粒较粗、残余奥氏体较多，耐磨性略低，且变形较大。","erratum":"","sourceNumber":49,"id":"j0286","order":285,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"碳素结构钢相对于合金结构钢而言，优点是＿＿＿＿，缺点是＿＿＿＿。","blanks":["冶炼、加工简单，价格便宜","淬透性差、缺乏良好的综合力学性能"],"answer":"冶炼、加工简单，价格便宜；淬透性差、缺乏良好的综合力学性能","explanation":"碳素结构钢的优点：冶炼和加工简单、价格便宜、货源广；缺点：淬透性差（大截面淬不透）、回火稳定性差、无特殊性能（不耐蚀、不耐热）。这正是合金钢产生的背景。","erratum":"","sourceNumber":50,"id":"j0287","order":286,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"纯金属的晶格类型主要有＿＿＿＿晶格、＿＿＿＿晶格和密排六方晶格三种。","blanks":["体心立方","面心立方"],"answer":"体心立方；面心立方","explanation":"纯金属的三种典型晶格：体心立方（α-Fe、Cr、W、Mo）、面心立方（γ-Fe、Al、Cu、Ni）、密排六方（Mg、Zn、Ti、Cd）。","erratum":"","sourceNumber":51,"id":"j0288","order":287,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"金属结晶的必要条件是＿＿＿＿。","blanks":["一定的过冷度"],"answer":"一定的过冷度","explanation":"结晶的必要条件是一定的过冷度（ΔT=Tm-T实际＞0），它是结晶的驱动力；此外还需形核和长大。过冷度越大，形核率越高，晶粒越细。","erratum":"","sourceNumber":52,"id":"j0289","order":288,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"金属的塑性变形是在＿＿＿＿应力作用下，主要通过＿＿＿＿来进行的。","blanks":["切","滑移"],"answer":"切；滑移","explanation":"塑性变形是在切应力作用下进行的，主要通过滑移实现（沿密排面、密排方向）。正应力只能引起弹性变形和断裂，不能产生塑性变形。","erratum":"","sourceNumber":53,"id":"j0290","order":289,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"金属中的位错密度越高，则其强度越＿＿＿＿，塑性越＿＿＿＿。","blanks":["高","差"],"answer":"高；差","explanation":"位错密度越高，位错间相互缠结、阻碍运动越严重，强度越高而塑性越差——这正是加工硬化的本质。但位错密度过高（超过10^12/cm²）会产生微裂纹，强度反而下降。","erratum":"","sourceNumber":54,"id":"j0291","order":290,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"纯铁的熔点为 1538℃，则其再结晶温度约为＿＿＿＿，再结晶退火温度约为＿＿＿＿。","blanks":["450℃","550~650℃"],"answer":"450℃；550~650℃","explanation":"按T再≈0.4Tm估算：Fe的Tm=1538+273=1811K，T再≈0.4×1811=724K≈451℃；再结晶退火温度取T再＋100~200℃，即约550~650℃。","erratum":"原答案997℃、1097℃错误（误用摄氏温度计算）。正确：再结晶温度约450℃，再结晶退火温度约550~650℃。第41题同一错法。","sourceNumber":55,"id":"j0292","order":291,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"冷加工和热加工是以金属的＿＿＿＿区分的。","blanks":["再结晶温度"],"answer":"再结晶温度","explanation":"冷加工与热加工以再结晶温度划分：变形温度高于T再为热加工，低于T再为冷加工。注意这是“相对”概念，铅、锡在室温下加工就属于热加工。","erratum":"","sourceNumber":56,"id":"j0293","order":292,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"所谓“相”是指合金中＿＿＿＿和＿＿＿＿相同的组成部分。","blanks":["晶体结构","化学成分"],"answer":"晶体结构；化学成分","explanation":"相的定义要点：晶体结构相同、化学成分相同，且有界面与其他部分分开。二者缺一不可（同结构不同成分，或同成分不同结构，都属不同相）。","erratum":"","sourceNumber":57,"id":"j0294","order":293,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"合金中的基本相分为＿＿＿＿和＿＿＿＿两类。","blanks":["固溶体","金属化合物"],"answer":"固溶体；金属化合物","explanation":"合金中的基本相分两类：固溶体（以溶剂晶格为基，如F、A）和金属化合物（具有新晶格，如Fe3C）。此外还有机械混合物，但那是组织而非相。","erratum":"","sourceNumber":58,"id":"j0295","order":294,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"按照溶质原子在溶剂中位置的不同，固溶体分为＿＿＿＿和＿＿＿＿。","blanks":["置换固溶体","间隙固溶体"],"answer":"置换固溶体；间隙固溶体","explanation":"按溶质原子所占位置，固溶体分为置换固溶体（溶质占据溶剂结点位置）和间隙固溶体（溶质挤入晶格间隙）。前者可无限或有限固溶，后者必定有限。","erratum":"","sourceNumber":59,"id":"j0296","order":295,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"固溶体按溶解度大小不同分为＿＿＿＿和＿＿＿＿。","blanks":["有限固溶体","无限固溶体"],"answer":"有限固溶体；无限固溶体","explanation":"按溶解度分为有限固溶体（溶解度有极限，如Cu-Zn、C在Fe中）和无限固溶体（任意比例互溶，如Cu-Ni、Au-Ag）。无限固溶只可能是置换固溶体。","erratum":"","sourceNumber":60,"id":"j0297","order":296,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"金属化合物根据其形成条件及结构特点分为＿＿＿＿、＿＿＿＿和＿＿＿＿三类。","blanks":["正常价化合物","电子化合物","间隙化合物"],"answer":"正常价化合物；电子化合物；间隙化合物","explanation":"金属化合物按形成条件和结构特点分三类：正常价化合物（按原子价规律，如Mg2Pb）、电子化合物（按电子浓度，如CuZn、Cu3Sn）、间隙化合物（过渡族金属与C、N、H、B形成，如Fe3C）。","erratum":"","sourceNumber":61,"id":"j0298","order":297,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"钢中常见的化合物大多数属于＿＿＿＿化合物，其共同的性能特点是熔点＿＿＿＿、硬度＿＿＿＿、脆性大。","blanks":["间隙","高","高"],"answer":"间隙；高；高","explanation":"钢中常见的化合物（Fe3C、Cr23C6、TiC等）大多属间隙化合物，其共同特点是熔点高、硬度高、脆性大。它们是钢中强化相和耐磨相的主要来源。","erratum":"原答案“正常价化合物”错误。Fe3C等过渡族金属碳化物属“间隙化合物”，钢中极少出现正常价化合物。","sourceNumber":62,"id":"j0299","order":298,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"铁碳合金的基本相中，塑性最好的是＿＿＿＿，强度最高的是＿＿＿＿，硬度最高的是＿＿＿＿。","blanks":["A（奥氏体）","P（珠光体，按组织计）","Cm（渗碳体）"],"answer":"A（奥氏体）；P（珠光体，按组织计）；Cm（渗碳体）","explanation":"铁碳合金中塑性最好的是A（面心立方、滑移系多），硬度最高的是 Cm（Fe3C，约800HBW）。强度最高的表述有争议：按组织讲珠光体强度最高，按相讲渗碳体最硬但极脆，答题时建议写“珠光体（组织）”。","erratum":"","sourceNumber":63,"id":"j0300","order":299,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"珠光体是指＿＿＿＿和＿＿＿＿所形成的两相组织，其形态一般是层片状。","blanks":["F","Cm（Fe₃C）"],"answer":"F；Cm（Fe₃C）","explanation":"珠光体是F与Cm（渗碳体）组成的两相组织，一般呈层片状（“粗片状”指退火态珠光体片间距较粗，正火态为细片状即索氏体）。","erratum":"","sourceNumber":64,"id":"j0301","order":300,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"二次渗碳体只可能出现于碳含量大于＿＿＿＿的钢中，其形态是＿＿＿＿。","blanks":["0.77%","网状"],"answer":"0.77%；网状","explanation":"二次渗碳体只在碳含量大于0.77%（共析成分）的钢中出现，沿奥氏体晶界析出，呈网状。网状渗碳体使钢变脆，须用正火消除。","erratum":"","sourceNumber":65,"id":"j0302","order":301,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"灰口铸铁和白口铸铁的组织相比，灰口铸铁中不应有＿＿＿＿组织，而白口铸铁中没有＿＿＿＿组织。","blanks":["游离渗碳体（莱氏体）","片状石墨"],"answer":"游离渗碳体（莱氏体）；片状石墨","explanation":"灰口铸铁中的碳主要以片状石墨存在，基体为F和/或P，不含（或极少含）游离渗碳体；白口铸铁中的碳主要以渗碳体存在，没有片状石墨。这是两类铸铁的本质区别。","erratum":"","sourceNumber":66,"id":"j0303","order":302,"chapterId":"iron","chapterIds":["iron"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"将 45 钢加热至 Ac1 温度时，所得奥氏体的含碳量为＿＿＿＿；继续升高温度，奥氏体的含碳量会＿＿＿＿。","blanks":["0.77%","降低（减小）"],"answer":"0.77%；降低（减小）","explanation":"45钢加热到Ac1（727℃）时，珠光体刚转变为奥氏体，此时奥氏体为共析成分，含碳量0.77%；继续升温，铁素体逐渐溶入，奥氏体含碳量向钢的平均成分0.45%靠近，即不断降低。","erratum":"原答案两空均错。正确：加热到Ac1时所得奥氏体含碳量为0.77%；继续升高温度，奥氏体含碳量会“降低”（减小），最终趋近0.45%。","sourceNumber":67,"id":"j0304","order":303,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"钢的奥氏体晶粒长大倾向性与钢的＿＿＿＿有关。","blanks":["化学成分（本质晶粒度）以及加热温度、保温时间"],"answer":"化学成分（本质晶粒度）以及加热温度、保温时间","explanation":"奥氏体晶粒长大倾向主要取决于钢的本质晶粒度（冶炼脱氧方式，Al脱氧为本质细晶粒钢）以及加热温度和保温时间。","erratum":"原答案“加热方法”不准确。应改为：与钢的“化学成分（本质晶粒度）”和“加热温度、保温时间”有关。","sourceNumber":68,"id":"j0305","order":304,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"将 45 钢加热至 Ac1 温度长时间保温后，其组织为 F+A，其中 F 的含碳量为＿＿＿＿%，A 的含碳量为＿＿＿＿%。","blanks":["0.0218","0.77"],"answer":"0.0218；0.77","explanation":"45钢（0.45%C）在Ac1（727℃）长时间保温，处于F＋A两相区，两相的成分由相图确定，与钢的平均成分无关：F含碳0.0218%（P点），A含碳0.77%（S 点）。两相相对量由杠杆定律：F≈44%、A≈56%。","erratum":"","sourceNumber":69,"id":"j0306","order":305,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"亚共析钢的正火温度为 Ac3 以上＿＿＿＿℃，过共析钢的正火温度为 Accm 以上＿＿＿＿℃。","blanks":["30~50","30~50"],"answer":"30~50；30~50","explanation":"亚共析钢正火/退火加热到Ac3以上30~50℃（全部奥氏体化）；过共析钢则加热到Accm以上30~50℃（使网状二次渗碳体溶解），空冷得到细片珠光体，避免网状析出。","erratum":"","sourceNumber":70,"id":"j0307","order":306,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"钢淬火后马氏体组织粗细主要取决于奥氏体的＿＿＿＿。","blanks":["晶粒大小"],"answer":"晶粒大小","explanation":"马氏体的粗细（针长、板条尺寸）取决于原奥氏体晶粒大小：奥氏体晶粒越粗，马氏体越粗大，且显微裂纹越多、韧性越差。故淬火加热温度必须严格控制，防止奥氏体晶粒粗化。","erratum":"","sourceNumber":71,"id":"j0308","order":307,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"工具钢一般都属于＿＿＿＿碳钢，其机加工前的预处理工艺为＿＿＿＿，机加工后的最终热处理工艺为＿＿＿＿。","blanks":["优质（或高级优质）","退火","淬火＋低温回火"],"answer":"优质（或高级优质）；退火；淬火＋低温回火","explanation":"工具钢一般为优质或高级优质碳素工具钢（T7A~T13A）。机加工前的预处理是退火（降低硬度、改善切削、为淬火作组织准备）；最终热处理为淬火＋低温回火（获得高硬度高耐磨性并消除应力）。","erratum":"","sourceNumber":72,"id":"j0309","order":308,"chapterId":"steel","chapterIds":["steel"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"量具钢除要求高硬度外，还要求有高＿＿＿＿性和高＿＿＿＿性。","blanks":["耐磨","尺寸稳定"],"answer":"耐磨；尺寸稳定","explanation":"量具钢除高硬度（HRC60以上）外，还要求高耐磨性（保证寿命）和高尺寸稳定性（防止使用中变形、失去精度），因此常需淬火＋冷处理＋低温长时间时效。","erratum":"","sourceNumber":73,"id":"j0310","order":309,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"常用不锈钢按其组织构成分为＿＿＿＿不锈钢、＿＿＿＿不锈钢、＿＿＿＿不锈钢。","blanks":["马氏体","铁素体","奥氏体"],"answer":"马氏体；铁素体；奥氏体","explanation":"不锈钢按组织分为马氏体型（1Cr13、2Cr13）、铁素体型（1Cr17）、奥氏体型（1Cr18Ni9Ti）三类，此外还有双相型和沉淀硬化型。组织类型由Cr、Ni当量比决定。","erratum":"","sourceNumber":74,"id":"j0311","order":310,"chapterId":"steel","chapterIds":["steel"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"合金元素大多数都能提高钢的＿＿＿＿，故合金钢的淬火效果优于碳钢。","blanks":["淬透性"],"answer":"淬透性","explanation":"合金元素大多使C曲线右移、提高淬透性，故合金钢的淬透性优于碳钢；同时合金元素还提高回火稳定性和强韧性。","erratum":"原答案“合金元素大多促进奥氏体的形成，故合金钢的淬火优于碳钢”表述有误。多数合金元素反而减慢奥氏体化（需更高温度、更长保温），它们的作用是提高淬透性，不是促进奥氏体形成。","sourceNumber":75,"id":"j0312","order":311,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"不锈钢的成分特点是碳含量＿＿＿＿和＿＿＿＿含量高。","blanks":["较低（wC≤0.12%）","铬（wCr≥12%）"],"answer":"较低（wC≤0.12%）；铬（wCr≥12%）","explanation":"不锈钢的成分特点是低碳（w C≤0.12%，甚至超低碳≤0.03%）和高铬（w Cr≥12%）。低碳是为了避免形成Cr23C6造成贫铬；高铬是为了形成致密钝化膜。","erratum":"","sourceNumber":76,"id":"j0313","order":312,"chapterId":"steel","chapterIds":["steel"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"碳在铸铁中主要以＿＿＿＿和＿＿＿＿的形式存在。","blanks":["渗碳体","石墨"],"answer":"渗碳体；石墨","explanation":"碳在铸铁中以两种形式存在：渗碳体（化合态，白口铸铁中为主）和石墨（游离态，灰口铸铁中为主）。石墨的形状（片状、团絮状、球状、蠕虫状）决定铸铁的性能。","erratum":"","sourceNumber":77,"id":"j0314","order":313,"chapterId":"iron","chapterIds":["iron"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"提高铸铁中＿＿＿＿元素和＿＿＿＿元素的含量，有利于其石墨化。","blanks":["碳","硅"],"answer":"碳；硅","explanation":"碳和硅都是强促进石墨化的元素：碳提供石墨的碳源，硅降低碳在铁中的溶解度、使碳更易析出石墨。故提高C、Si含量有利于石墨化（但不能过高，否则石墨粗大、性能下降）。","erratum":"","sourceNumber":78,"id":"j0315","order":314,"chapterId":"iron","chapterIds":["iron"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"blank","type":"blank","section":"填空题","question":"正火与退火的主要差别是前者冷却速度＿＿＿＿，得到的组织强度和硬度也＿＿＿＿。","blanks":["较快","稍高一些"],"answer":"较快；稍高一些","explanation":"正火与退火的主要差别是冷却速度：正火为空冷（较快），退火为炉冷（很慢）。冷速快则珠光体片间距细、组织细，强度硬度较高而塑性略低；正火周期短、成本低，故常用来代替退火。","erratum":"","sourceNumber":79,"id":"j0316","order":315,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"说明下列符号各是什么指标？各代表什么意思？（每个1分，共6分）(1)σe（2）σ s （3）ψ （4）αk (5)HRC (6)δ","answer":"（1）σe：弹性模量；刚度指标（1分）（2）σs：屈服点（强度）；强度指标（1 分）（3）ψ：断面收缩率；塑性指标（1分）（4）αk：冲击韧度；韧性指标（1分）（5）HRC：洛氏硬度；硬度指标（1分）(6)δ断后伸长率（1分）","explanation":"六个符号分属三类指标：强度指标σe（弹性极限）、σs（屈服强度）；塑性指标ψ（断面收缩率）、δ（断后伸长率）；硬度和韧性指标HRC（洛氏硬度C标尺）、αk（冲击韧度）。答题时先归类再解释，得分点最清楚。","erratum":"原答案第（1）处错误：σe是“弹性极限”，不是弹性模量。弹性模量用E表示，是刚度指标；σe是材料保持纯弹性变形的最大应力，属强度指标。","sourceNumber":1,"id":"j0317","order":316,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"何谓共晶反应和共析反应?试比较这两种反应的异同点.（6分）","answer":"共晶反应：指一定成分的液体合金，在一定温度下，同时结晶出成分和晶格均不相同的两种晶体的反应。（1分）共析反应：由特定成分的单相固态合金，在恒定的温度下，分解成两个新的，具有一定晶体结构的固相的反应。（1分）共同点：反应都是在恒温下发生，反应物和产物都是具有特定成分的相，都处于三相平衡状态。（2分）不同点：共晶反应是一种液相在恒温下生成两种固相的反应；共析反应是一种固相在恒温下生成两种固相的反应；而包晶反应是一种液相与一种固相在恒温下生成另一种固相的反应。（2分）","explanation":"本题得分点：①两个定义各1分；②共同点2分——都是恒温下进行、都是三相平衡、反应物和产物都是特定成分的相；③不同点2分——共晶的反应物是液相，共析的反应物是固相。答案完整，可补充“共晶产物为莱氏体、共析产物为珠光体”使答案更具体。","erratum":"","sourceNumber":2,"id":"j0318","order":317,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"何谓铁素体（F）,奥氏体（A），渗碳体（Fe3C），珠光体（P）,莱氏体（Ld）？它们的结构、组织形态、性能等各有何特点？（6分）（任抽两种）","answer":"铁素体（F）：铁素体是碳在α-Fe中形成的间隙固溶体，为体心立方晶格。由于碳在α-Fe中的溶解度`很小，它的性能与纯铁相近。塑性、韧性好，强度、硬度低。它在钢中一般呈块状或片状。奥氏体（A）：奥氏体是碳在γ-Fe中形成的间隙固溶体，面心立方晶格。因其晶格间隙尺寸较大，故碳在γ-Fe中的溶解度较大。有很好的塑性。渗碳体（Fe3C）：铁和碳相互作用形成的具有复杂晶格的间隙化合物。渗碳体具有很高的硬度，但塑性很差，延伸率接近于零。在钢中以片状存在或网络状存在于晶界。在莱氏体中为连续的基体，有时呈鱼骨状。珠光体（P）：由铁素体和渗碳体组成的机械混合物。铁素体和渗碳体呈层片状。珠光体有较高的强度和硬度，但塑性较差。莱氏体（Ld）：由奥氏体和渗碳体组成的机械混合物。在莱氏体中，渗碳体是连续分布的相，奥氏体呈颗粒状分布在渗碳体基体上。由于渗碳体很脆，所以莱氏体是塑性很差的组织。（1分）","explanation":"五种组织的答题模板：化学成分→晶格类型→形态→性能。F：碳在α-Fe中的间隙固溶体，体心立方，块状/片状，软韧；A：碳在γ-Fe中的间隙固溶体，面心立方，等轴状，塑性好；Fe3C：间隙化合物，复杂斜方晶格，片状/网状/球状，硬脆；P：F＋Fe3C层片状混合物，强度硬度较高、塑性差；Ld：A＋Fe3C共晶混合物（室温为P＋Fe3CⅡ＋Fe3CⅠ），硬脆。","erratum":"","sourceNumber":3,"id":"j0319","order":318,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"根据Fe-Fe3C相图，说明含碳量为 1.0%的钢比含碳量为0.5%的钢硬度高。（4分）","answer":"钢中随着含碳量的增加，渗碳体的含量增加，渗碳体是硬脆相，因此含碳量为1.0%的钢比含碳量为0.5%的钢硬度高。","explanation":"答题要点：含碳量升高→渗碳体（硬脆相）数量增多→硬度升高。0.5%钢组织为F＋P（约38%P），1.0%钢为P＋Fe3CⅡ，渗碳体量由约7%增至约15%，故1.0%钢硬度更高。注意此处只问硬度，不含强度（强度在1.0%以上反而下降，见第5题）。","erratum":"","sourceNumber":4,"id":"j0320","order":319,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"根据Fe-Fe3C相图，说明在室温下，含碳0.8% 的钢其强度比含碳1.2%的钢高。（4分）","answer":"因为在钢中当含碳量超过1.0%时，所析出的二次渗碳体在晶界形成连续的网络状，使钢的脆性增加，导致强度下降。因此含碳0.8%的钢其强度比含碳1.2%的钢高。","explanation":"关键在“强度”而非“硬度”。含碳量超过1.0%后，二次渗碳体沿晶界形成连续网状，相当于在晶界预置了裂纹源，受力时极易沿网开裂，故强度（尤其塑性、韧性）显著下降。0.8%钢为单一珠光体，无网状渗碳体，强度最高。","erratum":"","sourceNumber":5,"id":"j0321","order":320,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"根据Fe-Fe3C相图，说明在1100℃，含碳0.4%的钢能进行锻造，含碳4.0%的生铁不能锻造。（4分）","answer":"在1100℃时，含碳0.4%的钢的组织为奥氏体，奥氏体的塑性很好，因此适合于锻造；含碳4.0%的生铁的组织中含有大量的渗碳体，渗碳体的硬度很高，不适合于锻造。","explanation":"1100℃时0.4%C处于A单相区，奥氏体面心立方、塑性极好（δ可达40%以上），变形抗力小，适合锻造；4.0%C已超过共晶成分，组织为L＋Fe3CⅠ（液相＋粗大一次渗碳体），渗碳体硬脆、塑性近于零，锻造必然开裂，只能铸造。","erratum":"","sourceNumber":6,"id":"j0322","order":321,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"根据Fe-Fe3C相图，说明绑轧物件一般用铁丝（镀锌低碳钢丝），而起重机吊重物却用钢丝绳（用60、65、70、75 等钢制成）。(5分)","answer":"为了便于绑轧，要求有很好的塑性，因此应选用塑性很好的低碳钢丝（2分）；而起重机吊重物用钢丝绳除要求高的强度并要求有一定的韧性，60、65、70、75 属于中、高碳钢，比低碳钢的强度高得多，高的弹性极限，且有一定的韧性，这样在吊重物时不会产生塑性变形和突然断裂而造成事故（3分）。","explanation":"选材依据是“塑性”与“强度＋韧性”的不同要求：绑扎铁丝要求极好的塑性以便弯折，故用低碳钢丝（Q195、Q215，δ达25%以上）；起重机钢丝绳要求高强度、高弹性极限并有一定韧性，故用60、65、70、75中高碳钢经冷拉和淬火回火处理。答题时应把“性能要求→成分→组织”这条逻辑写出来。","erratum":"","sourceNumber":7,"id":"j0323","order":322,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"根据Fe-Fe3C相图，说明钳工锯T8，T10,T12 等钢料时比锯10,20 钢费力，锯条容易磨钝。","answer":"T8, T10,T12 属于碳素工具钢，含碳量为0.8%，1.0%，1.2%，因而钢中渗碳体含量高，钢的硬度较高；而10,20钢为优质碳素结构钢，属于低碳钢，钢的硬度较低，因此钳工锯T8，T10,T12等钢料时比锯10,20 钢费力，锯条容易磨钝。","explanation":"T8、T10、T12的含碳量分别为0.8%、1.0%、1.2%，属过共析钢，组织中渗碳体量大、硬度高（HRC60以上）；10、20钢为低碳钢，组织以铁素体为主，硬度低（HB100~150）。锯削时硬度差直接体现为切削阻力大、锯齿迅速磨钝。","erratum":"","sourceNumber":8,"id":"j0324","order":323,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"根据Fe-Fe3C相图，说明钢适宜于通过压力加工成形，而铸铁适宜于通过铸造成形。","answer":"因为钢的含碳量范围在0.02%~2.14%之间，渗碳体含量较少，铁素体含量较多，而铁素体有较好的塑韧性，因而钢适宜于压力加工；而铸铁组织中含有大量以渗碳体为基体的莱氏体，渗碳体是硬脆相，因而铸铁适宜于通过铸造成形。","explanation":"答题要落到“组织决定工艺性”：钢的含碳量0.0218%~2.11%，组织以F＋P为主，F塑性好，故可压力加工成形；铸铁含碳高（2.5%~4.0%），组织中有大量莱氏体或以渗碳体为基体，硬脆、塑性近于零，不能承受塑性变形，只能利用其良好的流动性铸造成形。注意钢的含碳量上限规范写法是2.11%（有的教材写2.14%，属旧数据）。","erratum":"","sourceNumber":9,"id":"j0325","order":324,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"下列零件或工具用何种碳钢制造：手锯锯条、普通螺钉、车床主轴。（6分）","answer":"手锯锯条：它要求有较高的硬度和耐磨性，因此用碳素工具钢制造，如T9、T9A、T10、T10A、T11、T11A。（2分）普通螺钉：它要保证有一定的机械性能，用普通碳素结构钢制造，如Q195、Q215、Q235。（2分）车床主轴：它要求有较高的综合机械性能，用优质碳素结构钢，如30、35、40、45、50。（2分）","explanation":"按“性能要求→钢种”作答：手锯锯条要求高硬度、高耐磨，选碳素工具钢T9A~T11A（淬火＋低温回火）；普通螺钉只要求一定强度和良好塑性、可加工性，选普通碳素结构钢Q195、Q215、Q235（可冷镦）；车床主轴要求良好的综合力学性能，选优质碳素结构钢30~50（调质处理）。","erratum":"","sourceNumber":10,"id":"j0326","order":325,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"金属晶粒大小对金属的性能有何影响?说明铸造时细化晶粒的方法及其原理.","answer":"金属晶粒越细，金属的强度越高，塑性和韧性也越好，反之力学性能越差。","explanation":"晶粒大小对性能的影响可用一句话概括：晶粒越细，强度、硬度越高，塑性、韧性也越好（细晶强化），且裂纹扩展路径曲折、韧脆转变温度降低。注意原答案只答了“强度、塑性、韧性”，漏掉了“硬度”和“韧脆转变温度降低”这两个得分点。","erratum":"","sourceNumber":11,"id":"j0327","order":326,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"铸造时细化晶粒的方法有哪些？说明其原理。","answer":"（1）增加过冷度：过冷度增大时液态金属的结晶能力增强，形核率大大增加，而长大速度增加较少，因而晶粒细化。\n（2）变质处理：在液态金属结晶前加入细小的变质剂，使结晶时形核率 N 增加，晶粒细化。\n（3）振动处理：结晶时对液态金属附加机械振动、超声波振动或电磁振动，使已生长的晶粒破碎而细化，破碎的晶粒尖端又起净核作用，形核率增加，晶粒进一步细化。","explanation":"细化晶粒三法：①增大过冷度——形核率N的增长快于长大速度G，N/G 增大，晶粒细化；②变质处理——加入变质剂（Ti、V、Al等）形成大量非自发形核核心，提高形核率；③附加振动——机械/超声/电磁振动打碎正在生长的枝晶，碎枝晶又成为新的形核核心。答题必须写清“机理”，只写方法要扣分。","erratum":"","sourceNumber":12,"id":"j0328","order":327,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"珠光体、索氏体、屈氏体、贝氏体、马氏体；","answer":"珠光体：铁素体和渗碳体的机械混合物。索氏体：在650～600℃温度范围内形成层片较细的珠光体。屈氏体：在600～550℃温度范围内形成片层极细的珠光体。贝氏体：过饱和的铁素体和渗碳体组成的混合物。马氏体：碳在α-Fe中的过饱和固溶体。","explanation":"这五个都是组织而非相：P＝F＋Fe3C层片状混合物（A1~650℃）；S＝650~600℃形成的细片P；T＝600~550℃形成的极细片P；B＝过饱和F与Fe3C的混合物（550℃~Ms，分上、下贝氏体）；M＝碳在α-Fe中的过饱和固溶体（Ms以下）。片间距越细，强度硬度越高。","erratum":"","sourceNumber":13,"id":"j0329","order":328,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"奥氏体、过冷奥氏体、残余奥氏体；","answer":"奥氏体:碳在γ-Fe中形成的间隙固溶体.过冷奥氏体:处于临界点以下的不稳定的将要发生分解的奥氏体称为过冷奥氏体。残余奥氏体：M转变结束后剩余的奥氏体。","explanation":"三者都是奥氏体，区别在状态与稳定性：A是727℃以上稳定存在的相；过冷A是冷到A1以下尚未分解、热力学不稳定的A；残余A是马氏体转变结束后（室温）仍保留下来的A。判断依据是“温度区间＋稳定性”。","erratum":"","sourceNumber":14,"id":"j0330","order":329,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"退火、正火、淬火、回火、冷处理、时效处理（尺寸稳定处理）；","answer":"退火：将工件加热到临界点以上或在临界点以下某一温度保温一定时间后，以十分缓慢的冷却速度（炉冷、坑冷、灰冷）进行冷却的一种操作。正火：将工件加热到Ac3或Accm以上30～80℃，保温后从炉中取出在空气中冷却。淬火：将钢件加热到Ac3或Ac1以上30～50℃，保温一定时间，然后快速冷却（一般为油冷或水冷），从而得马氏体的一种操作。回火：将淬火钢重新加热到A1点以下的某一温度，保温一定时间后，冷却到室温的一种操作。冷处理：把冷到室温的淬火钢继续放到深冷剂中冷却，以减少残余奥氏体的操作。时效处理：为使二次淬火层的组织稳定，在110~150℃经过6~36小时的人工时效处理，以使组织稳定。","explanation":"六个概念要按“加热温度—冷却方式—目的”三要素作答：退火（Ac3或Ac1以上/以下，炉冷，均匀组织、降硬度、消应力）；正火（Ac3或Accm以上30~50℃，空冷，细化组织、提高硬度）；淬火（Ac3或Ac1以上30~50℃，水/油冷，得马氏体）；回火（A1 以下，保温后空冷，消应力、调性能）；冷处理（淬火后继续冷至-60~-80℃，减少残余A）；时效（低温长时间保温，稳定组织和尺寸）。","erratum":"","sourceNumber":15,"id":"j0331","order":330,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"淬火临界冷却速度（Vk），淬透性,淬硬性；","answer":"淬火临界冷却速度（Vk）：淬火时获得全部马氏体组织的最小冷却速度。淬透性：钢在淬火后获得淬硬层深度大小的能力。淬硬性：钢在淬火后获得马氏体的最高硬度。","explanation":"三个概念的本质区别：Vk是“冷却速度的临界值”（能否获得全M的判据）；淬透性是“钢的固有属性”（获得M层深浅的能力，取决于过冷A稳定性）；淬硬性是“M能达到的最高硬度”（只取决于M的含碳量）。答题时一定要点明“淬透性属钢的固有属性，与冷却介质无关”。","erratum":"","sourceNumber":16,"id":"j0332","order":331,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"试比较共析碳钢过冷奥氏体等温转变曲线与连续转变曲线的异同点。","answer":"首先连续冷却转变曲线与等温转变曲线临界冷却速度不同。其次连续冷却转变曲线位于等温转变曲线的右下侧，且没有C曲线的下部分，即共析钢在连续冷却转变时，得不到贝氏体组织。这是因为共析钢贝氏体转变的孕育期很长，当过冷奥氏体连续冷却通过贝氏体转变区内尚未发生转变时就已过冷到Ms点而发生马氏体转变，所以不出现贝氏体转变。","explanation":"异同点：①相同——都是描述过冷奥氏体转变的动力学曲线，都有P、B转变区（共析钢CCT无B 区）。②不同——CCT在TTT的右下方，因连续冷却使转变温度降低、时间推后；CCT的临界冷速比TTT大；共析钢连续冷却时贝氏体孕育期长，来不及转变就已降到Ms，故CCT上没有贝氏体转变区。这正是“共析钢连续冷却得不到贝氏体、必须等温淬火”的原因。","erratum":"","sourceNumber":17,"id":"j0333","order":332,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"析钢过冷奥氏体等温转变曲线三个转变区的转变产物是？（3分）","answer":"析钢过冷奥氏体等温转变曲线三个转变区的转变产物是：P B M。（3分）","explanation":"三个转变区及产物：高温区（A1~550℃，珠光体型转变）→P（细分S、T）；中温区（550℃~Ms，贝氏体型转变）→B上、B下；低温区（Ms以下）→M＋A′。题目中“析钢”应为“共析钢”。","erratum":"","sourceNumber":18,"id":"j0334","order":333,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"常见的热处理方法有哪些？（6分）","answer":"退火、正火、淬火、回火、表面热处理如感应淬火、化学热处理如渗碳，渗氮等。","explanation":"常见热处理分四类：①普通热处理——退火、正火、淬火、回火；②表面热处理——感应加热淬火、火焰加热淬火、激光淬火；③化学热处理——渗碳、渗氮、碳氮共渗、渗金属；④特殊热处理——真空热处理、形变热处理、冷处理。答题时分类列举比平铺直叙更易得满分。","erratum":"","sourceNumber":19,"id":"j0335","order":334,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"某过共析钢工件因终锻温度过高,其组织中出现了网状渗碳体,对工件的机性有何影响?采用何种工艺可将之削除.（6分）","answer":"某过共析钢工件因终锻温度过高,其组织中出现了网状渗碳体,将使工件的强度下降，力学性能变坏。可以采用正火的热处理方法来消除。","explanation":"网状渗碳体的危害：相当于在晶界形成连续的脆性硬壳，割裂基体连续性，使强度、塑性、韧性显著下降，淬火时还易沿网开裂。消除方法：正火——加热到Accm以上30~50℃使网溶入奥氏体，空冷时冷速快、二次渗碳体来不及沿晶界析出，得到细片珠光体；若网状严重，可先正火再球化退火。","erratum":"","sourceNumber":20,"id":"j0336","order":335,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"正火与退火的主要区别是什么？生产中应如何选择正火及退火？（6分）","answer":"与退火的区别是①加热温度不同，对于过共析钢退火加热温度在Ac1以上30～50℃而正火加热温度在Accm以上30～50℃。②冷速快，组织细，强度和硬度有所提高。当钢件尺寸较小时，正火后组织：S，而退火后组织：P。选择：（1）从切削加工性上考虑：切削加工性又包括硬度，切削脆性，表面粗糙度及对刀具的磨损等。一般金属的硬度在HB170～230范围内，切削性能较好。高于它过硬，难以加工，且刀具磨损快；过低则切屑不易断，造成刀具发热和磨损，加工后的零件表面粗糙度很大。对于低、中碳结构钢以正火作为预先热处理比较合适，高碳结构钢和工具钢则以退火为宜。至于合金钢，由于合金元素的加入，使钢的硬度有所提高，故中碳以上的合金钢一般都采用退火以改善切削性。（2）从使用性能上考虑如工件性能要求不太高，随后不再进行淬火和回火，那么往往用正火来提高其机械性能，但若零件的形状比较复杂，正火的冷却速度有形成裂纹的危险，应采用退火。（3）从经济上考虑正火比退火的生产周期短，耗能少，且操作简便，故在可能的条件下，应优先考虑以正火代替退火。","explanation":"区别有两点：①加热温度——过共析钢退火在Ac1以上30~50℃（不完全退火），正火在 Accm以上30~50℃；亚共析钢两者都在Ac3以上，温度相近；②冷却速度与组织——正火空冷冷速快，组织为S（细片P），强度和硬度较高；退火炉冷，组织为P，硬度较低。选择原则：低碳钢、中碳钢用正火（提高硬度、改善切削、周期短成本低）；高碳钢、工具钢、形状复杂易裂件用退火；从切削加工性看，硬度控制在HB170~230最佳。","erratum":"","sourceNumber":21,"id":"j0337","order":336,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"指出下列零件的锻造毛坯进行正火的主要目的及正火后的显微组织：（1）20钢齿轮（2）45钢小轴（3）T12钢锉刀","answer":"（1）目的：细化晶粒，均匀组织，消除内应力，提高硬度，改善切削加工性。组织：晶粒均匀细小的大量铁素体和少量索氏体。（2）目的：细化晶粒，均匀组织，消除内应力。组织：晶粒均匀细小的铁素体和索氏体。（3）目的：细化晶粒，均匀组织，消除网状Fe3CⅡ，为球化退火做组织准备，消除内应力。组织：索氏体和球状渗碳体。","explanation":"正火的三个作用：细化晶粒、均匀组织、消除内应力，并调整硬度改善切削加工性。组织：20钢（0.2%C）→F＋S（少量S，F为主）；45钢→F＋S；T12（过共析）→S＋球状（粒状）渗碳体，关键是正火先消除网状渗碳体，为球化退火作组织准备。原答案把T12写成“索氏体和球状渗碳体”可接受，但应点明“消除网状Fe3CⅡ”这一前提。","erratum":"","sourceNumber":22,"id":"j0338","order":337,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"确定下列工件的退火工艺,并说明其原因：(1)冷轧15钢钢板要求降低硬度.(2)正火态的T12钢钢坯要求改善其切削加工性.(3)锻造过热的60钢锻坯要求细化晶粒.（6分）","answer":"（1）完全退火；（2）球化退火；（3）等温退火。","explanation":"三问的答案：①冷轧15钢钢板已产生加工硬化，降低硬度应进行再结晶退火（600~650℃）；②正火态T12钢要改善切削性，须球化退火（750~770℃加热、690~700℃等温），使片状碳化物球化；③锻造过热的60钢要细化晶粒，须完全退火（Ac3+30~50℃加热后炉冷）或正火，通过重结晶细化。","erratum":"原答案（1）完全退火、（3）等温退火均有误。冷轧钢板应用再结晶退火；过热钢细化晶粒应用完全退火（或正火），等温退火主要解决周期与组织均匀性，不是细化晶粒的首选。","sourceNumber":23,"id":"j0339","order":338,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"一批45钢小轴试样（尺寸Φ15*10mm），因其组织、晶粒大小不均匀，需采用退火处理。拟采用以下几种退火工艺；（1）缓慢加热至700℃，保温足够时间，随炉冷却至室温；（2）缓慢加热至840℃，保温足够时间，随炉冷却至室温；（3）缓慢加热至1100℃，保温足够时间，随炉冷却至室温；问上述三种工艺各得到何种组织？若要得到大小均匀的细小晶粒，选何种工艺最合适？","answer":"（1）因其未达到退火温度，加热时没有经过完全奥氏体化，故冷却后依然得到组织、晶粒大小不均匀的铁素体和珠光体。（2）因其在退火温度范围内，加热时全部转化为晶粒细小的奥氏体，故冷却后得到组织、晶粒均匀细小的铁素体和珠光体。（3）因其加热温度过高，加热时奥氏体晶粒剧烈长大，故冷却后得到晶粒粗大的铁素体和珠光体。要得到大小均匀的细小晶粒，选第二种工艺最合适。","explanation":"①700℃未达到Ac1（727℃），未奥氏体化，组织仍是不均匀的F＋P，晶粒未改变；②840℃在Ac3 以上，完全奥氏体化且温度不高，冷却后得到均匀细小的F＋P；③1100℃远超Ac3，奥氏体晶粒剧烈粗化，冷却后得到粗大的F＋P（魏氏组织）。故选②。本题的核心是“加热温度决定奥氏体晶粒大小，奥氏体晶粒大小决定室温组织粗细”。","erratum":"","sourceNumber":24,"id":"j0340","order":339,"chapterId":"crystal","chapterIds":["crystal"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"确定下列钢件的退火方法，并指出退火目的及退火后的组织（4-6分，任意抽一个） 1）经冷轧后的15钢钢板，要求降低硬度；","answer":"再结晶退火。目的：使变形晶粒重新转变为等轴晶粒，以消除加工硬化现象，降低了硬度，消除内应力。细化晶粒，均匀组织，消除内应力，降低硬度以消除加工硬化现象。组织：等轴晶的大量铁素体和少量珠光体。 2）ZG35的铸造齿轮答：完全退火。经铸造后的齿轮存在晶粒粗大并不均匀现象，且存在残余内应力。因此退火目的：细化晶粒，均匀组织，消除内应力，降低硬度，改善切削加工性。组织：晶粒均匀细小的铁素体和珠光体。 3）锻造过热后的60钢锻坯；答：完全退火。由于锻造过热后组织晶粒剧烈粗化并分布不均匀，且存在残余内应力。因此退火目的：细化晶粒，均匀组织，消除内应力，降低硬度，改善切削加工性。组织：晶粒均匀细小的少量铁素体和大量珠光体。 4）具有片状渗碳体的T12钢坯；答：球化退火。由于T12钢坯里的渗碳体呈片状，因此不仅硬度高，难以切削加工，而且增大钢的脆性，容易产生淬火变形及开裂。通过球化退火，使层状渗碳体和网状渗碳体变为球状渗碳体，以降低硬度，均匀组织、改善切削加工性。组织：粒状珠光体和球状渗碳体。","explanation":"四种情况对应四种退火：①冷轧15钢（加工硬化）→再结晶退火，目的是消除加工硬化、恢复塑性，组织为等轴F＋少量P；②ZG35铸造齿轮（晶粒粗大不均、有内应力）→完全退火，细化晶粒、均匀组织、消除应力、改善切削，组织为细小F＋P；③锻造过热60钢→完全退火，重结晶细化晶粒，组织为少量F＋大量P；④片状渗碳体T12→球化退火，使片状、网状碳化物球化，降低硬度、改善切削、减小淬火变形开裂，组织为粒状P（球状珠光体）。","erratum":"","sourceNumber":25,"id":"j0341","order":340,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"某T12钢工件退火时,误当作45钢而进行了完全退火,其组织和性能会发生什么变化,因该工件切削加工困难,应采用什么热处理工艺来改善之。（6分）","answer":"某T12钢工件退火时,误当作 45钢而进行了完全退火,其组织中出现了网状渗碳体,将使工件的强度下降，力学性能变坏。可以采用正火的热处理方法来消除。","explanation":"T12（1.2%C）若误按45钢进行完全退火（加热到Ac3以上，实际对过共析钢相当于加热到 Accm以上），全部奥氏体化后随炉缓冷，二次渗碳体沿晶界大量析出成网，使强度、塑性、韧性显著下降，切削时还易崩刀。改善办法：先正火（Accm以上30~50℃空冷）消除网状渗碳体，再进行球化退火降低硬度、改善切削加工性。","erratum":"","sourceNumber":26,"id":"j0342","order":341,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"钢的淬透性与钢的淬硬性是否同一概念？为什么？（6分）","answer":"钢的淬透性与钢的淬硬性是两个完全不同的概念，两者没有必然的联系，（1分）钢的淬透性是指钢在淬火后获得淬硬层深度大小的能力，即获得马氏体多少的能力，（1分）主要取决于过冷奥氏体的稳定性，凡增加过冷奥氏体的稳定性的因素均提高钢的淬透性。1）合金成分因素：除元素Co以外，几乎所有合金元素溶入奥氏体后，都会增加奥氏体的稳定性，即C曲线向右移动，临界冷速减小，使钢在淬火时可以用较小的冷却方式冷却，从而得到更多的马氏体组织，淬透性提高；2）加热时的奥氏体化程度：加热温度越高、保温时间越长，则奥氏体的稳定性增加，淬透性提高。3）含碳量：共析成分比非共析成分碳钢的奥氏体的稳定性高，淬透性提高。（3分）而钢的淬硬性是指钢在淬火后获得马氏体的最高硬度，仅取决于马氏体的含碳量，含碳量越高则淬硬性越高。（1分）","explanation":"不是同一概念，务必分清：淬透性——获得马氏体层深浅的能力，取决于过冷奥氏体的稳定性（成分、奥氏体化条件），是钢的固有属性，与冷却介质、零件尺寸无关；淬硬性——淬火后马氏体能达到的最高硬度，只取决于马氏体含碳量。二者无必然联系：GCr15淬硬性高（HRC64）但淬透性中等，40Cr淬透性好（φ25mm可淬透）而淬硬性只有HRC55左右。","erratum":"","sourceNumber":27,"id":"j0343","order":342,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"试说明淬火钢中出现残余奥氏体的原因是什么,对其性能有何影响,采用什么工艺能将之消除。（6分）","answer":"淬火钢中出现残余奥氏体的原因是：马氏体转变是在一定温度范围内（Ms-Mf），连续冷却的任何停顿和减慢，都增大奥氏体的稳定性和残余奥氏体的量；另外马氏体形成时体积膨胀，对未转变的奥氏体构成大的压应力，也使马氏体转变不能进行到底，而总要保留一部分不能转变的（残余）奥氏体。残余奥氏体存在马氏体之间可改善钢的韧性。采用回火工艺能将之消除。","explanation":"残余奥氏体的成因有三：①M转变在Ms~Mf间进行，若Mf低于室温则转变不完全；②M形成时体积膨胀，对未转变A施加压应力，阻碍其继续转变；③冷速越慢、在Ms附近停留越久，A越稳定、残余量越多。影响：降低硬度、耐磨性和尺寸稳定性（使用中会转变引起变形），但少量（<5%）可提高韧性。消除：冷处理（-60~-80℃）＋低温回火，或多次高温回火（高速钢）。","erratum":"","sourceNumber":28,"id":"j0344","order":343,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"试说明为什么亚共析钢必须进行完全淬火,而过共析钢则只能进行不完全淬火（6分）。","answer":"亚共析钢必须在Ac3+30-50℃加热，进行完全淬火，并使淬火组织中保留一定数量的细小弥散碳化物颗粒，以提高其耐磨性。而过共析钢加热到Ac1+30-50℃进行不完全淬火，其原因在于：若碳化物完全熔入奥氏体中，马氏体中将出现过多的残余奥氏体，从而会造成多方面的害处，例如：碳含量过高，淬火后全部形成片状马氏体，脆性增加，且奥氏体增加，硬度下降;组织中会失去硬而耐磨的碳化物颗粒，令耐磨性降低等;而且淬火后会得到粗针状马氏体，显微裂纹增多，令钢的脆性增大;同时会令淬火应力增大，加大工件变形开裂倾向。","explanation":"亚共析钢加热到Ac3+30~50℃，完全奥氏体化，淬火后得到全部马氏体，组织均匀、强度高，故必须完全淬火；若只在Ac1~Ac3之间加热，会有先共析铁素体保留，淬火后出现软点、硬度不均。过共析钢则相反：只需加热到Ac1+30~50℃做不完全淬火，保留约5%~10%粒状渗碳体，既提高耐磨性，又因奥氏体含碳量降低而减少片状马氏体和残余奥氏体、降低开裂倾向；若加热到Accm以上，碳化物全部溶解，奥氏体含碳过高、晶粒粗大，淬火后片状马氏体粗大、显微裂纹多、残余A多，反而易开裂。","erratum":"","sourceNumber":29,"id":"j0345","order":344,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"高碳高合金钢工件淬火时极易开裂,采取什么措施可有效防止其开裂?（6分）","answer":"（1）合理设计零件结构；（2）淬火前进行退火或正火，以细化晶粒并使组织均匀化，减少淬火产生的内应力；（3）淬火加热时严格控制加热温度，防止过热使奥氏体晶粒粗化，同时也可减少淬火时的热应力；（4）采用适当的冷却方法；（5）淬火后及时回火，以消除应力，提高工件的韧性。","explanation":"防开裂措施按“设计—预处理—加热—冷却—后处理”五步答：①合理设计，避免尖角、壁厚突变，截面均匀过渡；②淬火前进行退火或正火，细化晶粒、均匀组织、消除应力；③严格控制加热温度并预热（分段加热），防止过热使奥氏体晶粒粗化；④采用分级淬火、等温淬火或双介质淬火，减小热应力和组织应力；⑤淬火后及时回火（高碳高合金钢应在1~2h内），消除应力、提高韧性。","erratum":"","sourceNumber":30,"id":"j0346","order":345,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"回火的目的是什么，常用的回火操作有哪几种？（6分）","answer":"回火的目的：1获得工件所需的组织。2稳定尺寸。3消除淬火内应力。回火的种类：低温回火；中温回火；高温回火","explanation":"回火三目的：①获得所需的组织与性能（低温回火→回火M，中温→回火T，高温→回火S）；②消除淬火内应力，防止变形开裂；③稳定组织和尺寸，保证精度。三种回火：低温150~250℃、中温350~500℃、高温500~650℃。","erratum":"","sourceNumber":31,"id":"j0347","order":346,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"T12钢工件经正常淬火后其表面硬度比60钢低的原因是什么？如何进一步提高其硬度？","answer":"原因是：淬火加热温度过低、保温时间不足、冷却速度过低、工件表面脱碳或预先热处理不当等。进一步提高其硬度的方法是将工件退火或正火后重新进行淬火。","explanation":"本题命题本身值得推敲：T12（1.2%C）正常淬火（780℃不完全淬火）后表层为高碳马氏体＋粒状碳化物，硬度应在HRC62~65，通常高于60钢（HRC58~60）；只有出现表层脱碳、加热不足、冷却不够等情况才会偏低。原答案罗列的是“T12淬火后硬度不足的一般原因”，与题干“为什么比60钢低”并不对应。规范的答法应是：①表层脱碳使含碳量降低；②加热温度偏低或保温不足，碳化物未充分溶解、奥氏体合金度低；③冷却速度不足，出现非马氏体组织；④原始组织不良（如网状渗碳体）。提高办法：退火或正火后重新按正常工艺淬火，并防止脱碳（盐浴炉、保护气氛）。","erratum":"","sourceNumber":16,"id":"j0348","order":347,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"选择下列零件的热处理方法，并编写简明的工艺路线（各零件均选用锻造毛坯，并且钢材具有足够的淬透性）：（1）某机床变速箱齿轮（模数 m=4），要求齿面耐磨，心部强度和韧性要求不高，材料选用 45 钢；（2）某机床主轴，要求有良好的综合机械性能，轴径部分要求耐磨（HRC50~55），材料选用 45 钢；（3）镗床镗杆，在重载荷下工作，精度要求极高，并在滑动轴承中运转，要求镗杆表面有极高的硬度，心部有较高的综合机械性能，材料选用 38CrMoAlA。","answer":"（1）下料→锻造→正火→粗加工→精加工→局部表面淬火＋低温回火→精磨→成品\n（2）下料→锻造→正火→粗加工→调质→精加工→局部表面淬火＋低温回火→精磨→成品\n（3）下料→锻造→退火→粗加工→调质→精加工→氮化→研磨→成品","explanation":"三问的共同思路是「预备热处理改善组织与加工性 + 最终热处理决定表面与心部性能」，差别在于心部性能要求不同，因而中间工序从正火升级为调质、表面强化从表面淬火换成氮化。\n（1）齿轮 m=4 属中模数、受力不大，45 钢锻造后正火即可细化晶粒、消除锻造应力并改善切削加工性，同时为正火索氏体（F+S）心部组织提供足够强度与韧性；因心部无更高要求，不必调质。最终在齿面局部表面淬火＋低温回火，得到高硬度回火马氏体表层（耐磨、抗接触疲劳），心部仍保持正火组织，且淬硬层浅、变形小，精磨后即可保证精度。\n（2）主轴要求良好综合机械性能，故粗加工后必须调质（淬火＋高温回火）获得回火索氏体，使强度、塑性与韧性配合最佳，并保证后续精加工尺寸稳定；轴径部位再局部表面淬火＋低温回火提高耐磨性（HRC50~55），心部仍为调质组织承受弯扭复合应力。若此处仍用正火，心部综合性能不足。\n（3）镗杆在重载、高精度下与滑动轴承配合，38CrMoAlA 是典型渗氮钢：含 Al、Cr、Mo 可在 500~560℃ 形成高硬度合金氮化物层。锻造后先退火（该钢含合金元素、锻后硬度较高，退火才能软化、改善切削与消除应力），粗加工后调质获得回火索氏体心部以保证较高的综合机械性能与刚性；精加工后氮化，表面硬度可达 HV950 以上（远高于表面淬火），且加热温度低、变形极小、无需重新淬火，正好满足极高精度要求；因氮化层薄而硬，氮化后只能研磨（或精磨微量），不能再用磨削去除较大余量。","erratum":"","sourceNumber":32,"id":"j0349","order":348,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"低碳钢、中碳钢及高碳钢是如何根据含碳量划分的？分别举例说明他们的用途？","answer":"低碳钢：含碳量0.0218%<wc<0.25%的钢；08、10、钢，塑性、韧性好，具有优良的冷成型性能和焊接性能，常冷轧成薄板，用于制作仪表外壳、汽车和拖拉机上的冷冲压件，如汽车车身，拖拉机驾驶室等；15、20、25钢用于制作尺寸较小、负荷较轻、表面要求耐磨、心部强度要求不高的渗碳零件，如活塞钢、样板等。中碳钢：含碳量为0.25%%≤wc≤0.6%的钢；30、35、40、45、50钢经热处理（淬火+高温回火）后具有良好的综合机械性能，即具有较高的强度和较高的塑性、韧性，用于制作轴类零件；高碳钢：含碳量大于0.6%的钢；60、65钢热处理（淬火+高温回火）后具有高的弹性极限，常用作弹簧。T7、T8、用于制造要求较高韧性、承受冲击负荷的工具，如小型冲头、凿子、锤子等。T9、T10、T11、用于制造要求中韧性的工具，如钻头、丝锥、车刀、冲模、拉丝模、锯条。T12、T13、钢具有高硬度、高耐磨性，但韧性低，用于制造不受冲击的工具如量规、塞规、样板、锉刀、刮刀、精车刀等。","explanation":"三类划分（按含碳量）：低碳钢0.0218%~0.25%（08、10、15、20、25）——塑性韧性好、可焊可冲压，做冲压件、渗碳件；中碳钢0.25%~0.60%（30、35、40、45、50）——调质后综合力学性能好，做轴类、齿轮、连杆；高碳钢>0.60%（60、65、T7~T13）——强度高、弹性好或硬度高，做弹簧、刃具、量具。","erratum":"原答案有一处错误：“60、65钢热处理（淬火＋高温回火）后具有高的弹性极限，常用作弹簧”。弹簧钢应为“淬火＋中温回火”，得到回火屈氏体；高温回火得到回火索氏体，弹性极限反而下降。","sourceNumber":33,"id":"j0350","order":349,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"常见的合金结构钢有哪些?写出其牌号,说明其一般使用时的热处理状态(即最终热处理)和用途。","answer":"常见的合金结构钢有：（1）低合金高强度结构钢：其中Q345是最常用的低合金高强度结构钢，一般不进行热处理，广泛用于制造桥梁、船舶、车辆、锅炉、压力容器、起重机械等钢结构件。（2）合金渗碳钢：20CrMnTi是最常用的合金渗碳钢，一般是渗碳后淬火、低温回火，用来工作中承受较强烈的冲击作用和磨损条件下的渗碳零件。（3）合金调质钢：40Cr是最常用的合金调质钢，其热处理工艺是调质，用来制造一些受力复杂的重要零件，如机床的主轴等。（4）合金弹簧钢：常用的合金弹簧钢的牌号有60Si2Mn、60Si2CrVA和50CrVA，热成形弹簧钢进行淬火、中温回火，冷成形弹簧钢只需进行依次去应力退火，合金弹簧钢主要用语制造各种弹性元件，如制作汽车的减震板弹簧等。（5）滚动轴承钢：目前应用最多的有：GCr15主要用于中小型滚动轴承；GCr15SiMn主要用于较大的滚动轴承，滚动轴承钢的热处理包括预备热处理（球化退火）和最终热处理（淬火+低温回火）。","explanation":"合金结构钢按用途分五类，答题时每类写“牌号＋最终热处理＋用途”：①低合金高强度钢Q345（不热处理，桥梁船舶车辆）；②合金渗碳钢20CrMnTi（渗碳＋淬火＋低温回火，汽车齿轮、活塞销）；③合金调质钢40Cr（调质，机床主轴、连杆螺栓）；④合金弹簧钢60Si2Mn、50CrVA（淬火＋中温回火，板簧、螺旋弹簧）；⑤滚动轴承钢GCr15（球化退火＋淬火＋低温回火，轴承套圈、滚珠）。","erratum":"","sourceNumber":34,"id":"j0351","order":350,"chapterId":"steel","chapterIds":["steel"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"比较20钢和T10钢的退火,正火,淬火组织的异同.","answer":"退火：20钢：奥氏体 T10 钢：珠光体正火：20钢：奥氏体 T10 钢：珠光体淬火：20钢：马氏体 T10 钢：马氏体","explanation":"本题考的是“退火/正火得到的是室温平衡或近平衡组织，绝不是奥氏体”。正确对比：退火——20钢为F＋P（F为主），T10为P＋Fe3CⅡ（球状）；正火——20钢为F＋S（S少量），T10为S＋Fe3CⅡ；淬火——20钢为低碳马氏体（板条M）＋少量F，T10为高碳马氏体＋粒状碳化物＋残余 A。","erratum":"原答案把退火、正火组织都写成“奥氏体”，属根本性错误：奥氏体只在727℃以上存在，室温下早已转变。应改为上方给出的F＋P、P＋Fe3CⅡ及F＋S、S＋Fe3CⅡ。","sourceNumber":35,"id":"j0352","order":351,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"现有下列零件及可供选择的材料,给各零件选择合适的材料,并选择合适的最终热处理方法(或使用状态).零件名称:自行车架,连杆螺栓,车厢板簧,滑动轴承,变速齿轮,机床床身,柴油机曲轴.（每三组为1题）可选材料:60Si2Mn,ZQSn6-6-3,QT600-2,T12A,40Cr,HT200,16Mn,20CrMnTi.","answer":"自行车架：16Mn 焊接连杆螺栓：40Cr 最终热处理方法：调质；车厢板簧：60Si2Mn 最终热处理方法：淬火+中温回火；滑动轴承：ZQSn6-6-3 使用状态：铸造；变速齿轮：20CrMnTi 最终热处理方法：渗碳后淬火、低温回火；机床床身：HT200 最终热处理方法：去应力退火；柴油机曲轴：QT600-2 最终热处理方法：等温淬火。","explanation":"七件选材与最终处理：自行车架16Mn（焊接，不热处理）；连杆螺栓40Cr（调质）；车厢板簧60Si2Mn（淬火＋中温回火）；滑动轴承ZQSn（铸造，不热处理）；变速齿轮20CrMnTi（渗碳＋淬火＋低温回火）；机床床身HT200（去应力退火/时效）；柴油机曲轴QT600-2（等温淬火或正火）。答题逻辑：先看载荷性质（冲击/疲劳/减摩）→再定材料类别→最后定热处理。","erratum":"","sourceNumber":36,"id":"j0353","order":352,"chapterId":"steel","chapterIds":["steel"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"选择适宜材料，并写出常用的热处理方法和最终组织（每两组为 1 题）。","answer":"表格答案见下方「材料选用对照表」。总体规律：先看载荷性质（冲击 / 疲劳 / 减摩），再定材料类别，最后定热处理。","explanation":"表格各行的判读依据：机床床身选HT200（减振、铸造性好），时效消除内应力，组织P＋F＋片状石墨；汽车后桥齿轮选20CrMnTi（表硬心韧），渗碳＋淬火＋低温回火，表层Cm＋M＋A′、心部F＋M；滚动轴承选GCr15，球化退火＋淬火＋低温回火，Cm＋M＋A′；锉刀选T12，同上；汽车板簧选60Si2Mn，淬火＋中温回火，T回；钻头选W18Cr4V，淬火＋三次560℃回火（不是“低温回火”），Cm＋M回＋A′；桥梁选16Mn，不热处理，F＋P；滑动轴承选ZSnSb11Cu6，不热处理，α＋SnSb＋Cu6Sn5；耐酸容器选1Cr18Ni9Ti，固溶处理，单相A；发动机曲轴选QT600-3，等温淬火＋高温回火，S回＋G 球。名称候选材料选用材料热处理方法最终组织机床床身 T10A, KTZ450-06, HT200 HT200 时效 P＋F＋G片汽车后桥齿轮 40Cr,20CrMnTi, 60Si2Mn 20CrMnTi 渗碳＋淬火＋低温回火表面Cm＋M＋A’ 心部 F＋M 滚动轴承 GCr15, Cr12, QT600-2 GCr15 球化退火＋淬火＋低温回火 Cm＋M＋A’ 锉刀 9SiCr,T12, W18Cr4V T12 球化退火＋淬火＋低温回火 Cm＋M＋A’ 汽车板簧 45,60Si2Mn, T1060Si2Mn 淬火＋中温回火 T回钻头 W18Cr4V，65Mn,20 W18Cr4V 淬火＋低温回火 Cm＋M＋A’ 桥梁 1Cr13,16Mn, Q19516Mn,不热处理 F＋P 滑动轴承 H70, ZSnSb11Cu6, T8 ZSnSb11Cu6 不热处理 a+SnSb 耐酸容器 Q235,1Cr18Ni9Ti, ZGMn131Cr18Ni9Ti 固溶处理 A 发动机曲轴 QT600-3,45, ZL101 QT600-3 等温淬火＋高温回火 S回＋G球","erratum":"表中两处需修正：①钻头的热处理应为“淬火＋560℃三次回火”，标为“低温回火”不妥（高速钢回火温度属高温回火）；②滑动轴承的组织应为α＋Sn Sb＋Cu6Sn5（原文只写a＋Sn Sb，漏了Cu6Sn5）。","sourceNumber":38,"table":{"head":["零件","候选材料","选用材料","热处理方法","最终组织"],"rows":[["机床床身","T10A、KTZ450-06、HT200","HT200","时效","P+F+片状石墨"],["汽车后桥齿轮","40Cr、20CrMnTi、60Si2Mn","20CrMnTi","渗碳＋淬火＋低温回火","表面 Cm+M+A′，心部 F+M"],["滚动轴承","GCr15、Cr12、QT600-2","GCr15","球化退火＋淬火＋低温回火","Cm+M+A′"],["锉刀","9SiCr、T12、W18Cr4V","T12","球化退火＋淬火＋低温回火","Cm+M+A′"],["汽车板簧","45、60Si2Mn、T10","60Si2Mn","淬火＋中温回火","T回"],["钻头","W18Cr4V、65Mn、20","W18Cr4V","淬火＋560℃ 三次回火","Cm+M回+A′"],["桥梁","1Cr13、16Mn、Q195","16Mn","不热处理","F+P"],["滑动轴承","H70、ZSnSb11Cu6、T8","ZSnSb11Cu6","不热处理","α+SnSb+Cu₆Sn₅"],["耐酸容器","Q235、1Cr18Ni9Ti、ZGMn13","1Cr18Ni9Ti","固溶处理","单相 A"],["发动机曲轴","QT600-3、45、ZL101","QT600-3","等温淬火＋高温回火","S回+G球"]]},"id":"j0354","order":353,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"为什么比较重要的大截面的结构零件如重型运输机械和矿山机器的轴类，大型发电机转子等都必须用合金钢制造？与碳钢比较，合金钢有何优缺点？","answer":"碳钢制成的零件尺寸不能太大，否则淬不透，出现内外性能不均，对于一些大型的机械零件，（要求内外性能均匀），就不能采用碳钢制作，比较重要的大截面的结构零件如重型运输机械和矿山机器的轴类，大型发电机转子等都必须用合金钢制造。(1)如上所述合金钢的淬透性高(2)合金钢回火抗力高碳钢淬火后，只有经低温回火才能保持高硬度，若其回火温度超过200℃，其硬度就显著下降。即回火抗力差，不能在较高的温度下保持高硬度，因此对于要求耐磨，切削速度较高，刃部受热超过200℃的刀具就不能采用碳钢制作而采用合金钢来制作。(3)合金钢能满足一些特殊性能的要求如耐热性、耐腐蚀性、耐低温性（低温下高韧性）。","explanation":"原因在于“淬透性”与“截面尺寸”的矛盾：碳钢的淬透性有限（水淬临界直径一般不超过φ25~30mm），大截面零件心部淬不透，会出现“表层硬、心部软”的性能不均，心部存在未转变的珠光体或铁素体，疲劳强度和冲击韧性大幅下降。合金钢因合金元素使C曲线右移、淬透性成倍提高（40CrNiMo 油淬临界直径可达φ70mm以上），可使整个截面获得均匀的回火索氏体。合金钢的优点：淬透性高、回火稳定性高（可在较高温度回火仍保持硬度）、可满足耐热耐蚀耐低温等特殊要求；缺点：价格贵、冶炼和热处理工艺复杂、容易产生白点与回火脆性。","erratum":"","sourceNumber":43,"id":"j0355","order":354,"chapterId":"steel","chapterIds":["steel"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"零件失效的三种基本类型？","answer":"过量变形失效；断裂失效；表面损伤失效","explanation":"零件失效三种基本类型：①过量变形失效（弹性变形过量——刚度不足；塑性变形过量——强度不足或过载）；②断裂失效（过载断裂、疲劳断裂、低应力脆断）；③表面损伤失效（磨损、接触疲劳、腐蚀、表面塑性变形）。答题时应各举一例（如轴弯曲、齿轮疲劳点蚀、曲轴断裂）。","erratum":"","sourceNumber":44,"id":"j0356","order":355,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"材料选择的三原则是？（3-6分）","answer":"材料选择的三原则是：使用性原则，工艺性原则，经济性原则。","explanation":"材料选择三原则：①使用性原则——首先满足力学性能（强度、塑性、韧性、硬度）和特殊性能（耐蚀、耐热、耐磨）要求，是首要原则；②工艺性原则——满足铸造、锻造、焊接、切削加工和热处理工艺性；③经济性原则——价格低、来源广、总成本（含加工和后续维护）最低。答题时可补一句“三原则冲突时，使用性优先，再兼顾工艺性与经济性”。","erratum":"","sourceNumber":45,"id":"j0357","order":356,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"essay","section":"简答题","question":"有一碳钢制支架刚度不足，有人要用热处理方法；有人要另选合金钢；有人要改变零件载面形状解决。哪种方法合理？为什么？","answer":"改变零件载面形状的方法合理（2分）。用热处理方法和另选合金钢都不合理，因为零件的刚度取决于二个方面：一是材料的弹性模量，另一个是零件的载面形状，而材料的弹性模量是相对稳定的力学性能指标外（即这一指标对材料的组织状态不敏感），用热处理方法无法改变，对于同一合金系当成分改变时，材料的弹性模量也不变化。（4分）","explanation":"合理的是“改变零件截面形状”。原因：刚度取决于材料的弹性模量E和截面惯性矩I。E是组织不敏感性能，热处理改变组织却不能改变E；更换合金钢（同一基体）E也基本不变（钢的E均在 200~210GPa）。只有增大截面惯性矩I（改变形状、增加壁厚或采用加强筋）才能有效提高刚度。这是一个“性能对组织不敏感”的经典例子。","erratum":"","sourceNumber":46,"id":"j0358","order":357,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"analysis","section":"综合分析","question":"在 Fe-Fe₃C 相图（下图）中数字所标的区域内填上相应的组织组成物。（每空 1 分，共 10 分）","answer":"1：F+A　2：A+Fe₃CⅡ　3：A+Fe₃CⅡ+Ld　4：Fe₃CⅠ+Ld　5：A\n6：F（或 F+Fe₃CⅢ）　7：F+P　8：P+Fe₃CⅡ\n9：P+Fe₃CⅡ+Ld′　10：Fe₃CⅠ+Ld′","explanation":"填组织要“先定成分区间、再定温度区间、最后按相区读取”。①液相线以上为L；②L＋A；③L＋Fe3CⅠ；④A单相区；⑤A＋Fe3CⅡ；⑥A＋Fe3CⅡ＋Ld；⑦F＋A；⑧F＋P（或F＋Fe3CⅢ）；⑨P＋Fe3CⅡ；⑩P＋ Fe3CⅡ＋Ld′；⑪Ld′＋Fe3CⅠ。本题答案总体正确，但第6区写“F＋Fe3CⅡ”需核对位置：若该区在0.0218%~0.77%且位于A1以下，应为F＋P；在0.0008%~0.0218%应为F＋Fe3CⅢ。","erratum":"原卷第 6 区答「F+Fe₃CⅡ」。该区位于 0.0218% 以左、A1 线以下，室温应为 F（或 F+Fe₃CⅢ）；只有 0.0218%~0.77% 且位于 A1 以下的第 7 区才是 F+P。","sourceNumber":1,"image":"assets/mech/q1-fe-c-regions.png","id":"j0359","order":358,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"analysis","section":"综合分析","question":"在 Fe-Fe₃C 相图（下图）上：(1) 写出①—⑥区的组织组成物，标明 A、E、C、S、P、K 各点的含碳量；(2) 说明含碳量 1.0% 的钢比含碳量为 0.5% 的钢硬度高。（10 分）","answer":"①区：F+P　②区：P　③区：P+Fe₃CⅡ\n④区：P+Fe₃CⅡ+Ld′　⑤区：Ld′　⑥区：Fe₃CⅠ+Ld′\nA 点 0　E 点 2.11%　C 点 4.3%　S 点 0.77%　P 点 0.0218%　K 点 6.69%\n(2) 含碳量升高使硬脆相渗碳体增多、铁素体减少，故 1.0% 的钢比 0.5% 的钢硬度高。","explanation":"①~⑥区的组织：①F＋P；②P；③P＋Fe3CⅡ；④P＋Fe3CⅡ＋Ld′；⑤Ld′；⑥Fe3CⅠ＋Ld′。特征点含碳量：A点0、E点2.11%、C点4.3%、S 点0.77%、P 点 0.0218%、K点6.69%。第（2）问的思路是：含碳量升高→渗碳体（硬脆相）增多、铁素体减少→硬度升高。","erratum":"原卷 E 点写作 2.14%（旧教材数据），现行教材与国家标准多用 2.11%，答题请统一用 2.11%。","sourceNumber":2,"image":"assets/mech/q2-fe-c-points.png","id":"j0360","order":359,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"analysis","section":"综合分析","question":"将共析钢件加热到770℃，保温足够时间，按图所示V1、V2、V3、V4、Vk的冷却速度冷至室温，各获得什么组织？（5-10分）","answer":"V1、P,V2、S,V3、T+M+A’,V4、M+A’,Vk、M+A’","explanation":"共析钢加热到770℃（A1以上）全部奥氏体化，随后按不同冷速连续冷却：V1（炉冷，最慢）→全部P；V2（空冷）→S（细片P）；V3（油冷，介于Vk与临界冷速之间）→T＋M＋A′；V4、Vk（水冷，≥Vk）→M＋A′。要点是“冷速决定转变温度，转变温度决定产物粗细”：冷速越快、过冷度越大、转变温度越低、组织越细，直至来不及扩散而形成马氏体。","erratum":"","sourceNumber":3,"image":"assets/mech/q3-cct-cooling.png","id":"j0361","order":360,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"analysis","section":"综合分析","question":"将共析钢件加热到770℃，保温足够时间，试问按图所示①、②、③、④、⑤的冷却速度冷至室温，各获得什么组织？（5-10分）","answer":"①、P ②、T③、B④、T+M+A’⑤ M+A’","explanation":"①最慢冷→P；②稍快→T（极细片P）；③冷到贝氏体区等温（或冷速恰在B 转变区停留）→B；④ 中速冷→T＋M＋A′；⑤快冷（≥Vk）→M＋A′。③与④的区别在于是否在贝氏体转变区停留足够时间：停留则得B，匆匆穿过则只能得到T＋M的混合组织。","erratum":"","sourceNumber":4,"image":"assets/mech/q4-cct-cooling.png","id":"j0362","order":361,"chapterId":"phase","chapterIds":["phase"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"analysis","section":"综合分析","question":"说明45钢试样（Φ10mm）经下列温度加热、保温并在水中冷却得到的室温组织：700℃，760℃，840℃， 1100℃。（4-10分）","answer":"700：因为它没有达到相变温度，因此没有发生相变，组织为铁素体和珠光体。 760：它的加热温度在Ac1_Ac3之间，因此组织为铁素体，马氏体和少量残余奥氏体。 840：它的加热温度在Ac3以上，加热时全部转变为奥氏体，冷却后的组织为马氏体和少量残余奥氏体。1100：因为它的加热温度过高，加热时奥氏体晶粒粗化，淬火后得到粗片状马氏体和少量残余奥氏体","explanation":"700℃：低于Ac1（727℃），未发生相变，组织仍为原始 F＋P。760℃：处于Ac1~Ac3之间，只有P 转变为A，组织为F＋A，水冷后F保留、A转变为M，故为 F＋M＋A′。840℃：高于Ac3，全部为A，水冷后为M＋A′（细晶）。1100℃：远高于Ac3，A晶粒剧烈粗化，水冷后为粗大片状 M＋A′，性能硬而脆。本题的关键是“加热温度→奥氏体化程度与晶粒大小→淬火组织”。","erratum":"","sourceNumber":5,"id":"j0363","order":362,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"analysis","section":"综合分析","question":"选择下列工件的淬火及回火温度，说明回火后获得的组织，并给出回火后的大致硬度。（1）45 钢小轴（要求综合机械性能）（2）60 钢弹簧（3）T12 钢锉刀","answer":"（1）45钢小轴（要求综合机械性能），B工件的淬火温度为850℃左右，回火温度为500℃～650℃ 左右，其回火后获得的组织为回火索氏体，A大致的硬度25～35HRC。（3分）（2）60钢弹簧，工件的淬火温度为850℃左右，回火温度为350℃～500℃左右，其回火后获得的组织为回火屈氏体，C大致的硬度40～48HRC。（3分）（3）T12钢锉刀，A工件的淬火温度为780℃左右，回火温度为150℃～250℃，其回火后获得的组织为回火马氏体，B大致的硬度60HRC。（4分）","explanation":"选配逻辑：淬火温度由含碳量定（亚共析钢Ac3+30~50℃约850℃，过共析钢Ac1+30~50℃约780℃）；回火温度由性能要求定（综合性能→高温回火，弹性→中温回火，高硬度耐磨→低温回火）。故（1）45钢小轴→B（850℃淬火＋500~650℃回火，回火索氏体，25~35HRC）；（2）60钢弹簧→C（850℃淬火＋350~500℃回火，回火屈氏体，40~48HRC）；（3）T12锉刀→A（780℃淬火＋150~250℃回火，回火马氏体，60HRC）。","erratum":"原卷把A、B两组的硬度写反了：应为“A 大致硬度60HRC、B大致硬度 25~35HRC、C大致硬度40~48HRC”。答案文字中“B……A大致的硬度25~35HRC”“A……B大致的硬度60HRC”即由此错位而来，结论虽对，标签需对调。","sourceNumber":6,"id":"j0364","order":363,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"analysis","section":"综合分析","question":"某40MnB钢主轴,要求整体有足够的韧性,表面要求有较高的硬度和耐磨性,采用何种热处理工艺可满足要求?简述理由.","answer":"采用正火、调质（预备热处理），以及淬火+低温回火（最终热处理）。（1）正火：主要为了消除毛坯的锻造应力，降低硬度以改善切削加工性，同时也均匀组织，细化晶粒，为以后的热处理做组织准备。（2）调质：主要使主轴具有高的综合力学性能。（3）淬火+低温回火：提高表面的硬度和耐磨性，而心部具有足够的韧性，其中低温回火的作用是消除淬火应力及减少脆性。","explanation":"40MnB主轴要求“整体韧性＋表面硬耐磨”，应选“调质＋表面淬火＋低温回火”的组合：①正火（预备热处理）——消除锻造应力、均匀细化组织、调整硬度改善切削；②调质——使心部获得回火索氏体，保证足够的强度与韧性；③表面淬火＋低温回火——使表层获得回火马氏体（HRC50~55），提高耐磨性和疲劳强度，心部仍保持良好韧性。注意表面淬火只能用于中碳钢，40MnB含碳0.4%正合适。","erratum":"","sourceNumber":7,"id":"j0365","order":364,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"analysis","section":"综合分析","question":"有一传动轴(最大直径φ20mm)受中等交变拉压载荷作用要求沿截面性能均匀一致,(1)选择合适的材料,(2)编制简明工艺路线,(3)说明各热处理工艺的主要作用(4)指出最终组织.可供选择材料:16Mn,20CrMnTi,45,40Cr,40CrNiMo,T12,”6”,”5”","answer":"（1）选用20CrMnTi （2）简明工艺路线：备料→锻造→正火→机械加工→渗碳→淬火、低温回火→机械加工。（3）热处理工艺的主要作用如下：正火：主要为了消除毛坯的锻造应力，降低硬度以改善切削加工性，同时也均匀组织，细化晶粒，为以后的热处理做组织准备。（组织：S+α(少量)）渗碳：为了保证传动轴表层的含碳量及渗碳层深度的要求。淬火+低温回火：提高表面的硬度和耐磨性，而心部具有足够的韧性，其中低温回火的作用是消除淬火应力及减少脆性。（4）表层组织为高碳M回+K(颗粒状)+A’(少量)，心部：","explanation":"关键限定条件是“沿截面性能均匀一致”。φ20mm的40Cr淬透性足够（油淬临界直径约φ25mm），调质后可获得整体均匀的回火索氏体，完全满足要求；而20CrMnTi渗碳只能做到“表硬心韧”，截面性能呈梯度分布，与“均匀一致”直接矛盾。故应选40Cr，工艺路线为：下料→锻造→正火→粗加工→调质→精加工→（必要时轴颈表面淬火＋低温回火）→磨削。","erratum":"原答案选20CrMn Ti＋渗碳，与题干“沿截面性能均匀一致”矛盾。正确应选40Cr并进行调质处理，最终组织为回火索氏体。","sourceNumber":8,"id":"j0366","order":365,"chapterId":"steel","chapterIds":["steel"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"analysis","section":"综合分析","question":"用20CrMn Ti制造汽车变速箱齿轮，要求齿面硬度HRC58-60，中心硬度HRC30-45，试写出加工工艺路线，并说明各热处理的作用目的。","answer":"加工工艺路线为：下料→锻造→正火→机械粗、半加工→渗碳+淬火+低温回火→喷丸→磨齿（4分）正火处理可使同批毛坯具有相同的硬度（便于切削加工），并使组织细化，均匀；（1-2分）渗碳后表面含碳量提高，保证淬火后得到高的硬度，提高耐磨性和接触疲劳强度；（1-2分）喷丸处理是提高齿轮表层的压力使表层材料强化，提高抗疲劳能力。（1-2分）","explanation":"20CrMnTi渗碳齿轮的工艺路线：下料→锻造→正火→粗、半精加工→渗碳→淬火＋低温回火→喷丸→磨齿。各工序作用：正火——均匀细化组织、调整硬度改善切削、为渗碳作组织准备；渗碳（900~930℃）——提高表层含碳量至0.8%~1.0%，保证淬火后表面高硬度；淬火＋低温回火——表层得高碳M＋粒状Cm＋少量A′（HRC58~62），心部得低碳M＋F，保证表硬心韧；喷丸——表层产生残余压应力，提高接触疲劳强度；磨齿——修正变形、保证精度。","erratum":"","sourceNumber":9,"id":"j0367","order":366,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"analysis","section":"综合分析","question":"某机床主轴选用45钢锻造毛坯,要求有良好的综合机械性能且轴径部分要耐磨(HRC 50-55),试为其编写简明的工艺路线，并说明各热处理工序的作用。","answer":"主轴的工艺路线：下料→锻造→正火→粗加工→调质→半精、精加工→表面淬火、低温回火→精加工。正火处理是为了得到合适的硬度，以便机械加工，同时为调质处理做好组织准备。调质处理是为了使主轴得到高的综合机械性能和疲劳强度，为了更好地发挥调质效果，将它安排在粗加工后进行。表面淬火是为了使轴径部分得到所需硬度，以保证装配精度和不易磨损。","explanation":"45钢主轴（综合性能＋轴颈耐磨）工艺路线：下料→锻造→正火→粗加工→调质→半精、精加工→轴颈表面淬火＋低温回火→精加工（磨削）。作用：正火——消除锻造应力、细化组织、改善切削；调质——获得回火索氏体，保证高的综合力学性能和疲劳强度，安排在粗加工之后是为了不把宝贵的调质层切除；表面淬火＋低温回火——使轴颈获得HRC50~55的高硬度耐磨层，同时消除淬火应力；磨削——保证尺寸精度。","erratum":"","sourceNumber":10,"id":"j0368","order":367,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"analysis","section":"综合分析","question":"车床主轴要求轴颈部位硬度为 HRC54~58，其余部位为 HRC20~25，其加工路线为：下料→锻造→正火→机加工→调质→机加工（精）→轴颈表面淬火→低温回火→磨加工。请指出：(1) 主轴应用的材料；(2) 正火的目的和大致工艺；(3) 调质的目的和大致工艺；(4) 表面淬火的目的；(5) 低温回火的目的以及轴颈表面与心部的组织。","answer":"(1) 45 钢。\n(2) 细化晶粒、消除应力；加热到 Ac3+50℃ 保温一段时间后空冷。\n(3) 使强度、硬度、塑性与韧性达到良好配合；淬火＋高温回火。\n(4) 提高轴颈表面硬度，保证装配精度与耐磨性。\n(5) 去除表面淬火的热应力；轴颈表面为 M+A′，心部为 S回。","explanation":"本题的核心是“预备热处理—最终热处理—表面处理”的分工：①材料45钢（中碳钢，可表面淬火，成本低）；②正火——细化晶粒、消除锻造应力、调整硬度改善切削，加热到Ac3+30~50℃（约850℃）保温后空冷；③调质——淬火＋高温回火（500~650℃），获得回火索氏体，使强度、塑性、韧性良好配合；④表面淬火——感应加热使轴颈表层奥氏体化后喷水急冷，得细马氏体，提高表面硬度与耐磨性；⑤低温回火（180~200℃）——消除表面淬火应力、降低脆性，表层组织为M＋A′，心部为S回。","erratum":"","sourceNumber":11,"id":"j0369","order":368,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"analysis","section":"综合分析","question":"选择下列零件的热处理方法，并编写简明的工艺路线（各零件均选用锻造毛坯，并且钢材具有足够的淬透性）：（5分，任意抽取一个）（1）某机床变速箱齿轮（模数m=4），要求齿面耐磨，心部强度和韧性要求不高，材料选用45钢；（2）某机床主轴，要求有良好的综合机械性能，轴径部分要求耐磨（HRC 50-55），材料选用45钢；（3）镗床镗杆，在重载荷下工作，精度要求极高，并在滑动轴承中运转，要求镗杆表面有极高的硬度，心部有较高的综合机械性能，材料选用38CrMoALA。","answer":"（1）下料→锻造→正火→粗加工→精加工→局部表面淬火+低温回火→精磨→成品（5分）（2）下料→锻造→正火→粗加工→调质→精加工→局部表面淬火+低温回火→精磨→成品（5分）（3）下料→锻造→退火→粗加工→调质→精加工→氮化→研磨→成品（5分）","explanation":"本题与简答题第33题完全相同（重复命题）。（1）齿轮：下料→锻造→正火→粗加工→精加工→齿部表面淬火＋低温回火→精磨；（2）主轴：下料→锻造→正火→粗加工→调质→精加工→轴颈表面淬火＋低温回火→精磨；（3）镗杆（38CrMoAlA）：下料→锻造→退火→粗加工→调质→精加工→氮化→研磨。判分点在于“预备热处理在最前、最终热处理在精加工前后、精密件最后用氮化”。","erratum":"","sourceNumber":12,"id":"j0370","order":369,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"analysis","section":"综合分析","question":"拟用T10制造形状简单的车刀，工艺路线为：锻造—热处理—机加工—热处理—磨加工（1）试写出各热处理工序的名称并指出各热处理工序的作用；（2）指出最终热处理后的显微组织及大致硬度；（3）制定最终热处理工艺规定（温度、冷却介质）","answer":"（1）工艺路线为：锻造—退火—机加工—淬火后低温回火—磨加工。退火处理可细化组织，调整硬度，改善切削加工性；淬火及低温回火可获得高硬度和耐磨性以及去除内应力。（2）终热处理后的显微组织为回火马氏体，大致的硬度60HRC。（3）T10车刀的淬火温度为780℃左右，冷却介质为水；回火温度为150℃～250℃。","explanation":"T10车刀：①工艺路线为锻造→（正火或）球化退火→机加工→淬火＋低温回火→磨加工，其中球化退火细化组织、降低硬度、改善切削并为淬火作组织准备；淬火＋低温回火获得高硬度、高耐磨性并消除应力。②最终组织为回火马氏体＋粒状渗碳体＋少量残余奥氏体，硬度约HRC60~62。③工艺规范：淬火加热780~800℃（Ac1+30~50℃），水淬（或水—油双介质淬火，减小变形开裂）；回火150~200℃，空冷。","erratum":"","sourceNumber":13,"id":"j0371","order":370,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"analysis","section":"综合分析","question":"某型号柴油机的凸轮轴，要求凸轮表面有高的硬度（HRC>50），而心部具有良好的韧性（Ak>40J），原采用45钢调质处理再在凸轮表面进行高频淬火，最后低温回火，现因工厂库存的45钢已用完，只剩15 钢，拟用15钢代替。试说明：（1）原45钢各热处理工序的作用；（2）改用15钢后，应按原热处理工序进行能否满足性能要求？为什么？（3）改用15钢后，为达到所要求的性能，在心部强度足够的前提下采用何种热处理工艺？","answer":"（1）正火处理可细化组织，调整硬度，改善切削加工性；调质处理可获得高的综合机械性能和疲劳强度；局部表面淬火及低温回火可获得局部高硬度和耐磨性。（2）不能。改用15钢后按原热处理工序会造成心部较软，表面硬，会造成表面脱落。（3）渗碳。","explanation":"（1）原45钢工序的作用：正火——细化组织、调整硬度改善切削；调质——获得回火索氏体，保证心部综合力学性能和疲劳强度；凸轮表面高频淬火＋低温回火——表面得回火马氏体（HRC>50），心部保持良好韧性（αk>40J）。（2）改用15钢按原工序不行：15 钢含碳仅0.15%，即使表面淬火，表层硬度也只能达到HRC30左右，远低于HRC50；若强行提高加热温度则晶粒粗大、变形开裂，且心部过软、表层硬壳易剥落。（3）正确方案：15钢应采用“渗碳＋淬火＋低温回火”，使表面增碳到0.8%~1.0%后再淬硬，心部仍为低碳M（韧性好），从而同时满足表面高硬度与心部高韧性。","erratum":"","sourceNumber":14,"id":"j0372","order":371,"chapterId":"perf","chapterIds":["perf"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"analysis","section":"综合分析","question":"用9SiCr钢制成圆板牙，其工艺路线为：锻造→球化退火→机械加工→淬火→低温回火→磨平面→开槽开口。试分析：①球化退火、淬火及回火的目的；②球化退火、淬火及回火的大致工艺。（10分）","answer":"球化退火是为了消除锻造应力，获得球状珠光体和碳化物，降低硬度以利于切削加工并为淬火做好组织准备，减少淬火时的变形与开裂（3分）；淬火及回火是为了获得回火马氏体，保证热处理后具有高硬度、高耐磨性。球化退火工艺：加热温度790—810℃，等温温度700—720℃；淬火工艺：加热温度850—870℃(油淬)；回火工艺；160—180℃。（4分）","explanation":"①目的：球化退火——消除锻造应力，使片状、网状碳化物球化，获得球状珠光体，降低硬度改善切削加工性并为淬火作组织准备，减小淬火变形开裂；淬火＋低温回火——获得回火马氏体＋粒状碳化物，保证高硬度（HRC60~62）、高耐磨性和尺寸稳定性，圆板牙的刃口和螺纹要求这些性能。②大致工艺：球化退火——加热790~810℃保温后，快冷至700~720℃等温 4~6h，再炉冷至500℃以下出炉；淬火——850~870℃（9SiCr的Ac1约770℃）加热，油淬（分级淬火更好，减小变形）；回火——160~180℃保温1~2h，空冷。","erratum":"","sourceNumber":15,"id":"j0373","order":372,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"},{"kind":"subjective","type":"analysis","section":"综合分析","question":"用40Cr钢制造模数为3的齿轮，其加工工艺路线为：下料（棒料）→锻造毛坯→热处理1→粗加工齿形→热处理2→精加工齿形→热处理3→磨削。请说明各热处理工艺的名称、目的、加热温度范围及冷却方式，并说明各热处理工序在加工工艺路线中位置安排的理由。（10-12分）","answer":"热处理1：安排在锻造之后，粗加工之前，应是预备热处理，其目的是消除前道工序（锻造）的缺陷，均匀化和细化组织，消除内应力，降低硬度，改善切削加工性能。达到此目的可采用完全退火或正火，由于所用材料为40Cr中碳合金钢，根据含碳量可以确定为正火。加热温度为Ac3 +30～50 ℃,保温后空冷。（2-4分）热处理2：齿轮工作时承受冲击，要求轮齿根部有高的综合力学性能，热处理2应为调质处理，因为钢的淬透性有限，调质处理组织的深度是一定的，为了避免把宝贵的调质处理组织层切除，调质处理应放在粗加工之后进行，后续精加工是为了修正调质处理引起的变形。淬火加热温度为Ac3 +30～50 ℃（约850℃），保温后油冷（40Cr为合金钢），淬火后进行高温（约500℃）回火。（4分）热处理3：齿轮工作时轮齿表面承受磨擦和挤压，轮齿表面要求有高的硬度，热处理3应为表面淬火，并随后进行低温回火（由于所用材料为中碳钢，不应采用渗碳处理）。热处理3后工件表面硬度很高，难于切削加工，所以应安排在精加工之后进行，最后的尺寸精度由磨削来完成。表面淬火可采用感应加热淬火，淬火加热温度为Ac3以上80～150 ℃，实际由通电加热时间控制。加热后水溶液喷射淬火，回火温度为180～200 ℃。生产中也可以采用自回火，即在工件淬火冷却到200 ℃左右时停止喷水，利用工件内部的余热来达到回火的目的。（4分）","explanation":"三道热处理的分工与位置理由：①热处理1（锻造后、粗加工前）——正火。目的：消除锻造应力、细化均匀组织、调整硬度改善切削加工性。40Cr为中碳合金钢，含碳0.4%，用正火即可（不必完全退火）。加热 Ac3+30~50℃（约850~870℃），保温后空冷。放在粗加工前是因为此时只要求改善切削性，且正火引起的变形可由后续加工切除。②热处理2（粗加工后、精加工前）——调质。目的：使轮齿根部获得回火索氏体，保证高的综合力学性能和接触疲劳强度。加热Ac3+30~50℃（约850℃），油淬，再500~650℃高温回火。放在粗加工后，是为了避免把淬透层（40Cr的有效淬透直径有限）在粗加工中切除；随后精加工用于修正调质变形。③热处理3（精加工后、磨削前）——齿面表面淬火＋低温回火。目的：提高齿面硬度和耐磨性。45钢以外的40Cr属中碳合金钢，适合感应加热表面淬火；若用渗碳则成本高、周期长，且中碳钢渗碳意义不大。表面淬火后硬度高、难切削，故安排在精加工之后，最终精度由磨削保证。加热Ac3以上80~150℃（由通电时间控制），喷水淬火，180~200℃回火（也可自回火）。","erratum":"","sourceNumber":16,"id":"j0374","order":373,"chapterId":"heat","chapterIds":["heat"],"sourceFile":"机械工程材料试题库（勘误版）"}]};if(typeof module!=="undefined"&&module.exports){module.exports=data;}else{root.QUESTION_BANK_MECH=data;}})(typeof globalThis!=="undefined"?globalThis:this);
